import{a as e}from"./jsx-runtime-Bzw2jH9X.js";var t=e({default:()=>n}),n=JSON.parse(`[{"id":"qx-c1-001","clusterId":"C","werkstueckRef":"C.1.1","stufe":1,"question":"Ein Freund sagt: „Wenn sich alle Galaxien voneinander entfernen, muss es irgendwo einen Mittelpunkt geben, wo der Urknall stattfand. Dort müsste man hinfliegen können.“ Welche Antwort trifft den Denkfehler am besten?","options":["Der Schluss ist richtig, denn eine gemeinsame Fluchtbewegung ist ohne einen zentralen Ausgangspunkt im Raum nicht zu erklären. Dieser liegt wahrscheinlich nur außerhalb des Bereichs, den wir beobachten können.","Der Schluss ist falsch, denn der Raum selbst dehnt sich überall zugleich aus. Einen Mittelpunkt, von dem alles wegfliegt und zu dem man fliegen könnte, gibt es nicht.","Der Schluss ist nur teilweise richtig: Es gab einen Mittelpunkt, doch durch die ständige Ausdehnung ist er inzwischen so weit entfernt, dass wir ihn mit keinem Teleskop mehr erkennen können.","Der Schluss ist falsch, denn die Galaxien entfernen sich nicht wirklich voneinander. Es handelt sich um den langsamen Zerfall eines bereits unendlich großen, kalten Raumes in einzelne Galaxien."],"correctIndex":1,"explanation":"Der Fehlschluss überträgt ein Alltagsbild auf den Kosmos: Bei einer Explosion im Raum fliegen Teile von einem Ort weg, und es gibt einen Mittelpunkt. Der Urknall war aber keine Explosion in einen bestehenden Raum hinein, sondern die Entstehung und Ausdehnung des Raumes selbst, nicht an einem Punkt, sondern überall zugleich. Dazu passt die Beobachtung: Je weiter eine Galaxie entfernt ist, desto schneller entfernt sie sich. Einen Mittelpunkt, von dem alles wegfliegt, gibt es nicht. Daher gibt es auch keinen Ort, zu dem man fliegen könnte. Gestützt wird das Modell von zwei unabhängigen Beobachtungen: der Expansion der Galaxien und der kosmischen Mikrowellen-Hintergrundstrahlung, die aus allen Richtungen des Himmels nahezu gleichmäßig messbar ist.","coreRule":"⚡ Wer aus „alles entfernt sich voneinander“ auf einen Mittelpunkt schließt, überträgt ein Alltagsbild (Explosion im Raum) auf einen Vorgang, bei dem der Raum selbst sich ausdehnt, überall zugleich.","quote":"Es war die Entstehung und Ausdehnung des Raumes selbst -- nicht an einem Punkt, sondern überall zugleich.","quoteLabel":"Merksatz:","beleg":"Werkstück C.1.1 (Kontext & Tiefe, „Keine Explosion im Raum“)","status":"entwurf","scenario":"In einer Diskussion über die Ausdehnung des Universums beobachtet ihr: Galaxien entfernen sich voneinander, und zwar umso schneller, je weiter sie entfernt sind. Dein Freund schließt daraus auf einen zentralen Explosionsort.","kurz":"Der Urknall war keine Explosion an einem Ort im Raum, sondern die Ausdehnung des Raumes selbst, überall zugleich. Das Alltagsbild der Explosion verführt zum Schluss auf einen Mittelpunkt, zu dem man fliegen könnte. Den gibt es nicht.","prueffrage":"Wie sähe die Fluchtbewegung für Beobachter in einer ganz anderen Galaxie aus, und was würde das über einen Mittelpunkt verraten?","rueckmeldung":[{"option":0,"text":"Eine gemeinsame Fluchtbewegung scheint einen Ausgangspunkt zu verlangen. Doch dehnt sich der Raum überall zugleich, sieht jeder Beobachter alle Galaxien von sich wegfliegen, umso schneller, je weiter sie weg sind; ein Mittelpunkt ist nicht nötig."},{"option":2,"text":"Dass sich die Abstände durch die Ausdehnung vergrößern, stimmt. Einen Mittelpunkt gab es aber nie, auch keinen versteckten: Der Urknall ereignete sich nicht an einem Ort, sondern überall zugleich."},{"option":3,"text":"Dass der Schluss auf ein Zentrum falsch ist, trifft zu. Doch die Galaxien entfernen sich beobachtbar voneinander, und für einen Zerfall eines kalten Raums in Galaxien gibt es keinen Beleg: Ein Fehler wird hier durch eine unbelegte Behauptung ersetzt."}],"familie":"schluss-pruefen","fertigkeit":"F2"},{"id":"qx-c1-002","clusterId":"C","werkstueckRef":"C.1.1","stufe":2,"question":"Der Heiler soll nennen, über welche der vier fundamentalen Kräfte (Gravitation, Elektromagnetismus, starke und schwache Kernkraft) seine „Energie“ übertragen werden soll. Er kann keine nennen, die auf seine Beschreibung passt. Was folgt daraus für seine Behauptung?","scenario":"Bei einem Heilerabend sagt jemand, er lenke „kosmische Heilenergie“ in deine Hände.","options":["Seine „Energie“ ist mit hoher Wahrscheinlichkeit keine physikalische Größe, sondern eine bildhafte Redeweise; er müsste für eine neue Kraft außergewöhnliche Belege liefern.","Seine „Energie“ ist eine fünfte Kraft, die die Physik noch nicht gefunden hat; solange man ihre Existenz nicht ausschließen kann, gilt sie als gleichwertig.","Seine „Energie“ ist eine Unterform des Elektromagnetismus, weil dieser für fast alle Alltagsphänomene verantwortlich ist und deshalb alles Spürbare erklärt.","Seine „Energie“ ist unbewiesen, aber vorläufig akzeptabel, solange niemand ihre Nichtexistenz nachgewiesen hat."],"correctIndex":0,"explanation":"Jede bisher beobachtete Wechselwirkung lässt sich auf die vier bekannten Grundkräfte zurückführen. Wer behauptet, eine „Energie“ zu lenken, behauptet etwas Physikalisches und muss sagen können, über welche dieser Kräfte sie übertragen werden soll; kann er das nicht, ist das Wort wahrscheinlich nur bildhaft gemeint. Eine neue, fünfte Kraft wäre denkbar, doch Präzisionsexperimente suchen gezielt danach und lassen ihr bislang nur winzige Spielräume; wer sie behauptet, muss außergewöhnliche Belege liefern. Dass sich etwas nicht ausschließen lässt, macht es deshalb weder gleichwertig noch vorläufig akzeptabel. Und dass der Elektromagnetismus fast alle Alltagsphänomene trägt, macht nicht jede behauptete Energie elektromagnetisch; der Heiler müsste zeigen, was an seiner „Energie“ elektromagnetisch sein soll.","coreRule":"⚡ Nenne die Kraft: Passt keine der vier fundamentalen Kräfte, ist „Energie“ eine Metapher und keine Physik – und wer eine neue Kraft behauptet, trägt die Beweislast.","beleg":"Werkstück C.1.1 (Anwendung & Relevanz, „Gegen die Esoterik & ‚Energieheilung‘“, mit Verweis auf D.4.1; Kontext & Tiefe, Absatz zur ‚fünften Kraft‘); Fn. gl-c-dunkle-energie (Adelberger u. a. 2003, Suche nach einer fünften Kraft)","status":"entwurf","quote":"","quoteLabel":"","kurz":"Er behauptet etwas Physikalisches, kann aber keine Kraft nennen, die dazu passt. Dann ist „Energie“ wohl bildhaft gemeint. Eine neue Kraft wäre zwar denkbar, bräuchte aber außergewöhnliche Belege, und nur ihre Nichtwiderlegung genügt dafür nicht.","prueffrage":"Was würde sich an Messgeräten ändern, wenn tatsächlich etwas in deine Hände fließt?","rueckmeldung":[{"option":1,"text":"Eine neue Kraft ist tatsächlich denkbar, und die Physik sucht sogar gezielt nach solchen Kräften. Dass man etwas nicht ausschließen kann, macht es aber nicht gleichwertig: Belege fehlen, und Präzisionsexperimente lassen nur winzige Restspielräume."},{"option":2,"text":"Der Elektromagnetismus steckt tatsächlich in fast allen Alltagsphänomenen. Daraus folgt aber nicht, dass die behauptete Energie dazugehört; gerade weil er so breit wirkt, müsste der Heiler zeigen, was an seiner „Energie“ elektromagnetisch sein soll."},{"option":3,"text":"Eine Nichtexistenz lässt sich selten nachweisen, das stimmt. Deshalb liegt die Beweislast bei dem, der etwas behauptet. „Noch nicht widerlegt“ reicht nicht, um eine Aussage vorläufig zu akzeptieren, schon gar nicht bei etwas Außergewöhnlichem."}],"familie":"begriff-messbar-machen","fertigkeit":"F1"},{"id":"qx-c1-003","clusterId":"C","werkstueckRef":"C.1.1","stufe":3,"question":"Welche der folgenden Äußerungen ist ein Fehlschluss, der aus einer offenen Frage einen Beleg gegen ein gut gestütztes Modell machen will?","options":["„Die Physik kann nicht sagen, was vor dem Urknall war. Also ist die ganze Theorie widerlegt, und eine übernatürliche Erklärung muss an ihre Stelle treten.“","„Ob hinter dem Anfang des Universums ein Sinn oder ein erster Beweger steht, ist eine Frage für Philosophie und Religion und lässt sich nicht im Experiment prüfen.“","„Was vor dem Urknall war, ist offen. In extremen Zuständen wie einer Singularität könnten Regeln gelten, die ganz anders sind als in unserem Alltag.“","„Die Natur der Dunklen Energie ist noch nicht verstanden. Ihr Zahlenwert ist aber präzise vermessen, und die Forschung arbeitet weiter daran.“"],"correctIndex":0,"explanation":"Der Satz schließt von einer offenen Frage auf die Falschheit des gesamten Modells. Das ist ein Argument aus Unwissenheit: „Das weiß man nicht, also ist das übrige Wissen hinfällig und meine Erklärung gewinnt.“ Dieser Schluss trägt nicht. Ein Modell wird durch seine Belege getragen, bei der Urknall-Theorie vor allem durch die beobachtete Expansion der Galaxien und die kosmische Hintergrundstrahlung. Eine ungeklärte Frage am Rand ändert an diesen Belegen nichts. Zudem wäre die Ersatzerklärung dadurch nicht gestützt, denn sie müsste selbst Belege liefern. Die anderen Sätze sind unproblematisch. Philosophische oder religiöse Fragen nach einem Sinn oder ersten Beweger sind legitim, solange sie nicht als wissenschaftliche Argumente getarnt werden, um belegte Modelle zu leugnen. Auch ehrlich benannte Lücken sind kein Fehler, solange sie als Lücken behandelt werden und nicht als Freibrief.","coreRule":"⚡ Eine offene Frage am Rand eines Modells ist kein Beleg gegen das Modell. Wer das Modell kippen will, muss zeigen, dass es die gut belegten Beobachtungen schlechter erklärt, nicht nur auf eine Lücke zeigen.","beleg":"Werkstück C.1.1 (Der Kipppunkt; Red Flags, Argument aus Unwissenheit)","status":"entwurf","scenario":"In einer Diskussion über den Ursprung des Universums fallen vier Sätze. Es geht um die Frage, wie man mit offenen Fragen eines wissenschaftlichen Modells umgehen sollte.","kurz":"Eine offene Frage am Rand widerlegt kein Modell, das auf Belegen wie der Expansion der Galaxien und der Hintergrundstrahlung ruht. Der Fehler: aus „das weiß man nicht“ wird „also stimmt meine Erklärung“, die selbst Belege bräuchte.","prueffrage":"Welche Beobachtungen stützen die Theorie, und ändert sich an ihnen etwas, nur weil eine Frage offen ist?","rueckmeldung":[{"option":1,"text":"Hier wird eine Frage nach Sinn oder erstem Beweger gestellt, die sich tatsächlich nicht im Experiment prüfen lässt. Das Modell wird dabei nicht angegriffen und nichts an seine Stelle gesetzt, deshalb liegt kein Fehlschluss vor."},{"option":2,"text":"Die Lücke wird als offen benannt, und die Vermutung über andere Regeln bleibt vorsichtig („könnten“). Weder wird das Modell widerlegt noch eine Ersatzerklärung durchgesetzt, eine ehrlich benannte Lücke ist hier kein Fehler."},{"option":3,"text":"Auch dieser Satz nennt eine Wissenslücke, hält aber zugleich fest, was gesichert ist, nämlich den präzise vermessenen Zahlenwert. Er behandelt die Lücke als Aufgabe der Forschung und nicht als Grund, das Modell zu verwerfen."}],"familie":"unwissen-ist-kein-beleg","fertigkeit":"F2"},{"id":"qx-c1-004","clusterId":"C","werkstueckRef":"C.1.1","stufe":4,"question":"Welche Antwort deckt den Denkfehler in dieser Rechtfertigung am genauesten auf?","scenario":"Ein Esoteriker kontert: „Selbst die Physik gibt zu, dass sie Dunkle Energie nicht versteht – dann darf ich auch meine unsichtbare Lebensenergie annehmen.“","options":["Unwissen ist für beides ein Freibrief, solange niemand die Annahme endgültig widerlegen kann, weshalb die Beweislast bei den Kritikern liegt.","Die Dunkle Energie ist faktisch eine fünfte Naturkraft, also wäre eine Lebensenergie nur eine weitere unentdeckte Kraft derselben Art.","Die Dunkle Energie wird gezielt beobachtet und gemessen, die Lücke ist also begrenzt und eindeutig beschrieben; eine bloß behauptete Lebensenergie hat nichts Vergleichbares.","Weil die Dunkle Energie vollständig verstanden ist, darf nur Erklärtes angenommen werden, und die Lebensenergie fällt deshalb aus dem Raster."],"correctIndex":2,"explanation":"Der Schluss „Die Physik versteht etwas nicht, also darf ich irgendetwas Unsichtbares annehmen“ macht aus einer Wissenslücke einen Freibrief. Die Dunkle Energie ist aber nicht aus der Luft gegriffen: Supernova-Messungen zeigen eine beschleunigte Ausdehnung des Universums (Riess u. a. 1998; Perlmutter u. a. 1999), und ihr Anteil am Universum ist vermessen, nach den Planck-Daten von 2018 rund 68 %. Ihre Natur ist keineswegs verstanden, die Lücke selbst aber genau umrissen und überprüfbar; einer „Lebensenergie“ ohne Messgröße und ohne beobachtbaren Effekt fehlt genau das. Die Beweislast liegt bei dem, der eine Behauptung aufstellt, nicht bei den Kritikern. Als fünfte Naturkraft ist die Dunkle Energie zudem nicht belegt, sie taugt also auch nicht als Vorbild für eine weitere unentdeckte Kraft.","coreRule":"⚡ Eine Lücke im Wissen, die genau vermessen ist, trägt eine Hypothese; eine Lücke, die nur als Platz für eine Behauptung dient, trägt nichts.","beleg":"Werkstück C.1.1 (Kontext & Tiefe); Fn. gl-c-dunkle-energie (Riess u. a. 1998; Perlmutter u. a. 1999; Planck Collaboration 2020, A&A 641, A6)","status":"entwurf","kurz":"Die Dunkle Energie ist zwar unverstanden, aber ihre Wirkung wird gemessen und die Lücke ist genau umrissen. Eine Lebensenergie ohne Messgröße hat nichts Vergleichbares. Unwissen allein rechtfertigt also keine beliebige Annahme.","prueffrage":"Was genau gibt die Physik zu, wenn sie sagt, sie verstehe die Dunkle Energie nicht?","rueckmeldung":[{"option":0,"text":"Dass niemand die Lebensenergie endgültig widerlegen kann, wirkt wie ein Freibrief. Die Beweislast trägt aber, wer etwas behauptet, nicht die Kritik, und die Dunkle Energie ist keine freie Annahme, sondern an Messungen gebunden."},{"option":1,"text":"Die Dunkle Energie zeigt sich in Messungen, ihre Natur ist aber offen. Als fünfte Naturkraft ist sie nicht belegt. Selbst dann fehlte der Lebensenergie jede Messgröße, die sie in eine Reihe mit ihr stellen würde."},{"option":3,"text":"Die Natur der Dunklen Energie ist gerade nicht verstanden. Der Unterschied liegt nicht im Verstehen, sondern darin, dass ihre Wirkung messbar und die Lücke umrissen ist. Dieses Kriterium fehlt der Lebensenergie."}],"familie":"unwissen-ist-kein-beleg","fertigkeit":"F2"},{"id":"qx-c1-005","clusterId":"C","werkstueckRef":"C.1.2","stufe":1,"question":"Was ist an dem Schluss deiner Freundin fehlerhaft?","options":["Sie betrachtet nur das Zimmer. Das Aufräumen kostet Energie, und dabei entsteht anderswo Unordnung, sodass die Gesamtunordnung nicht sinkt.","Sie unterschätzt die Dauer. Bei sorgfältigem Aufräumen bleibt die Ordnung dauerhaft erhalten, sodass die Unordnung insgesamt sinkt.","Sie verwechselt Energie mit Unordnung. Beim Aufräumen geht Energie verloren, und dieser Verlust macht die Umgebung unordentlicher.","Sie hat recht, solange weder Wärme noch Stoff den Raum verlassen. Dort lässt sich die Unordnung durch Aufräumen insgesamt dauerhaft verringern."],"correctIndex":0,"explanation":"Entropie misst, auf wie viele Arten ein System im Kleinen angeordnet sein kann; in einem abgeschlossenen System, das mit seiner Umgebung weder Energie noch Stoff austauscht, nimmt sie insgesamt nie ab. Lokale Ordnung entsteht nur unter Energieeinsatz, und dabei entsteht anderswo mehr Unordnung, etwa als Wärme aus Muskeln und Staubsauger. Gemessen daran zählt die Anordnung von Kleidung und Büchern thermodynamisch sogar verschwindend wenig; die Alltagsordnung dient hier nur als Bild. Der Schluss „Ordnung im Zimmer heißt weniger Unordnung insgesamt“ ist deshalb falsch. Auch die Alternativen scheitern: Selbst dauerhafte Ordnung im Zimmer ändert nichts an der anderswo entstandenen Unordnung, in einem abgeschotteten Raum bleibt die Wärme der Arbeit eben im Raum, und Energie geht bei einer Umwandlung nicht verloren, sondern ändert nur ihre Form.","coreRule":"⚡ Lokale Ordnung gibt es nur auf Kosten von mehr Unordnung anderswo: Rechne immer die ganze Bilanz, nicht nur das Zimmer.","quote":"","quoteLabel":"","beleg":"Werkstück C.1.2 (Das aufgeräumte Zimmer; Kontext & Tiefe, Erster und Zweiter Hauptsatz)","status":"entwurf","scenario":"Du räumst eine Stunde lang dein Zimmer auf: Kleidung gefaltet, Bücher sortiert, Boden gesaugt. Deine Freundin sagt: „Ich habe Ordnung geschaffen, also hat die Unordnung im Universum abgenommen.“","kurz":"Der Schluss springt vom Zimmer aufs Ganze: Ordnung entsteht dort nur unter Einsatz von Energie, und dabei entsteht anderswo mehr Unordnung, etwa als Wärme. Die Gesamtunordnung nimmt deshalb nicht ab, auch wenn das Zimmer ordentlicher ist.","prueffrage":"Was verbraucht der Staubsauger, und was gibt dein Körper während der Stunde Arbeit an die Luft ab?","rueckmeldung":[{"option":1,"text":"Gründliches Aufräumen wirkt, als bliebe die Ordnung. Doch selbst wenn sie hielte: Schon beim Aufräumen ist anderswo mehr Unordnung entstanden, als im Zimmer verschwand, die Gesamtunordnung ist also nicht gesunken."},{"option":2,"text":"Daran stimmt: Aufräumen kostet Energie, und anderswo wächst die Unordnung. Energie geht dabei aber nicht verloren, sie ändert nur ihre Form, und Unordnung ist keine Energie."},{"option":3,"text":"Ein abgeschotteter Raum wirkt, als bliebe die Ordnung darin. Doch gerade wenn weder Wärme noch Stoff hinein- oder hinausgelangt, sinkt die Gesamtunordnung dort nie: Beim Aufräumen entsteht Wärme, und die steigert sie mehr, als das Ordnen sie senkt."}],"familie":"bilanz-pruefen","fertigkeit":"F1"},{"id":"qx-c1-006","clusterId":"C","werkstueckRef":"C.1.2","stufe":2,"question":"Welche Antwort prüft den Einwand richtig?","scenario":"In einer Diskussion sagt jemand: „Mein Kaffee kühlt im Zimmer ab, und dabei sinkt seine Entropie. Damit ist bewiesen, dass der Satz ‚Die Gesamtentropie nimmt nie ab' nicht stimmen kann.“ Das Zimmer ist ein abgeschlossenes System aus Kaffee und Raumluft.","options":["Der Einwand trifft zu, denn der Satz gilt nur für Gase, und bei Flüssigkeiten wie Kaffee darf die Entropie sinken.","Der Einwand ist ein Fehlschluss, denn er betrachtet nur den Kaffee; der kühle Raum gewinnt mehr Entropie, als der Kaffee verliert, und die Summe beider steigt.","Der Einwand ist ein Fehlschluss, denn die Wärme des Kaffees wandelt sich vollständig in Bewegungsenergie der Luft um, und dabei entsteht Ordnung.","Der Einwand ist ein Fehlschluss, denn die Wärme geht beim Abkühlen verloren, und verlorene Energie trägt keine Entropie mehr."],"correctIndex":1,"explanation":"Der Satz gilt für das abgeschlossene Gesamtsystem, nicht für jeden Teil einzeln. Der Einwand betrachtet nur den Kaffee und übersieht die Umgebung: Die Wärme verteilt sich, bis Tasse und Raum gleich warm sind, und dabei gewinnt der kühlere Raum mehr Entropie, als der Kaffee verliert. Das lässt sich nachrechnen: Gleichen sich zwei gleiche Stahlkörper (Wärmekapazität je 1800 J/K, rund 4 kg Stahl), die nur miteinander Wärme austauschen, von 400 K und 300 K auf je 350 K an, verliert der heiße rund 240 J/K Entropie, der kalte gewinnt rund 277 J/K, netto steigt die Entropie um rund 37 J/K. Der Satz unterscheidet dabei nicht zwischen Gasen und Flüssigkeiten. Die Wärme landet als ungeordnete Bewegung der Luftteilchen im Raum, es entsteht also keine Ordnung, und sie geht auch nicht verloren, sondern trägt dort Entropie, während die Gesamtenergie gleich bleibt.","coreRule":"⚡ Lokal darf die Entropie sinken – solange sie in der Umgebung mehr zunimmt. Prüfe bei „Das widerspricht dem Gesetz“ immer, ob das ganze System betrachtet wurde.","beleg":"Werkstück C.1.2; Fn. gl-c-waermefluss (Ling/Moebs/Sanny 2016, Abschn. 4.6 Beispiel 4.5 und 4.7 Beispiel 4.9)","status":"entwurf","kurz":"Der Satz gilt für das abgeschlossene Gesamtsystem, nicht für jeden Teil einzeln. Der Kaffee verliert zwar Entropie, doch der kühlere Raum gewinnt mehr, als der Kaffee verliert, sodass die Summe steigt.","prueffrage":"Wohin geht die Wärme, die der Kaffee abgibt, und wie verändert sich dabei die Raumluft?","rueckmeldung":[{"option":0,"text":"Dass die Entropie einer Flüssigkeit sinken kann, stimmt, wenn sie Wärme abgibt. Das gilt aber ebenso für Gase, und der Satz bezieht sich nicht auf Stoffe, sondern auf das abgeschlossene Gesamtsystem. Dort steigt die Summe."},{"option":2,"text":"Der Einwand ist tatsächlich ein Fehlschluss. Doch die Wärme landet als ungeordnete Bewegung der Luftteilchen im Raum, und daraus entsteht keine Ordnung: Die Entropie der Luft steigt stärker, als die des Kaffees sinkt."},{"option":3,"text":"Dass der Einwand ein Fehlschluss ist, stimmt. Die Wärme geht jedoch nicht verloren: Sie fließt in den Raum und trägt dort Entropie. Energie verschwindet nicht, ihre Gesamtmenge bleibt gleich."}],"familie":"bilanz-pruefen","fertigkeit":"F1"},{"id":"qx-c1-007","clusterId":"C","werkstueckRef":"C.1.2","stufe":3,"question":"Ein Redner sagt: „Der menschliche Körper ist hochgeordnet. Das widerlegt den Zweiten Hauptsatz der Thermodynamik und beweist eine Lebenskraft.“ Welcher Denkfehler steckt in diesem Schluss?","options":["Er nimmt an, der Zweite Hauptsatz gelte nur für unbelebte Systeme, und übersieht, dass lebende Zellen Entropie im Inneren speichern und abbauen können.","Er übersieht, dass sich Ordnung von selbst bildet, sobald genug Zeit vergeht, weil Ordnung über lange Zeiträume der wahrscheinlichste Zustand eines Systems ist.","Er übersieht, dass ein einzelner Körper seine Entropie dauerhaft senken darf, ohne Energie aufzunehmen, weil der Hauptsatz nur einen Anstieg im Mittel verlangt.","Er betrachtet nur den Körper und nicht die Umgebung, denn Lebewesen halten ihre Ordnung durch ständige Energieaufnahme und erhöhen dabei die Entropie ihrer Umgebung."],"correctIndex":3,"explanation":"Der Zweite Hauptsatz verlangt nur, dass die Gesamtentropie eines abgeschlossenen Systems nicht abnimmt. Ein Körper ist aber kein abgeschlossenes System: Er nimmt ständig Energie von außen auf (Nahrung) und gibt Wärme und Abfallprodukte an die Umgebung ab. Dadurch steigt die Entropie der Umgebung stärker, als die Entropie im Körper sinkt, sodass die Gesamtentropie nicht abnimmt. Lokale Ordnung ist also möglich, wenn sie mit Energie und Abwärme bezahlt wird; ein Widerspruch zum Hauptsatz entsteht nicht.","coreRule":"⚡ Ordnung in einem Teil ist kein Gegenbeweis zum Zweiten Hauptsatz: Prüfe immer das Gesamtsystem. Leben zahlt für lokale Ordnung mit Energie und Abwärme.","beleg":"Werkstück C.1.2 (Kontext & Tiefe, Absatz „Das Leben selbst, einschließlich unseres Körpers …“)","status":"entwurf","scenario":"","kurz":"Der Hauptsatz verbietet eine Abnahme nur für die Gesamtentropie eines abgeschlossenen Systems. Ein Körper ist offen: Er nimmt Energie auf und gibt Wärme an die Umgebung ab, deren Entropie dabei steigt. Seine Ordnung widerlegt also nichts.","prueffrage":"Was geschieht mit der Ordnung eines Körpers, der wochenlang nichts zu essen bekommt?","rueckmeldung":[{"option":0,"text":"Der Hauptsatz kennt keine Ausnahme für Lebewesen, er gilt für belebte wie unbelebte Systeme. Zellen bauen Entropie auch nicht einfach im Inneren ab: Sie halten ihre Ordnung, indem sie Energie aufnehmen und Entropie an die Umgebung abgeben."},{"option":1,"text":"Dass sich bei genug Zeit alles von selbst ordnet, trifft nicht zu: Unordnung ist statistisch der weit wahrscheinlichere Zustand. Ordnung im Körper bleibt nur bestehen, weil ständig Energie zugeführt und Wärme abgegeben wird."},{"option":2,"text":"Ein Körper kann seine Entropie nur senken, indem er Wärme und Stoffe an die Umgebung abgibt, und dauerhaft gelingt das nur mit ständiger Energiezufuhr wie Nahrung. Die Gesamtentropie von Körper und Umgebung nimmt dabei nicht ab."}],"familie":"bilanz-pruefen","fertigkeit":"F1"},{"id":"qx-c1-008","clusterId":"C","werkstueckRef":"C.1.2","stufe":4,"question":"Welche Überlegung prüft den Kern dieser Werbebehauptung am besten?","options":["Der Körper besitzt mit Leber und Nieren Organe, die Stoffe laufend abbauen und ausscheiden; der Anbieter müsste erklären, welche zusätzliche Leistung sein Saft darüber hinaus erbringt.","Der Zweite Hauptsatz verbietet jede Ausleitung, weil sich Entropie nicht aus einem System entfernen lässt; schon deshalb kann kein Saft etwas ausleiten.","Ein Körper bleibt nur geordnet, solange man ihm gezielt von außen zusätzliche Ordnung in Form von besonderen Zusatzstoffen zuführt; der Saft könnte das leisten.","Die Behauptung lässt sich erst beurteilen, wenn jeder Inhaltsstoff des Safts untersucht ist; bis dahin bleibt das Versprechen unwiderlegt und damit offen."],"correctIndex":0,"explanation":"Die Behauptung unterstellt, der Körper werde „Schlacken“ allein nicht los. Abbau und Ausscheidung leisten aber laufend vor allem Leber und Nieren, deshalb müsste der Anbieter erklären, was sein Saft darüber hinaus bewirkt; hinzu kommt, dass „Schlacke“ kein medizinisch definierter Stoff ist und der Werbetext offenlässt, was sich ansammeln soll. Der Zweite Hauptsatz verbietet Ausscheidung nicht: Er gilt für abgeschlossene Systeme, und ein Körper hält seine Ordnung, indem er Energie aufnimmt und Wärme und Abfallstoffe an die Umgebung abgibt. Dafür braucht er gewöhnliche Nahrung als Energiequelle, keine „Ordnung“ aus besonderen Zusatzstoffen. Um den Kern der Behauptung zu prüfen, muss man auch nicht erst jeden Inhaltsstoff des Safts untersuchen.","coreRule":"⚡ Behauptungen über ein „Ausleiten“ durch Spezialprodukte prüft man am Körper als entropie-bekämpfendem System: Leber und Nieren leisten diese Arbeit bereits laufend und ohne teure Säfte.","beleg":"Werkstück C.1.2 (Anwendung & Relevanz, „In der Pseudomedizin (‚Detox‘)“)","status":"entwurf","scenario":"Im Werbetext eines Saftanbieters steht: „Dein Körper ist voller Schlacken, die er allein nie wieder loswird. Nur unser Saft leitet sie zuverlässig aus.“ Eine Freundin überlegt, ob sie den Saft bestellen soll.","kurz":"Der Werbetext setzt voraus, der Körper könne sich nicht selbst entgiften, doch Leber und Nieren tun genau das laufend. Wer behauptet, sein Saft leiste mehr, muss erklären, was er über diese Organe hinaus bewirkt.","prueffrage":"Was genau sollen diese „Schlacken“ sein, und hat sie schon jemand im Blut oder Urin nachgewiesen?","rueckmeldung":[{"option":1,"text":"Der Zweite Hauptsatz gilt für abgeschlossene Systeme, ein Körper ist aber offen: Er nimmt Energie auf und gibt Wärme und Abfallstoffe ab. Ausscheiden ist damit nicht verboten, das Argument trägt nicht."},{"option":2,"text":"Ein Körper braucht tatsächlich Zufuhr von außen, um seine Ordnung zu halten. Das leistet aber gewöhnliche Nahrung als Energiequelle, nicht eine Zufuhr von „Ordnung“ durch besondere Zusatzstoffe."},{"option":3,"text":"Alle Inhaltsstoffe zu untersuchen wirkt gründlich, ist für den Kern aber nicht nötig: Schon die Voraussetzung, der Körper werde „Schlacken“ allein nie los, scheitert an Leber und Nieren. Und wer etwas verspricht, muss es belegen."}],"familie":"bilanz-pruefen","fertigkeit":"F1"},{"id":"qx-c1-009","clusterId":"C","werkstueckRef":"C.1.3","stufe":1,"question":"Ein Sternenforscher erklärt: „Massereiche Sterne fusionieren Element für Element bis zum Eisen. Danach macht Fusion keinen Sinn mehr.“ Eine Studentin fragt nach: „Warum sollte genau Eisen das Ende der Kette sein?“ Welche Antwort erklärt es am besten?","options":["Ab dem Eisen lassen sich keine schwereren Atomkerne mehr bilden, weil Eisen das schwerste Element ist, das im Universum überhaupt existiert.","Ab dem Eisen fehlt dem Stern der Wasserstoff, mit dem er jede Fusionsstufe zündet, und der Kern erlischt ohne weiteren Brennstoff.","Ab dem Eisen verbraucht Fusion mehr Energie, als sie erzeugt, der Kern verliert seine Energiequelle und kollabiert unter der eigenen Schwerkraft.","Ab dem Eisen lässt die Schwerkraft im Kern nach, sodass Druck und Temperatur für weitere Fusionen nicht mehr ausreichen."],"correctIndex":2,"explanation":"Entscheidend ist die Energiebilanz: Bis zum Eisen setzt jede Fusion Energie frei und hält den Stern am Leben. Bei Eisen kehrt sich das um: Weitere Fusion würde mehr Energie kosten, als sie liefert, der Kern verliert seine Energiequelle und kollabiert unter seiner eigenen Schwerkraft, was meist in einer Supernova endet. Schwerere Elemente sind dennoch nicht unmöglich: Gold und Uran existieren, sie entstehen nur nicht durch Fusion im Sternkern, sondern in der Supernova, zum Teil in aufgeblähten Roten Riesen und nach heutigem Wissen wohl großenteils beim Zusammenstoß von Neutronensternen. Auch ein Mangel an Wasserstoff ist nicht der Grund, denn die späteren Stufen verschmelzen die Produkte der vorigen, etwa Helium zu Kohlenstoff und Sauerstoff, Kohlenstoff zu Neon und Magnesium. Und die Schwerkraft lässt nicht nach: Sie setzt sich durch, sobald die Fusion keine Energie und keinen Gegendruck mehr liefert.","coreRule":"⚡ Bei jeder Erklärung fragen: Was ist die Energiebilanz? Bis zum Eisen liefert Fusion Energie, danach kostet sie welche, und der Stern stirbt.","beleg":"Werkstück C.1.3 (Die erste Ernte; Fn gl-c-nukleosynthese: Tyson/Gott/Strauss 2022, Schwedt 2014)","status":"entwurf","scenario":"","kurz":"Bis zum Eisen setzt jede Fusion Energie frei, danach kostet sie mehr, als sie liefert. Dann fehlt dem Kern der Gegendruck, und er kollabiert. Dass sich nichts Schwereres bilden lässt, ist die naheliegende, aber falsche Deutung.","prueffrage":"Was hält einen Stern davon ab, unter seinem eigenen Gewicht zusammenzufallen, solange er Elemente verschmilzt?","rueckmeldung":[{"option":0,"text":"Dass bei Eisen etwas endet, legt nahe, schwerere Kerne seien unmöglich. Gold und Uran gibt es aber, sie entstehen nur anders, etwa in Supernovae oder bei Neutronensternkollisionen. Es endet die Fusion im Kern, nicht die Existenz schwererer Elemente."},{"option":1,"text":"Wasserstoff ist der Hauptbrennstoff eines Sterns, daher liegt das nahe. Die späteren Stufen verschmelzen aber die Produkte der vorigen, etwa Helium zu Kohlenstoff, ganz ohne Wasserstoff; am Eisen kippt die Energiebilanz, nicht der Vorrat."},{"option":3,"text":"Druck und Temperatur sind tatsächlich Voraussetzung für jede Fusion. Die Schwerkraft lässt aber nicht nach: Sie setzt sich durch, sobald die Fusion keine Energie und keinen Gegendruck mehr liefert, und dann kollabiert der Kern."}],"familie":"bilanz-pruefen","fertigkeit":"F1"},{"id":"qx-c1-010","clusterId":"C","werkstueckRef":"C.1.3","stufe":2,"question":"Welche Überlegung prüft die Behauptung am besten und führt zu einem begründeten Urteil?","scenario":"In einem Artikel über Schmuck steht: „Gold ist so alt wie das Universum selbst. Es entstand beim Urknall und sammelte sich später in den Planeten.“ Du trägst einen goldenen Ehering und willst prüfen, ob die Aussage stimmt.","options":["Im frühen Universum bestand fast alles aus Wasserstoff und Helium. Schwere Elemente wie Gold brauchen extreme Prozesse in oder nach dem Tod von Sternen. Die Behauptung ist deshalb sehr unwahrscheinlich.","Gold ist sehr selten und wertvoll. Etwas so Seltenes muss ganz am Anfang entstanden sein, bevor das Universum Zeit hatte, es zu verbrauchen. Die Behauptung ist deshalb plausibel.","Der Artikel nennt keine Quelle, deshalb lässt sich nichts darüber sagen. Ohne Gegenbeweis ist die Behauptung genauso wahrscheinlich wie jede andere Herkunft.","Gold ist schwerer als Eisen. Schwere Elemente sinken nach unten, daher müssen sie in der Frühzeit entstanden sein und sich als Erstes gesammelt haben. Die Behauptung ist deshalb plausibel."],"correctIndex":0,"explanation":"Eine Behauptung über Herkunft lässt sich mit dem prüfen, was über die Anfangsbedingungen bekannt ist. Das frühe Universum bestand zu rund 75 % aus Wasserstoff und zu rund 25 % aus Helium, schwerere Elemente gab es praktisch nicht. Elemente jenseits des Eisens entstehen teils in der Hitze von Supernovae, teils durch langsamen Neutroneneinfang in aufgeblähten Roten Riesen. Gold und Uran entstehen nach heutigem Wissen großenteils beim Zusammenstoß zweier ausgebrannter Neutronensterne. Das Gold in deinem Ring entstand also erst, nachdem Sterne entstanden und gestorben waren, in einem Prozess wie einer Sternkatastrophe, nicht beim Urknall. Seltenheit allein sagt nichts über das Alter aus, und das Fehlen einer Quelle macht eine Behauptung nicht gleich wahrscheinlich wie ihr Gegenteil. Sie bleibt ungeprüft, und die Prüfung gegen bekanntes Wissen spricht klar dagegen.","coreRule":"⚡ Prüfe Herkunftsbehauptungen an den Anfangsbedingungen: Was es am Anfang nicht gab, musste später entstehen, und zwar durch einen Prozess, der es erzeugen kann.","beleg":"Werkstück C.1.3; Fn. gl-c-nukleosynthese (Tyson/Gott/Strauss 2022, S. 64–65; Schwedt 2014, S. 197)","status":"entwurf","kurz":"Das frühe Universum bestand fast nur aus Wasserstoff und Helium; Gold entsteht erst bei Sternkatastrophen. Der naheliegende Fehler ist, Seltenheit oder Schwere als Hinweis auf frühe Entstehung zu lesen. Beides sagt nichts über das Alter.","prueffrage":"Wird Gold mit der Zeit verbraucht, und was verrät seine Seltenheit dann über sein Alter?","rueckmeldung":[{"option":1,"text":"Gold ist tatsächlich selten und wertvoll. Aus Seltenheit folgt aber kein hohes Alter: Gold wird nicht aufgebraucht, sondern erst später bei Sternkatastrophen erzeugt, und Seltenheit allein verrät nichts über den Ursprung."},{"option":2,"text":"Eine fehlende Quelle macht die Aussage tatsächlich ungeprüft. Das heißt aber nicht, dass nichts zu sagen wäre: Man kann sie mit bekanntem Wissen vergleichen, und dann ist sie keineswegs so wahrscheinlich wie jede andere Herkunft."},{"option":3,"text":"Gold hat eine höhere Atommasse als Eisen, das stimmt. Wie schwer ein Element ist, sagt aber nichts darüber, wann es entstand. Das Absinken schwerer Stoffe betrifft Material, das schon vorhanden ist, nicht dessen Herkunft."}],"familie":"mechanismus-verlangen","fertigkeit":"F1"},{"id":"qx-c1-011","clusterId":"C","werkstueckRef":"C.1.3","stufe":3,"question":"Du liest die Behauptung: „Das Eisen in deinem Blut stammt aus dem Eisenkern massereicher Sterne, den die Supernova beim Sterben ins All schleudert.“ Welche Prüffrage deckt am besten auf, ob das stimmen kann?","options":["Wird der kollabierte Eisenkern ins All geschleudert, oder bleibt er als dichter Sternrest zurück?","Wie viele Elemente kann ein einzelner Stern fusionieren, bevor sein Brennstoff aufgebraucht ist?","Wie viel Energie setzt die Explosion eines massereichen Sterns frei, verglichen mit unserer Sonne?","Wie lange dauert es, bis Eisen aus einer Supernova in neue Gaswolken gelangt und Planeten bildet?"],"correctIndex":0,"explanation":"Die Behauptung verwechselt zwei Dinge: das Eisen im Kern eines massereichen Sterns und das Eisen, das tatsächlich ins All gelangt. Wenn der Eisenkern kollabiert, bleibt er als Neutronenstern oder Schwarzes Loch zurück, statt ausgeschleudert zu werden. Die Frage nach dem Schicksal des Kerns trifft deshalb genau die Stelle, an der das Argument bricht; die übrigen Fragen sind interessant, entscheiden aber nicht, ob die Behauptung stimmt. Das Eisen, das ins All gelangt, entsteht erst bei Explosionen: zum Teil in der Kernkollaps-Supernova selbst, in Schichten außerhalb des Kerns, zu einem großen Teil in Supernovae vom Typ Ia, bei denen ein Weißer Zwerg in einem engen Doppelsternsystem explodiert. In beiden Fällen entsteht zunächst Nickel, das über Kobalt zu Eisen zerfällt.","coreRule":"⚡ Prüfe bei einer Herkunftsbehauptung, wo das Material entsteht und auf welchem Weg es tatsächlich nach außen gelangt: Das meiste Eisen stammt aus Supernovae vom Typ Ia, der Eisenkern massereicher Sterne bleibt zurück.","beleg":"Werkstück C.1.3 (Kontext & Tiefe, Supernova); Fn. gl-c-eisen (Langer 1995, S. 96; Schneider 2007, S. 49–50); Fn. gl-c-elementherkunft (Kobayashi/Karakas/Lugaro 2020, S. 3 und S. 26)","status":"entwurf","scenario":"In einem Online-Artikel über „Sternenstaub im Körper“ steht der Satz „Wir sind aus Sternenstoff gemacht“ als selbstverständliche Tatsache. Dazu heißt es, bei Eisen sei die Fusion im Sterneninneren an ihr Ende gekommen, weil eine weitere Fusion mehr Energie verbrauchen als freisetzen würde. Danach kollabiere der Kern des Sterns unter der eigenen Schwerkraft.","kurz":"Entscheidend ist, was mit dem Eisenkern geschieht: Er kollabiert und bleibt als Neutronenstern oder Schwarzes Loch zurück. Verwechselt wird das Eisen im Kern mit dem Eisen, das bei Explosionen tatsächlich ins All gelangt.","prueffrage":"Was muss mit dem Eisen eines Sterns geschehen, bevor es in einem Planeten und schließlich in deinem Blut landen kann?","rueckmeldung":[{"option":1,"text":"Dass ein massereicher Stern bis zum Eisen fusioniert, stimmt. Wie viele Stufen es gibt, sagt aber nichts darüber, ob das entstandene Eisen den Stern auch verlässt."},{"option":2,"text":"Die Explosionsenergie ist gewaltig, doch Größe allein belegt nichts. Entscheidend ist, was mit dem Kern geschieht: Ob er hinausgeschleudert wird, folgt nicht aus der Energiemenge."},{"option":3,"text":"Wie lange Eisen bis in neue Gaswolken braucht, setzt voraus, dass das Eisen aus dem Kern überhaupt ins All gelangt. Gerade das ist fraglich, und die Dauer klärt daher nicht, ob die Behauptung stimmt."}],"familie":"mechanismus-verlangen","fertigkeit":"F1"},{"id":"qx-c1-012","clusterId":"C","werkstueckRef":"C.1.3","stufe":4,"question":"Eine Astrologin sagt, die Sterne seien mystisch mit uns „verbunden“ und beeinflussten deinen Charakter. Du willst prüfen, ob an einer „Verbindung zu den Sternen“ überhaupt etwas dran ist. Welche Überlegung hält einer Prüfung stand?","options":["Sternbilder zur Geburt bilden Muster, die mit dem Charakter zusammenhängen, sobald man nur lange genug beobachtet und sauber auswertet.","Die Anziehung ferner Sterne wirkt auf Neugeborene stärker als die der Menschen im Kreißsaal und prägt sie dadurch.","Eine Verbindung zu den Sternen gibt es nicht, denn Sternenstoff ist nur eine dichterische Metapher, die sich physikalisch nicht belegen lässt.","Eine Verbindung gibt es, aber als Herkunft: Die Atome deines Körpers, außer Wasserstoff, entstanden in Sternen, ohne dass daraus ein Einfluss auf deinen Charakter folgt."],"correctIndex":3,"explanation":"Die Behauptung „Verbindung“ ist erst dann prüfbar, wenn man fragt, welche Art von Verbindung gemeint ist. Eine Herkunftsverbindung ist real und gut belegt: Nach dem Urknall gab es fast nur Wasserstoff und Helium. Kohlenstoff, Sauerstoff, Eisen und die übrigen schwereren Elemente wurden später durch Kernfusion in Sternen sowie in Supernovae und bei Kollisionen ausgebrannter Sternreste erzeugt. Dass dein Körper aus diesen Elementen besteht, ist ein beobachtbarer Befund und mehr als Poesie. Ein Einfluss auf den Charakter folgt daraus aber nicht: Herkunft des Materials ist etwas anderes als eine Wirkung auf dein Verhalten. Dass ferne Sterne Neugeborene gravitativ prägen, ist physikalisch nicht begründet; für einen solchen Einfluss gibt es keinen Beleg, die belegte Verbindung ist stofflicher Natur. Und wer „Muster, wenn man nur lange genug auswertet“ verspricht, beschreibt keinen Nachweis, sondern die Haltung, nach Bestätigung zu suchen. Die Aussage, es gebe gar keine Verbindung, ist dagegen falsch: Die stoffliche Herkunft aus Sternen ist belegt und mehr als eine Metapher. So hältst du beides auseinander: das echte Herkunftsargument und das unbelegte Einflussargument.","coreRule":"⚡ Prüfe, welche Art von Verbindung behauptet wird: Eine stoffliche Herkunft aus den Sternen ist belegt, ein Einfluss auf Charakter oder Zukunft folgt daraus nicht.","beleg":"Werkstück C.1.3 (Anwendung & Relevanz, „Gegen die Esoterik & Astrologie“; Kernidee)","status":"entwurf","scenario":"","quote":"","quoteLabel":"","kurz":"Eine Verbindung zu den Sternen gibt es als Herkunft: Die schwereren Elemente deines Körpers entstanden in Sternen. Der naheliegende Fehler ist, aus dieser stofflichen Herkunft einen Einfluss auf den Charakter abzuleiten, den sie nicht begründet.","prueffrage":"Was genau soll mit „Verbindung“ gemeint sein, und woran ließe sich diese Art von Verbindung beobachten?","rueckmeldung":[{"option":0,"text":"Wer lange genug sucht, findet in Daten fast immer irgendein Muster. Das ist aber kein Nachweis, sondern eine Suche nach Bestätigung. Ein belegter Zusammenhang zwischen Sternbild und Charakter ergibt sich daraus nicht."},{"option":1,"text":"Gravitation ist eine reale Kraft, daher wirkt die Überlegung physikalisch. Ferne Sterne ziehen wegen ihrer gewaltigen Entfernung aber weit schwächer als die Menschen im Kreißsaal; eine Prägung des Charakters ist dadurch weder begründet noch belegt."},{"option":2,"text":"Sternenstoff klingt tatsächlich nach Poesie, und ein Einfluss auf den Charakter ist nicht belegt. Zu weit geht aber die Aussage, es gebe gar keine Verbindung: Die Herkunft der schwereren Elemente aus Sternen ist gut belegt und mehr als eine Metapher."}],"familie":"genau-unterscheiden","fertigkeit":"F1"},{"id":"qx-c1-013","clusterId":"C","werkstueckRef":"C.1.4","stufe":1,"question":"Welche Überlegung führt zur plausibelsten Einschätzung?","options":["Die Hebamme zog vermutlich nicht schwächer als der Mars: Der riesige Abstand schwächt die Kraft stärker, als die Masse des Planeten ausgleicht.","Der Mars zog stärker, denn ein Planet hat unvorstellbar viel mehr Masse als ein Mensch, und die Kraft nimmt nur gleichmäßig mit der Entfernung ab.","Beide zogen praktisch gleich stark, denn die Gravitation reicht unendlich weit und hängt nur von der Masse ab, nicht vom Abstand.","Das lässt sich ohne Messung am Neugeborenen nicht sagen, denn die Stärke einer Kraft zeigt sich nur in der Wirkung auf das Kind selbst."],"correctIndex":0,"explanation":"Die Schwerkraft ist proportional zur Masse und zu 1/r². Verzehnfachst du den Abstand, sinkt die Kraft auf ein Hundertstel. Bei dem Abstand zwischen Baby und Mars (rund 55 Millionen Kilometer gegenüber einem halben Meter) wiegt die enorme Masse des Planeten das nicht auf: Die Hebamme zieht meist um ein Vielfaches stärker als der Mars und selbst bei dessen größter Annäherung nicht schwächer. Die Annahme, Größe zähle mehr als Nähe, ist deshalb ein Denkfehler, denn der Abstand fließt mit der zweiten Potenz ein. Auch ohne Messung am Kind lässt sich die Kraft aus Masse und Abstand berechnen.","coreRule":"⚡ Kraft ~ Masse / Abstand²: Doppelter Abstand heißt ein Viertel der Kraft, zehnfacher Abstand ein Hundertstel. Nähe schlägt Größe, wenn der Abstand groß genug ist.","quote":"Wenn du die Entfernung verdoppelst, sinkt seine Kraft auf ein Viertel (1/2²).","quoteLabel":"Merksatz:","beleg":"Werkstück C.1.4 (Kontext & Tiefe, Formel und Konsequenz)","status":"entwurf","scenario":"Eine Freundin liest ihr Horoskop und sagt: „Der Mars ist riesig, aber selbst bei seiner größten Annäherung rund 55 Millionen Kilometer weg, die Hebamme bei meiner Geburt war dagegen winzig und stand nur etwa einen halben Meter neben mir. Ich frage mich, wie viel Einfluss durch Anziehungskraft da von beiden wohl ausging.“ Du weißt: Die Schwerkraft nimmt mit dem Quadrat der Entfernung ab.","kurz":"Die Schwerkraft wächst mit der Masse, nimmt mit dem Abstand aber im Quadrat ab. Bei 55 Millionen Kilometern gegenüber einem halben Meter gleicht die riesige Masse des Mars das nicht aus. Größe allein entscheidet also nicht.","prueffrage":"Um welchen Faktor ist der Mars schwerer als die Hebamme, und um welchen Faktor schwächt das Quadrat des größeren Abstands seine Anziehung?","rueckmeldung":[{"option":1,"text":"Die Masse des Mars ist tatsächlich unvorstellbar viel größer als die eines Menschen. Die Kraft sinkt aber nicht gleichmäßig, sondern mit dem Quadrat des Abstands, und bei diesem Abstandsverhältnis wiegt das die Masse mehr als auf."},{"option":2,"text":"Die Gravitation hat zwar theoretisch unbegrenzte Reichweite. Das heißt aber nicht, dass der Abstand egal wäre: Die Kraft wird mit zunehmender Entfernung rasch kleiner, und zwar mit 1/r². Dass sie nur von der Masse abhinge, trifft nicht zu."},{"option":3,"text":"Eine Messung am Neugeborenen wäre kaum möglich, aber auch gar nicht nötig. Die Anziehungskraft folgt aus Masse und Abstand und lässt sich daher berechnen, ohne sie am Kind selbst zu beobachten."}],"familie":"groessenordnung-schaetzen","fertigkeit":"F4"},{"id":"qx-c1-014","clusterId":"C","werkstueckRef":"C.1.4","stufe":2,"question":"Die Astrologin sagt: „Bei deiner Geburt hat der riesige Mars viel stärker an dir gezogen als die Hebamme neben dir. Er ist schließlich ein ganzer Planet.“ Welche Überlegung prüft diese Behauptung am besten?","options":["Man muss Masse und Entfernung gemeinsam betrachten: Weil die Kraft mit dem Quadrat der Entfernung abnimmt, kann die winzige, aber nahe Hebamme stärker ziehen als der riesige, aber ferne Planet.","Man muss nur die Masse vergleichen: Weil der Mars unvergleichlich schwerer ist als ein Mensch, zieht er zwangsläufig stärker, auch wenn die Entfernung groß ist.","Man muss nur die Entfernung vergleichen: Weil die Hebamme viel näher ist, zieht sie stärker, ganz gleich wie klein ihre Masse im Verhältnis zum Planeten ist.","Man muss prüfen, welcher Körper im Horoskop wichtiger ist: Weil der Mars dort eine zentrale Rolle spielt, zieht er stärker als ein Mensch im Raum."],"correctIndex":0,"explanation":"Die Gravitationskraft hängt von zwei Größen zugleich ab: Sie wächst mit der Masse und sinkt mit dem Quadrat der Entfernung; verzehnfachst du den Abstand, bleibt nur ein Hundertstel der Kraft. Beim Mars gleicht die riesige Masse das nicht aus: Eine Hebamme von etwa 70 Kilogramm zieht selbst bei der größten Annäherung des Mars noch etwas stärker als er, bei üblichem Abstand meist um ein Vielfaches stärker. Umgekehrt ziehen Mond und Sonne wegen ihrer enormen Masse trotz großer Entfernung viel stärker als die Hebamme (der Mond rund 1.800-mal, die Sonne rund 300.000-mal so stark). Wie stark ein Körper zieht, folgt also allein aus Masse und Abstand, nicht aus der Bedeutung, die ihm eine Lehre zuschreibt. Wer nur eine der beiden Größen betrachtet oder die Stärke nach Ansehen vergibt, kommt zu falschen Schlüssen.","coreRule":"⚡ Bei Fernwirkungen immer Masse und Abstand zusammen prüfen: Größe allein entscheidet nichts.","beleg":"Werkstück C.1.4 (Das Härten im Feuer, Schmiede-Übung „Die Einfluss-Hierarchie“; Kontext & Tiefe)","status":"entwurf","scenario":"Du sprichst mit einer Astrologin über den angeblichen Einfluss der Planeten auf Neugeborene. Du weißt: Die Gravitationskraft wächst mit der Masse und sinkt mit dem Quadrat der Entfernung. Der Mars ist bei seiner größten Annäherung etwa 55 Millionen Kilometer entfernt, die Hebamme bei einer Geburt etwa einen halben Meter.","kurz":"Gravitation hängt von Masse und Entfernung zugleich ab, und die Entfernung zählt quadratisch. Wer nur auf die Masse des Planeten schaut, übersieht das: Selbst bei größter Annäherung des Mars zieht die nahe Hebamme nicht schwächer, bei üblichem Abstand um ein Vielfaches stärker.","prueffrage":"Wie viel weiter als die Hebamme ist der Mars entfernt, und was sagt die Astrologin über diese Entfernung?","rueckmeldung":[{"option":1,"text":"Der Mars ist unvergleichlich schwerer als ein Mensch, das stimmt. Die Kraft sinkt aber mit dem Quadrat der Entfernung: Selbst bei größter Annäherung zieht die Hebamme nicht schwächer, in größerer Entfernung meist um ein Vielfaches stärker."},{"option":2,"text":"Dass die Hebamme hier stärker zieht, stimmt, aber nicht allein wegen der Nähe. Beide Größen wirken zusammen: Mond und Sonne ziehen trotz großer Entfernung viel stärker als die Hebamme, weil ihre Masse so gewaltig ist."},{"option":3,"text":"Welche Rolle der Mars im Horoskop spielt, sagt nichts über seine Gravitation. Wie stark ein Körper zieht, folgt allein aus Masse und Abstand, nicht aus der Bedeutung, die eine Lehre ihm zuschreibt."}],"familie":"groessenordnung-schaetzen","fertigkeit":"F4"},{"id":"qx-c1-015","clusterId":"C","werkstueckRef":"C.1.4","stufe":3,"question":"Der Astrologe räumt ein: „Die Gravitation der Planeten ist tatsächlich zu schwach, aber es wirkt eine andere, noch unbekannte Kraft.“ Wie lässt sich seine Behauptung am besten prüfen?","options":["Man prüft die behauptete Wirkung selbst: Können Astrologen Geburtshoroskope Menschen besser zuordnen, als der Zufall erwarten lässt? Das gilt, egal welche Kraft dahinterstehen soll.","Man berechnet genauer, indem man auch Gezeitenkräfte und Kernkräfte der Planeten mitzählt; erst danach lässt sich die Behauptung abschließend bewerten.","Man beachtet, dass sich die Lehre über Jahrtausende gehalten hat; ein so lange verbreiteter Glaube besitzt vermutlich irgendeinen wirksamen Kernmechanismus.","Man verlangt den Nachweis, dass Planeten keinerlei unbekannte Kraft ausüben; erst dann gilt die Behauptung als geprüft und widerlegt."],"correctIndex":0,"explanation":"Der Verweis auf eine unbekannte Kraft ist ein Argument aus Unwissenheit: Er lässt sich nicht widerlegen, weil sich über das Unbekannte nichts sagen lässt. Prüfbar ist aber die behauptete Wirkung selbst, ganz gleich, durch welche Kraft sie entstehen soll. Genau das wurde getestet: In mehr als vierzig kontrollierten Versuchen ordneten Astrologen Geburtshoroskope nicht besser zu, als der Zufall erwarten lässt. Und gut 2.000 Londoner, die im März 1958 nur Minuten nacheinander zur Welt kamen, glichen einander nicht stärker als beliebige andere. Außerdem liegt die Beweislast bei dem, der die Wirkung behauptet; niemand muss die Nichtexistenz einer unbekannten Kraft beweisen. Dass sich ein Glaube lange hält, sagt nichts über seine Wirksamkeit.","coreRule":"⚡ Wer eine Wirkung behauptet, muss sie zeigen – egal, durch welche Kraft sie angeblich entsteht.","beleg":"Werkstück C.1.4 (Anwendung & Relevanz, „Bei der Astrologie“; Belege unter F.2.1 und Band II, Sektion II.8.1)","status":"entwurf","scenario":"Du hast einem Astrologen vorgerechnet, dass der Mars bei einer Geburt nicht stärker an dem Kind zieht als die anwesende Hebamme.","kurz":"Eine unbekannte Kraft lässt sich nicht widerlegen, weil über das Unbekannte nichts feststeht. Prüfbar ist aber die behauptete Wirkung selbst: Ordnen Astrologen Horoskope besser zu als der Zufall? Das ist getestet und trifft nicht zu.","prueffrage":"Was ließe sich über eine Kraft, von der nichts bekannt ist, überhaupt berechnen oder widerlegen?","rueckmeldung":[{"option":1,"text":"Mehr Rechnen wirkt gründlich, trifft aber nicht den Kern: Der Astrologe beruft sich auf eine unbekannte Kraft, die sich gar nicht berechnen lässt. Sinnvoller ist es, die behauptete Wirkung zu testen, statt bekannte Kräfte weiter auszuloten."},{"option":2,"text":"Dass sich eine Lehre lange hält, zeigt, dass sie Menschen anspricht, aber nicht, dass sie wirkt. Auch Irrtümer können sehr alt werden. Ob ein Mechanismus existiert, entscheidet sich an der behaupteten Wirkung, nicht am Alter."},{"option":3,"text":"Das dreht die Beweislast um. Wer eine Wirkung behauptet, muss sie belegen; niemand muss die Nichtexistenz einer unbekannten Kraft beweisen, was ohnehin nicht ginge. Prüfbar bleibt die behauptete Wirkung selbst."}],"familie":"beweislast-klaeren","fertigkeit":"F1"},{"id":"qx-c1-016","clusterId":"C","werkstueckRef":"C.1.4","stufe":4,"question":"Eine „Fernheilerin“ behauptet, ihre Wirkung sei aus 8.000 Kilometern Entfernung genauso stark wie am Bett. Welche Frage prüft diese Behauptung am besten?","options":["Wie viel Masse die Heilerin besitzt, denn bei großem Abstand wirken nur sehr massereiche Objekte überhaupt noch auf einen Menschen.","Wie schnell die Wirkung eintrifft, denn nur zu langsam ankommende Kräfte lassen sich mit physikalischen Gesetzen infrage stellen.","Keine, denn die Gravitation reicht unendlich weit; also darf jede andere Wirkung ebenfalls beliebig weit tragen, ohne zu schwinden.","Welche Kraft das leisten soll, denn jede Kraft aus so weiter Ferne müsste erklären, warum sie nicht mit der Entfernung abnimmt."],"correctIndex":3,"explanation":"Bekannte langreichweitige Kräfte wie Gravitation und Elektromagnetismus nehmen mit dem Quadrat der Entfernung ab: Bei zehnfachem Abstand bleibt nur ein Hundertstel, bei 8.000 Kilometern statt einem Meter ist die Wirkung nach dieser Regel um viele Größenordnungen geschwunden. Unendliche Reichweite heißt nicht gleichbleibende Stärke. Wer eine Wirkung aus großer Ferne behauptet, die am Bett genauso stark sein soll wie in 8.000 Kilometern, muss deshalb erklären, welcher Mechanismus das Abnehmen mit der Entfernung umgeht. Antwortet jemand darauf nur mit vagen, mystischen Begriffen statt mit überprüfbaren Angaben, ist das ein Warnsignal. Die Frage nach der Masse der Heilerin oder der Geschwindigkeit der Wirkung trifft den Kern nicht, und die Behauptung, Reichweite bedeute gleiche Stärke, ist schlicht falsch.","coreRule":"⚡ Wer eine Fernwirkung behauptet, muss erklären, warum sie mit der Entfernung nicht schwindet.","beleg":"Werkstück C.1.4 (Anwendung & Relevanz, „Bei anderen esoterischen Behauptungen“; Red Flags)","status":"entwurf","kurz":"Eine Wirkung aus 8.000 Kilometern müsste erklären, warum sie nicht schwächer wird, denn bekannte Kräfte nehmen mit dem Quadrat der Entfernung ab. Der naheliegende Fehler: „unendlich weit“ mit „gleich stark“ zu verwechseln.","prueffrage":"Reicht die Schwerkraft der Erde bis zum Mond, und ist sie dort noch so stark wie an der Erdoberfläche?","rueckmeldung":[{"option":0,"text":"Bei der Gravitation zählt die Masse tatsächlich, doch auch dort schwindet die Wirkung mit dem Abstand. Die Masse der Heilerin erklärt also nicht, warum die Wirkung in 8.000 Kilometern so stark sein soll wie am Bett."},{"option":1,"text":"Die Frage nach dem Tempo wirkt messbar und damit wissenschaftlich. Physikalische Gesetze gelten aber nicht nur für langsame Kräfte: Entscheidend ist, warum die Wirkung mit der Entfernung nicht abnehmen soll, ganz gleich, wie schnell sie ankommt."},{"option":2,"text":"Gravitation reicht tatsächlich unendlich weit, aber ihre Stärke nimmt mit dem Quadrat der Entfernung ab. Unendliche Reichweite heißt nicht gleichbleibende Stärke, und daraus lässt sich keine beliebig weit tragende Wirkung ableiten."}],"familie":"groessenordnung-schaetzen","fertigkeit":"F4"},{"id":"qx-c1-017","clusterId":"C","werkstueckRef":"C.1.5","stufe":1,"question":"Welche Schlussfolgerung ist mit diesen Messwerten am besten vereinbar?","scenario":"Am Rand des Grand Canyon sagt ein Besucher: „Eine so riesige Schlucht kann nur eine einzige gewaltige Flut in kurzer Zeit in den Fels geschnitten haben.“ Datierte Ablagerungen in Höhlen der Canyonwände zeigen, dass sich der Colorado River im Mittel nur um Bruchteile eines Millimeters pro Jahr eingegraben hat, also langsamer, als ein Fingernagel wächst.","options":["Der Canyon ist in wenigen Wochen entstanden, weil eine gewaltige Flut den Fels durchschnitten hat.","Der Canyon ist nach wenigen Jahrtausenden fertig gewesen, weil der Fluss sich um rund einen halben Meter pro Jahr eingegraben hat.","Der Canyon ist durch ein einzelnes Erdbeben entstanden, das den Fels aufgespalten hat, und der Fluss hat später nur noch die fertige Schlucht durchflossen.","Der Canyon ist über sehr lange Zeit entstanden, weil ein meist unspektakulärer Fluss sich nur langsam, aber stetig eingegraben hat."],"correctIndex":3,"explanation":"Rate mal Zeit ergibt die Tiefe: Wer eine gemessene Einschneiderate von nur Bruchteilen eines Millimeters pro Jahr kennt, kann die Entstehung einer so gewaltigen Schlucht nicht in Wochen oder wenigen Jahrtausenden erklären. Er braucht unvorstellbar lange Zeiträume, in denen winzige Schritte sich summieren. Die genannte Größenordnung stammt aus der Datierung von Höhlenablagerungen (Polyak u. a. 2008): Der Grundwasserspiegel sank um rund 0,05 bis 0,4 mm pro Jahr. Vorbehalt: Umstritten ist unter anderem, ob sich Absenkung des Grundwasserspiegels und Einschneiden gleichsetzen lassen, nicht aber die Größenordnung der Rate. Die Gegenerklärungen scheitern an derselben Rechnung: Eine Flut von wenigen Wochen passt nicht zu den gemessenen Werten, und ein halber Meter pro Jahr wäre mehr als das Tausendfache der genannten 0,05 bis 0,4 mm pro Jahr. Für ein Erdbeben als alleinige Ursache gibt es in der Aufgabe keinen Anhaltspunkt. Dass man sich langsame Prozesse über riesige Zeiträume schwer vorstellen kann, ist kein Argument gegen sie.","coreRule":"⚡ Rate mal Zeit ergibt das Ergebnis: Auch winzige, stetige Veränderungen schaffen über genug Zeit riesige Formen. Prüfe immer, ob die Zeitskala der Erklärung zur gemessenen Rate passt.","beleg":"Werkstück C.1.5 (Der Fingernagel am Grand Canyon); Fn. gl-c-grandcanyon (Polyak/Hill/Asmerom 2008, Science 319, S. 1377–1380)","status":"entwurf","kurz":"Rate mal Zeit ergibt die Tiefe: Bei nur Bruchteilen eines Millimeters Einschneiden pro Jahr summieren sich winzige Schritte erst über sehr lange Zeiträume zu einer riesigen Schlucht. Wochen oder wenige Jahrtausende reichen dafür nicht, so groß der Canyon auch wirkt.","prueffrage":"Wie tief wird eine Schlucht, wenn sich ein Fluss 1.000 Jahre lang um 0,1 Millimeter pro Jahr eingräbt, und wie tief nach einer Million Jahren?","rueckmeldung":[{"option":0,"text":"Die enorme Größe der Schlucht legt eine ebenso gewaltige Ursache nahe. Die gemessene Rate von Bruchteilen eines Millimeters pro Jahr passt aber nicht zu einer Entstehung in wenigen Wochen, denn dafür wäre ein Vielfaches davon nötig."},{"option":1,"text":"Mit Rate mal Zeit zu rechnen ist richtig, und Jahrtausende sind schon eine lange Zeit. Ein halber Meter pro Jahr wäre aber mehr als das Tausendfache der gemessenen 0,05 bis 0,4 Millimeter, die Rate stimmt also nicht mit den Messwerten überein."},{"option":2,"text":"Ein Beben, das den Fels aufspaltet, ist ein anschauliches Bild für Größe und Plötzlichkeit. Nichts deutet aber auf ein solches Beben hin, und die Messungen zeigen, dass der Fluss selbst sich eingräbt, wenn auch sehr langsam."}],"familie":"groessenordnung-schaetzen","fertigkeit":"F4"},{"id":"qx-c1-018","clusterId":"C","werkstueckRef":"C.1.5","stufe":2,"question":"Wie weit vor dem Ziel würde der Mensch auf dieser Strecke auftauchen?","options":["Etwa 15 Meter vor dem Ziel, also ungefähr dort, wo auch die Dinosaurier aussterben.","Etwa 4 bis 7 Zentimeter vor dem Ziel, also auf dem allerletzten Stück der Strecke.","Etwa 4 bis 7 Meter vor dem Ziel, also als kleiner Schritt am Ende der Strecke.","Etwa 4 bis 7 Millimeter vor dem Ziel, also ungefähr die Länge eines Reiskorns."],"correctIndex":1,"explanation":"Die Rechnung ist ein einfacher Dreisatz: 200.000 bis 300.000 Jahre geteilt durch 4,54 Milliarden Jahre ergibt rund 0,004 bis 0,007 Prozent der Erdgeschichte. Auf 1.000 Metern sind das etwa 4 bis 7 Zentimeter. Zur Gegenprobe: Das Aussterben der Dinosaurier läge bei Meter 985, also etwa 15 Meter vor dem Ziel; der Mensch kommt erst etwa 4 bis 7 Zentimeter vor dem Ziel. Zwischen dem Aussterben der Dinosaurier und dem Auftauchen des Menschen liegt also fast die gesamte letzte Strecke. Die Menschheit ist ein geologischer Wimpernschlag am Ende der Strecke. Unsere Intuition ist für Tage und Lebenszeiten gemacht und überfordert sich bei Milliarden von Jahren, deshalb hilft es, die Größenordnung durch eine Verhältnisrechnung zu prüfen.","coreRule":"⚡ Schätze Größenordnungen durch ein Verhältnis, nicht nach dem Gefühl: Auf der Zeitleiste der Erde sind wir ein Wimpernschlag am Ende.","beleg":"Werkstück C.1.5 (Die Schmiede-Übung „Der Zeit-Spaziergang“; Kontext & Tiefe); Fn. gl-c-erdalter (Dalrymple 2001, S. 205, 213, 217–219)","status":"entwurf","scenario":"Ein Freund sagt: „Den modernen Menschen gibt es doch schon ewig – dass die Dinosaurier lange vor uns ausgestorben sind, ist ein kleiner Unterschied.“ Um ihm die Größenordnung greifbar zu machen, überträgst du die gesamte Erdgeschichte (4,54 Milliarden Jahre) auf einen Kilometer Wegstrecke: Der Start steht für die Entstehung der Erde, das Ziel für heute. Der moderne Mensch existiert seit etwa 200.000 bis 300.000 Jahren, die Dinosaurier starben vor etwa 66 Millionen Jahren aus.","kurz":"200.000 bis 300.000 Jahre sind nur etwa 0,004 bis 0,007 Prozent von 4,54 Milliarden Jahren, auf 1.000 Metern also 4 bis 7 Zentimeter. Der Fehler liegt darin, Millionen und Hunderttausende nach Gefühl zu vermischen, statt das Verhältnis auszurechnen.","prueffrage":"Wie viele Meter der Strecke entsprechen einem Zehntel Prozent der gesamten Erdgeschichte, und passen die Zeitspannen der Menschheit darunter oder darüber?","rueckmeldung":[{"option":0,"text":"Bei so großen Zahlen fühlt es sich plausibel an, dass Dinosaurier und Mensch fast am selben Punkt landen. Das Aussterben der Dinosaurier liegt aber rund 15 Meter vor dem Ziel, der Mensch erst auf den letzten Zentimetern."},{"option":2,"text":"Ende der Strecke und kleiner Schritt stimmen als Eindruck. Beim Umrechnen sind aber zwei Zehnerpotenzen verrutscht: 0,004 bis 0,007 Prozent von 1.000 Metern sind 4 bis 7 Zentimeter; ein Meterwert wäre hundertmal zu groß."},{"option":3,"text":"Dass der Mensch ganz am Ende auftaucht, trifft zu, und deshalb wirkt ein winziger Wert stimmig. Die Rechnung ergibt aber 4 bis 7 Zentimeter, nicht Millimeter; der Wert ist um den Faktor zehn zu klein."}],"familie":"groessenordnung-schaetzen","fertigkeit":"F4"},{"id":"qx-c1-019","clusterId":"C","werkstueckRef":"C.1.5","stufe":3,"question":"Ein Gesprächspartner zeigt dir das Fossil eines Meerestiers, das auf einem hohen Berg gefunden wurde, und sagt: „Das beweist eine weltweite Sintflut vor wenigen tausend Jahren.“ Welche Erwiderung nimmt den Fund ernst und erklärt ihn am sparsamsten, ohne die Tatsache selbst zu bestreiten?","options":["Das Meer stand früher mehrere tausend Meter höher und ist seither langsam wieder abgeflossen, ohne dass sich das Land bewegt hätte.","Die Gesteinsformen sehen nur wie Meerestiere aus, waren aber nie Lebewesen und entstanden durch bloße Kristallbildung.","Ehemaliger Meeresboden wurde durch die Bewegung der Erdplatten über Millionen Jahre langsam zu Hochgebirgen aufgefaltet.","Eine einzelne Überflutung erklärt den Fund zwar, sie dauerte nur länger und lief langsamer ab, als es die Überlieferung beschreibt."],"correctIndex":2,"explanation":"Der Fund selbst ist echt: Meerestiere lebten dort, wo heute Berge stehen. Offen ist nur, wie er dorthin kam. Die sparsamste Erklärung nimmt Prozesse, die sich heute noch beobachten lassen: Erdplatten bewegen sich, und ehemaliger Meeresboden wird über Millionen Jahre langsam zu Hochgebirgen aufgefaltet. Die radiometrische Datierung und die Abfolge der Gesteinsschichten belegen so lange Zeiträume (Tiefenzeit). Ein bloßes Abfließen des Meeres ohne Bewegung des Landes passt nicht zu dieser Erklärung. Die Idee, die Fossilien seien nie Lebewesen gewesen, erklärt den Fund nicht, sondern bestreitet ihn. Eine einzelne Überflutung erklärt weder diese Zeiträume noch die langsame Hebung. Gegen den Sintflut-Einwand hilft das Konzept der Tiefenzeit: Es bietet die langsame, aber mächtigere Erklärung.","coreRule":"⚡ Wenn ein Fund zu einer einzigen großen Katastrophe passt, prüfe, ob langsame, heute beobachtbare Prozesse über sehr lange Zeit denselben Befund sparsamer erklären.","beleg":"Werkstück C.1.5 (Werkbank-Frage; Red Flags, „Sintflut“)","status":"entwurf","scenario":"Auf einer Wanderung in den Alpen entdeckst du in einer Felswand Versteinerungen von Muscheln und Seelilien. Dein Begleiter hält sie für den Beweis einer einzigen großen Überflutung vor wenigen tausend Jahren.","quote":"","quoteLabel":"","kurz":"Der Fund ist echt, offen ist nur, wie er auf den Berg kam. Am sparsamsten erklärt ihn ein heute noch beobachtbarer Vorgang: Platten verschieben sich, und alter Meeresboden wird über Millionen Jahre zum Gebirge aufgefaltet. Eine Flut erklärt weder diese Zeit noch die Hebung.","prueffrage":"Stecken die Versteinerungen in einer einzigen Schicht oder in vielen übereinanderliegenden Gesteinsschichten der Felswand?","rueckmeldung":[{"option":0,"text":"Ein langsam sinkender Meeresspiegel scheint ohne bewegtes Land auszukommen. Für ein Meer mehrere tausend Meter über dem heutigen fehlt aber das Wasser; erst die Hebung des Landes erklärt die Höhe des Fundorts."},{"option":1,"text":"Die Fossilien zu bloßen Kristallen zu erklären, nimmt der Flut-Behauptung scheinbar die Grundlage. Muscheln und Seelilien zeigen aber erkennbar den Bau von Lebewesen, und so wird der Fund bestritten statt erklärt."},{"option":3,"text":"Ein Meer erklärt zunächst, warum dort Meerestiere liegen, und die gedehnte Zeit wirkt wie ein Kompromiss. Doch auch eine langsamere Überflutung erklärt nicht, wie Meeresboden in solche Höhen kam, und passt nicht zu Millionen Jahren langsamer Hebung."}],"familie":"sparsamste-erklaerung","fertigkeit":"F4"},{"id":"qx-c1-020","clusterId":"C","werkstueckRef":"C.1.5","stufe":4,"question":"Jemand sagt: „Das Klima hat sich schon immer verändert – heute ist nichts Besonderes.“ Du hast Daten aus Eisbohrkernen vor dir, die das Klima über rund 800.000 Jahre rekonstruieren. Welche Frage an diese Daten prüft die Behauptung am besten?","options":["Wie schnell stieg die CO₂-Konzentration in früheren Phasen im Vergleich zu heute, nicht nur: Hat sie sich überhaupt schon einmal verändert?","Gab es in der Erdgeschichte schon einmal irgendeine Veränderung der CO₂-Konzentration, die sich in den Daten nachweisen lässt?","Wie viele Jahre reichen die Eisbohrkerne insgesamt zurück, und welche Gesamtlänge haben die gebohrten Eissäulen?","Welche Forscher haben die Eisbohrkerne gesammelt, und welche Institute werten die Messdaten aus?"],"correctIndex":0,"explanation":"Der Satz „Das Klima hat sich schon immer verändert“ ist richtig, beweist aber wenig: Auch wenn Veränderung früher vorkam, sagt das nichts darüber, ob die heutige Veränderung vergleichbar ist. Entscheidend ist die Rate, also wie schnell sich etwas ändert, und nicht nur, ob. Genau das lässt sich mit langen Datenreihen prüfen. Die heutige CO₂-Konzentration liegt höher als in mindestens zwei Millionen Jahren; laut IPCC (2021) ist ihr Anstieg seit 1850 in den letzten 800.000 Jahren ohne Beispiel. Zudem hat sich die Erde seit 1970 schneller erwärmt als in jedem anderen Fünfzigjahreszeitraum der letzten zweitausend Jahre. Auch die schnellsten CO₂-Änderungsraten der letzten 56 Millionen Jahre lagen mindestens um den Faktor vier darunter (geringe Konfidenz). Wer nur fragt, ob es früher Veränderungen gab, übersieht den Kern: Eine wahre Aussage („Klima änderte sich immer“) kann trotzdem in die Irre führen, wenn sie das Tempo ausblendet.","coreRule":"⚡ „Das Klima änderte sich immer“ stimmt – aber die Frage ist, wie schnell. Prüfe die Änderungsrate, nicht nur das Vorkommen von Veränderung.","beleg":"Werkstück C.1.5 (Anwendung & Relevanz, „Im Kontext des Klimawandels (C.5.1)“); Fn. gl-c-ipcc-tempo (IPCC 2021, SPM A.2.1 und A.2.2, S. 8; Technical Summary S. 69)","status":"entwurf","scenario":"Eisbohrkerne enthalten eingeschlossene Luftbläschen aus vergangenen Zeiten. Aus ihnen lässt sich ablesen, wie hoch die CO₂-Konzentration in der Atmosphäre früher war und wie schnell sie sich änderte.","quote":"","quoteLabel":"","kurz":"Dass sich das Klima früher änderte, stimmt, trifft aber nicht den Kern: Entscheidend ist, wie schnell sich etwas änderte. Die Daten lassen sich auf das Tempo befragen, und gerade das heutige Tempo war in dieser Zeit offenbar ohne Beispiel.","prueffrage":"Würden Eisbohrkerne auch dann frühere CO₂-Schwankungen zeigen, wenn die heutige Änderung völlig neuartig wäre?","rueckmeldung":[{"option":1,"text":"Eine frühere Veränderung lässt sich in den Daten sicher finden, insofern stimmt die Aussage über den steten Klimawandel. Gerade deshalb unterscheidet ein solcher Fund nichts: Er lässt offen, ob die heutige Änderung vergleichbar ist."},{"option":2,"text":"Wie weit die Kerne zurückreichen, beschreibt die Datenbasis, etwa die rund 800.000 Jahre. Über Veränderungen sagt das nichts, und erst recht nichts darüber, ob heute etwas Besonderes geschieht."},{"option":3,"text":"Wer die Kerne gesammelt und ausgewertet hat, ist eine Frage nach der Herkunft der Daten. Sie klärt weder, wie schnell sich die CO₂-Konzentration änderte, noch, wie die Änderung heute im Vergleich liegt."}],"familie":"groessenordnung-schaetzen","fertigkeit":"F4"},{"id":"qx-c1-021","clusterId":"C","werkstueckRef":"C.1.6","stufe":1,"question":"Jemand sagt: „In ein paar tausend Jahren haben wir einfach bessere Antriebe, dann fliegen wir mit Lichtgeschwindigkeit zu den Nachbarsternen.“ Welcher Einwand trifft den Kern dieser Annahme am besten?","options":["Mit besserer Technik lässt sich der Energiebedarf immer weiter senken, deshalb ist Lichttempo nur eine Frage der Zeit.","Je näher ein Objekt mit Masse dem Lichttempo kommt, desto mehr Energie braucht es; für das Erreichen selbst wäre unendlich viel nötig.","Bei hohem Tempo bleibt die Zeit an Bord stehen, deshalb kann ein Schiff dort nicht weiter beschleunigen.","Staub und Gas im All würden ein so schnelles Schiff so stark aufheizen, dass es noch vor dem Lichttempo verdampft."],"correctIndex":1,"explanation":"Die Annahme übersieht, dass es hier nicht um einen Mangel an Technik geht, sondern um ein Prinzip: Für alles mit Masse wächst der Energiebedarf bei Annäherung an die Lichtgeschwindigkeit (ca. 300.000 km/s) immer weiter an und würde für das Erreichen selbst gegen unendlich gehen. Bessere Antriebe können diese Schwelle also nicht abschaffen, höchstens den Weg dorthin effizienter machen. Wer „es braucht nur bessere Technik“ sagt, behauptet daher etwas, das die Physik nicht hergibt, und müsste einen konkreten Mechanismus nennen, der die Energieschranke umgeht. Das Argument „irgendwie wird sich das lösen“ ersetzt keinen solchen Beleg. Die anderen Einwände klingen plausibel, treffen aber nicht den Kern: Die Zeit an Bord vergeht bei hohem Tempo nur langsamer, sie bleibt nicht stehen. Der Kern ist die Energieschranke, nicht ein Nebeneffekt der Reise.","coreRule":"⚡ Für alles mit Masse ist die Lichtgeschwindigkeit eine Schwelle, die unendlich viel Energie kosten würde: Das ist ein Prinzip, kein Technikproblem.","beleg":"Werkstück C.1.6 (Kontext & Tiefe, „Die kosmische Temposchwelle“)","status":"entwurf","scenario":"In einer Diskussion über Reisen zu anderen Sternen wird argumentiert, es sei nur eine Frage der Antriebstechnik, bis Raumschiffe mit Masse die Lichtgeschwindigkeit erreichen.","kurz":"Es geht nicht um fehlende Technik, sondern um ein Prinzip: Für alles mit Masse wächst der Energiebedarf nahe der Lichtgeschwindigkeit ohne Grenze. Bessere Antriebe machen den Weg effizienter, die Schwelle selbst schaffen sie nicht ab.","prueffrage":"Welcher konkrete Mechanismus soll nach dieser Aussage das Hindernis aus dem Weg räumen, und nennt sie einen?","rueckmeldung":[{"option":0,"text":"Bessere Antriebe verschwenden tatsächlich weniger Energie. Die Bewegungsenergie selbst, die ein Körper mit Masse nahe dem Lichttempo braucht, legt aber die Physik fest; für das Erreichen wüchse sie ins Unendliche, das senkt keine Technik."},{"option":2,"text":"Dass die Zeit an Bord bei hohem Tempo langsamer vergeht, ist ein echter Effekt, doch sie bleibt nicht stehen. Zudem ist das eine Begleiterscheinung der Reise, nicht das, was das Erreichen des Lichttempos verhindert."},{"option":3,"text":"Staub und Gas im All sind für sehr schnelle Schiffe ein ernstes Thema, aber ein Nebenproblem. Auch im völlig leeren Raum bliebe die Energieschranke bestehen, sie liegt im Prinzip und nicht in der Umgebung."}],"familie":"bilanz-pruefen","fertigkeit":"F1"},{"id":"qx-c1-022","clusterId":"C","werkstueckRef":"C.1.6","stufe":2,"question":"Du willst die Behauptung mit einer Überschlagsrechnung prüfen: Wie lange bräuchte die schnellste Sonde der Menschheit für den Hinflug zum nächsten Stern etwa?","scenario":"Ein Mann behauptet im Gespräch: „Außerirdische können uns ganz leicht besuchen. Unsere schnellste Raumsonde fliegt doch schon mit rund 700.000 km/h, da ist der nächste Stern praktisch um die Ecke.“ Der nächste Stern, Proxima Centauri, ist etwa 4,2 Lichtjahre entfernt, das sind rund 40 Billionen Kilometer. Ein Lichtjahr ist die Strecke, die Licht in einem Jahr zurücklegt; Licht fliegt mit etwa 300.000 km/s, also rund 1,08 Milliarden km/h.","options":["Etwa 66 Jahre, kaum länger als ein langes Menschenleben, wenn das Höchsttempo gehalten wird.","Etwa 660 Jahre, mehr als zehn Menschenleben, aber noch im Bereich vorstellbarer Generationenschiffe.","Etwa 6.600 Jahre, selbst im Tempo der schnellsten Sonde dauert der Hinflug Jahrtausende.","Etwa 66.000 Jahre, so lange würde die Sonde bis zum nächsten Stern unterwegs sein."],"correctIndex":2,"explanation":"Die Sonde ist mit rund 700.000 km/h nur etwa 1/1.500 so schnell wie das Licht (700.000 geteilt durch 1,08 Milliarden). Licht braucht für 4,2 Lichtjahre 4,2 Jahre, die Sonde also rund 1.500-mal so lang: grob gerechnet 6.300 Jahre, mit genaueren Werten (4,24 Lichtjahre, rund 690.000 km/h) gut 6.600 Jahre. Entscheidend ist die Größenordnung: Jahrtausende, nicht Jahrzehnte oder Jahrhunderte, und das Tempo ist noch großzügig angesetzt, denn die Sonde erreicht es nur im Sturz auf die Sonne zu; Voyager 1 mit rund 17 km/s bräuchte etwa 75.000 Jahre. Dass der Stern „praktisch um die Ecke“ liege, hält der Rechnung also nicht stand. Wer „leichte“ Besuche behauptet, muss erklären, wie ein Fahrzeug um ein Vielfaches schneller sein soll als alles, was wir bauen können.","coreRule":"⚡ Ein beeindruckend klingendes Tempo sagt nichts, solange du es nicht mit der Entfernung vergleichst: Rechne die Größenordnung nach.","beleg":"Werkstück C.1.6 (Die unmögliche Reise); Fn. gl-c-proxima (Parker Solar Probe Ende 2024, rund 690.000 km/h; Voyager 1 rund 75.000 Jahre). Szenario auf Behauptungsprüfung umgebaut, Lichtgeschwindigkeit ca. 300.000 km/s aus der Analyse, Umrechnung in km/h Allgemeinwissen.","status":"entwurf","kurz":"Die Sonde fliegt nur mit etwa 1/1.500 der Lichtgeschwindigkeit und braucht also rund 1.500-mal so lange wie das Licht mit seinen 4,2 Jahren: etwa 6.300 bis 6.600 Jahre. „Praktisch um die Ecke“ täuscht, weil ein im Alltag riesiges Tempo an Sternentfernungen gemessen winzig ist.","prueffrage":"Wie oft passt die Sondengeschwindigkeit in die Geschwindigkeit des Lichts, und was bedeutet das für die Reisezeit im Vergleich zu den 4,2 Jahren, die Licht braucht?","rueckmeldung":[{"option":0,"text":"Ein Menschenleben als Reisedauer klingt beinahe machbar, weil die Zahl 700.000 km/h so groß wirkt. Gegen das Licht gerechnet ist die Sonde aber nur etwa 1/1.500 so schnell, die Zeit wird also nicht zu 66 Jahren, sondern zu Jahrtausenden."},{"option":1,"text":"660 Jahre klingen schon nach einer gewaltigen Reise, deshalb wirkt der Wert vorsichtig genug. Mit 4,2 Jahren Lichtlaufzeit mal etwa 1.500 kommt man aber auf Jahrtausende; 660 Jahre sind rund zehnmal zu wenig."},{"option":3,"text":"Wer die riesigen Entfernungen ernst nimmt, greift leicht zur größten Zahl. Die Überschlagsrechnung ergibt für die schnellste Sonde aber rund 6.600 Jahre, ein Zehntel davon; Zehntausende Jahre bräuchte erst eine langsamere Sonde wie Voyager 1."}],"familie":"groessenordnung-schaetzen","fertigkeit":"F4"},{"id":"qx-c1-023","clusterId":"C","werkstueckRef":"C.1.6","stufe":3,"question":"Drei Personen äußern sich zu Außerirdischen. Wer überschreitet die Grenze von legitimer Spekulation zur Pseudowissenschaft?","options":["Person A, denn schon die Annahme weiterer Zivilisationen in der Milchstraße ist unbelegt und damit unwissenschaftlich.","Person B, denn sie stellt einen Besuch als Tatsache hin und ersetzt Belege und Mechanismus durch „sicher irgendwie“.","Person A, denn sie behauptet, es gebe außerirdisches Leben, und tut das ohne jeden Beleg als Tatsache.","Person C, denn schon das Gedankenspiel mit Konzepten, die nach heutigem Wissen unmöglich sind, ist unwissenschaftlich."],"correctIndex":1,"explanation":"Eine offene Frage zu stellen und danach zu suchen, ist legitim: Person A behauptet nichts als Tatsache, sondern prüft, und auch Person C kennzeichnet ihr Gedankenexperiment offen als Spekulation ohne Beleg. Person B dagegen behauptet einen Besuch als Faktum, obwohl die Hürden gewaltig sind: Selbst mit der Geschwindigkeit der schnellsten Sonde (Parker Solar Probe) bräuchte man rund 6.600 Jahre bis zum nächsten Stern, und nichts mit Masse erreicht Lichtgeschwindigkeit. „Sicher irgendwie gelöst“ bietet keinen plausiblen Mechanismus und ist ein klassisches Warnsignal (Argument aus Unwissenheit). Die Grenze verläuft also nicht beim Thema, sondern bei der Art, wie mit Belegen umgegangen wird.","coreRule":"⚡ Suchen und Fragen ist Wissenschaft, Behaupten ohne Beleg ist Pseudowissenschaft.","beleg":"Werkstück C.1.6 (Der Kipppunkt; Red Flags)","status":"entwurf","scenario":"A: „Es wäre überraschend, wenn bei Hunderten Milliarden Sternen nur wir Leben hervorgebracht hätten. Deshalb suche ich mit Radioteleskopen nach Signalen.“ B: „Eine Zivilisation, die Millionen Jahre älter ist als wir, hat die Entfernungen sicher irgendwie überwunden. Also waren Außerirdische hier und haben die Pyramiden gebaut.“ C: „Warp-Antriebe sind bisher reine Science-Fiction. Als Gedankenexperiment finde ich sie trotzdem spannend, auch wenn es keinen Beleg gibt.“","quote":"","quoteLabel":"","kurz":"Nicht das Thema Außerirdische macht eine Aussage zur Pseudowissenschaft, sondern der Umgang mit Belegen: Person B stellt einen Besuch als Tatsache hin und ersetzt Mechanismus und Belege durch „sicher irgendwie“.","prueffrage":"Was genau behauptet Person A über außerirdisches Leben, und was tut sie, um es herauszufinden?","rueckmeldung":[{"option":0,"text":"Dass etwas unbelegt ist, macht es nicht unwissenschaftlich, denn jede Suche beginnt mit einer noch unbelegten Vermutung. Person A sagt nur, ein Alleinsein wäre überraschend, und prüft das mit Radioteleskopen, das ist eine offene, prüfbare Frage."},{"option":2,"text":"Es stimmt, dass es bisher keinen Beleg für außerirdisches Leben gibt. Person A gibt es aber nicht als Tatsache aus, sondern hält es für wahrscheinlich und sucht danach; eine Vermutung zu prüfen heißt nicht, sie für gesichert zu erklären."},{"option":3,"text":"Ein Gedankenspiel mit Warp-Antrieben wirkt unwissenschaftlich, doch Person C nennt es selbst Science-Fiction ohne Beleg. Offen gekennzeichnete Spekulation täuscht niemanden; problematisch ist erst, Unbelegtes als Tatsache auszugeben."}],"familie":"wissenschaft-abgrenzen","fertigkeit":"F1"},{"id":"qx-c1-024","clusterId":"C","werkstueckRef":"C.1.6","stufe":4,"question":"Ein Gesprächspartner hält dagegen, dass interstellare Besuche physikalisch kaum plausibel sind. Er sagt: „Eine Zivilisation, die Millionen Jahre älter ist als wir, hat Technik wie Magie – unsere Physik gilt für sie vielleicht gar nicht.“ Welche Antwort ist die stärkste?","options":["Du bestreitest nicht, dass es solche Technik geben könnte, fragst aber, wer für die Behauptung Belege liefern muss und welche Erklärung weniger unbelegte Annahmen braucht.","Du verlangst zuerst den Beweis, dass es solche Technik nicht geben kann, denn solange der fehlt, bleibt der Einwand als offene Möglichkeit bestehen und braucht keine Belege.","Du räumst ein, dass sich Magie-Technik und menschlicher Einfallsreichtum nicht ausschließen lassen, und hältst beide Erklärungen für gleich wahrscheinlich, ohne Belege zu verlangen.","Du wendest ein, dass die heutige Physik gut belegt ist und Wundertechnik deshalb ausgeschlossen werden kann, ohne dafür weitere Belege zu brauchen."],"correctIndex":0,"explanation":"Der Einwand schließt jede Gegenprobe im Voraus aus: Gilt die bekannte Physik „vielleicht gar nicht“, lässt sich mit nichts mehr argumentieren. Zwei Werkzeuge greifen hier. Erstens die Beweislast: Wer eine außergewöhnliche Behauptung aufstellt, muss sie belegen, und ein Gegner muss nicht das Unmögliche widerlegen. Zweitens Ockhams Rasiermesser: Solange keine außergewöhnlichen Beweise vorliegen, ist die Erklärung vorzuziehen, die mit weniger unbelegten Annahmen auskommt. „Menschen haben es selbst gebaut“ braucht keine zusätzliche, unbelegte Wundertechnik. Die Antwort, erst den Gegenbeweis zu verlangen, kehrt die Beweislast um. Die Antwort, beide Erklärungen für gleich wahrscheinlich zu halten, ignoriert, dass es auf Belege und die Zahl der Annahmen ankommt. Und die Antwort, Wundertechnik pauschal auszuschließen, überzieht in die Gegenrichtung, denn auch „unmöglich“ ist eine Behauptung, die sich nicht belegen lässt.","coreRule":"⚡ Wer „Magie-Technik“ behauptet, trägt die Beweislast – und bis Belege kommen, gewinnt die Erklärung mit den wenigsten unbelegten Annahmen.","beleg":"Werkstück C.1.6 (Werkbank-Frage; verlinkt auf Werkstück A.4 Beweislast und A.1.1 Ockhams Rasiermesser)","status":"entwurf","scenario":"In einer Diskussion über angebliche Besuche Außerirdischer weist jemand auf Sternentfernungen und die Lichtgeschwindigkeit hin.","kurz":"Wer eine außergewöhnliche Behauptung aufstellt, muss sie belegen, und vorzuziehen ist die Erklärung, die mit weniger unbelegten Annahmen auskommt. Der Fehler wäre, den Einwand für stark zu halten, nur weil sich ein „vielleicht“ nie widerlegen lässt.","prueffrage":"Ließe sich der Einwand „unsere Physik gilt vielleicht gar nicht“ durch irgendeine Beobachtung je widerlegen?","rueckmeldung":[{"option":1,"text":"Dass sich solche Technik nicht logisch ausschließen lässt, stimmt. Daraus folgt aber keine Pflicht zum Gegenbeweis: Wer Wundertechnik behauptet, muss sie belegen; so wird die Beweislast umgekehrt."},{"option":2,"text":"Beide Erklärungen lassen sich nicht strikt ausschließen. Gleich wahrscheinlich sind sie deshalb noch lange nicht, denn es zählt, wofür es Belege gibt und wie viele unbelegte Annahmen jede Erklärung braucht."},{"option":3,"text":"Die heutige Physik ist tatsächlich gut belegt. „Ausgeschlossen“ ist aber selbst eine Behauptung, die sich nicht belegen lässt. Tragfähiger ist es, Belege für die außergewöhnliche Behauptung zu verlangen."}],"familie":"beweislast-klaeren","fertigkeit":"F1"},{"id":"qx-c1-025","clusterId":"C","werkstueckRef":"C.2.1","stufe":1,"question":"Mit welchem Einwand lässt sich die Behauptung des Verkäufers am besten prüfen?","options":["Stoffe bestehen aus einzelnen Teilchen. Nach genügend Verdünnungsschritten ist statistisch kein Teilchen des Wirkstoffs mehr enthalten, und was fehlt, kann nicht wirken.","Je stärker man verdünnt, desto gleichmäßiger verteilen sich die Teilchen im Lösungsmittel. Die Menge sinkt, aber die Wirkung des Stoffes bleibt dabei erhalten.","Je stärker man verdünnt, desto weniger Teilchen sind noch enthalten. Dafür entfaltet jedes einzelne Teilchen eine größere Wirkung als in der Ausgangslösung.","Eine Verdünnung wirkt nur dann, wenn sie in einem sauberen Labor erfolgt ist. Verunreinigungen schwächen die Wirkung des Wirkstoffs sonst deutlich ab."],"correctIndex":0,"explanation":"Materie ist nicht unendlich teilbar: Man kann einen Zuckerwürfel nicht beliebig oft halbieren, irgendwann bleibt ein einzelnes Zuckermolekül. Weil jeder Verdünnungsschritt die Teilchenzahl senkt, ist irgendwann im Schnitt weniger als ein Teilchen übrig; bei Schritten von 1 zu 100 ist diese Grenze schon nach etwa zwölf Schritten erreicht (Verdünnung 1 zu 10²⁴). Bei 30 Schritten (Verdünnung 1 zu 10⁶⁰) ist sie weit überschritten: Selbst bei einer Ausgangslösung von einem Mol pro Liter, also rund 6 × 10²³ Molekülen, blieben im Mittel nur etwa 6 × 10⁻³⁷ Moleküle pro Liter. Die Behauptung „je verdünnter, desto stärker“ kehrt die Dosis-Wirkungs-Beziehung um und ist ein klares Warnsignal. Wer sie trotzdem aufrechterhält, muss eine nicht stoffliche Ursache behaupten und dafür eigene Belege liefern.","coreRule":"⚡ Materie besteht aus Teilchen. Wer immer weiter verdünnt, landet irgendwann bei null Teilchen – und was nicht mehr enthalten ist, kann nicht wirken.","beleg":"Werkstück C.2.1 (Kernidee; Avogadro-Grenze; Red Flags; Fußnoten gl-c-avogadro, gl-c-c30). Frage zur Denkaufgabe umgebaut: Behauptung prüfen statt Definition abfragen.","status":"entwurf","scenario":"Ein Verkäufer bietet ein Mittel an, bei dem ein Wirkstoff 30-mal hintereinander im Verhältnis 1 zu 100 verdünnt wurde. Er sagt: „Je öfter man verdünnt, desto stärker wirkt es. Verdünnen kann man schließlich unendlich weit.“","kurz":"Stoffe bestehen aus Teilchen, und jede Verdünnung senkt deren Zahl. Bei 30 Schritten im Verhältnis 1 zu 100 ist im Schnitt kein einziges Teilchen mehr übrig. Der Fehler liegt darin, Verdünnung wie ein stufenloses Verteilen zu denken, das nie endet.","prueffrage":"Wie viele Teilchen des Wirkstoffs wären nach 30 solchen Schritten im Mittel in einem Liter noch enthalten?","rueckmeldung":[{"option":1,"text":"Gleichmäßiges Verteilen klingt, als bliebe vom Stoff überall ein wenig erhalten. Mit jedem Schritt sinkt aber die Zahl der Teilchen, bis im Mittel keines mehr übrig ist, und was fehlt, kann nicht wirken."},{"option":2,"text":"Dass die Teilchenzahl sinkt, stimmt. Ein einzelnes Molekül bleibt aber dasselbe, ob viel oder wenig Wasser es umgibt; weniger Stoff bedeutet in der Regel weniger Wirkung, nicht mehr."},{"option":3,"text":"Saubere Arbeit ist sinnvoll, trifft hier aber nicht den Kern. Selbst im reinsten Labor ist nach so vielen Schritten vom Wirkstoff nichts mehr übrig; die Frage ist die Teilchenzahl, nicht Verunreinigung."}],"familie":"verduennung-nachrechnen","fertigkeit":"F4"},{"id":"qx-c1-026","clusterId":"C","werkstueckRef":"C.2.1","stufe":2,"question":"Ein Anbieter wirbt: „Unser Mittel in C30 enthält die volle Kraft der Ausgangssubstanz.“ C30 bedeutet: 30 Verdünnungsschritte im Verhältnis 1 zu 100, also insgesamt 1 zu 10⁶⁰. Ein Mol (ca. 6 × 10²³ Moleküle) der Ausgangssubstanz steckt in einem Liter Urtinktur. Du prüfst das Versprechen mit einer Überschlagsrechnung: Wie viel Lösung müsstest du einnehmen, um mit etwa 50 % Chance ein einziges Molekül der Ausgangssubstanz zu erwischen?","options":["Ein Schwimmbecken mit einigen zehntausend Litern – mehr, als jemand einnehmen könnte, aber noch ein überschaubarer Raum.","Die gesamte Wassermenge aller Weltmeere – eine Menge, die man sich noch als Ozean-Kugel vorstellen kann.","Eine Kugel mit dem Durchmesser der Erde, rund 12.700 Kilometer – unvorstellbar viel Lösung für ein einzelnes Molekül.","Eine Kugel mit dem Durchmesser des Abstands Erde–Sonne, also rund 150 Millionen Kilometer – unvorstellbar viel Lösung für ein einzelnes Molekül."],"correctIndex":3,"explanation":"Rechne in Größenordnungen: Ein Liter Urtinktur enthält etwa 6 × 10²³ Moleküle. Nach der Verdünnung um den Faktor 10⁶⁰ bleiben im Mittel rund 6 × 10⁻³⁷ Moleküle pro Liter. Für ein einziges erwartetes Molekül brauchst du also etwa 1,7 × 10³⁶ Liter, das ist eine Kugel mit rund 1,5 × 10¹¹ Metern Durchmesser, ungefähr der Abstand zwischen Erde und Sonne. Für eine 50-Prozent-Chance genügt etwas weniger, rund das 0,9-Fache dieses Durchmessers; bei einer schwächeren Urtinktur würde die Kugel noch größer. Die anderen Größen (Schwimmbecken, Weltmeere, Erdkugel) liegen jeweils um viele Zehnerpotenzen unter den benötigten rund 10³⁶ Litern. Der Denkfehler dahinter ist, sich bei Verdünnungen von 10⁶⁰ Vorstellbares einzureden, statt nachzurechnen. Die Rechnung zeigt: In einer üblichen Dosis ist nichts von der Ursubstanz zu erwarten, das Werbeversprechen von der „vollen Kraft“ ist stofflich leer.","coreRule":"⚡ Bei extremen Verdünnungen gilt: erst die Teilchenzahl überschlagen, dann über die Wirkung reden. Ab etwa 1 zu 10²⁴ ist pro Mol statistisch nur noch rund ein Molekül der Ausgangssubstanz zu erwarten; darüber praktisch keines mehr.","beleg":"Werkstück C.2.1 (Kontext & Tiefe, „Die mathematische Realität der Homöopathie“); Fn. gl-c-c30 (Überschlag für eine einmolare Urtinktur)","status":"entwurf","scenario":"","kurz":"Nach 10⁶⁰-facher Verdünnung bleiben nur etwa 6 × 10⁻³⁷ Moleküle pro Liter. Für ein einziges Molekül bräuchtest du eine Lösungskugel von der Größe des Abstands Erde–Sonne. Das Gefühl für „sehr stark verdünnt“ versagt hier; erst Nachrechnen zeigt die Leere.","prueffrage":"Wie viele Moleküle bleiben im Mittel in einem Liter, wenn 6 × 10²³ Moleküle um den Faktor 10⁶⁰ verdünnt werden?","rueckmeldung":[{"option":0,"text":"Ein Schwimmbecken ist schon mehr, als jemand je einnehmen könnte, deshalb wirkt es ausreichend groß. Nachgerechnet fehlen aber rund dreißig Zehnerpotenzen: Gebraucht würden etwa 10³⁶ Liter, ein Becken fasst nur 10⁴ bis 10⁵ Liter."},{"option":1,"text":"Die Weltmeere sind ein Bild, das sich gerade noch fassen lässt, und so liegt die Wahl nahe. Sie fassen aber nur etwa 10²¹ Liter, benötigt werden rund 10³⁶, also um rund fünfzehn Zehnerpotenzen mehr. Ein Molekül wäre darin nicht zu erwarten."},{"option":2,"text":"Eine Kugel von Erdgröße ist schon gewaltig, und damit ist die Grenze des Vorstellbaren überschritten. Sie fasst aber nur etwa 10²⁴ Liter, benötigt werden rund 10³⁶, also immer noch um etwa zwölf Zehnerpotenzen mehr."}],"familie":"verduennung-nachrechnen","fertigkeit":"F4"},{"id":"qx-c1-027","clusterId":"C","werkstueckRef":"C.2.1","stufe":3,"question":"Ein Homöopath sagt: „Du denkst zu materialistisch – es geht um eine geistartige Information, die beim Potenzieren auf den Trägerstoff übergeht.“ Du willst im Gespräch bleiben und nichts behaupten, was du selbst nicht belegen kannst. Welche Antwort ist am sinnvollsten?","options":["Du versuchst zu beweisen, dass es keine geistartige Information gibt, und siehst das Gespräch erst als gewonnen an, wenn er es eingesteht.","Du fragst, wie sich die Wirkung dieser Information von der Wirkung des bloßen Glaubens daran unterscheiden ließe.","Du hältst fest, dass „Geist“ in der Physik nicht vorkommt, und beendest das Gespräch, weil damit für dich alles gesagt ist.","Du räumst ein, dass sich solche Information grundsätzlich nicht prüfen lässt, und behandelst ihre Wirkung deshalb als gleichwertig mit Scheinmedikamenten."],"correctIndex":1,"explanation":"Am sinnvollsten ist es, nicht die Existenz der „geistartigen Information“ zu widerlegen, sondern zu fragen, wie sich ihre Wirkung von der reinen Wirkung des Glaubens daran unterscheiden lässt. Dafür dienen der Placebo-Effekt und die Hierarchie der Evidenz: Eine behauptete Wirkung zählt erst, wenn sie sich vom Glauben daran trennen lässt. So gibst du dem Gegenüber die Chance, seine Behauptung testbar zu machen, und das Gespräch bleibt offen. Wer dagegen die Existenz der Information widerlegen will, lässt sich auf ein Spiel ein, das im Kreis läuft. Das Gespräch einfach abzubrechen bietet keinen Test an. Und die Behauptung, Information sei grundsätzlich nicht prüfbar, wäre selbst unbelegt: Dass eine Wirkung nicht über den Glauben hinausgeht, folgt aus einem Test, nicht aus einer Vorannahme.","coreRule":"⚡ Frag nicht „Beweise, dass es sie nicht gibt“, sondern „Woran würden wir eine Wirkung erkennen, und wie unterscheiden wir sie vom Glauben daran?“","beleg":"Werkstück C.2.1 (Werkbank-Frage; Anwendung & Relevanz, „Bei anderen ‚Informationsmedizin‘-Systemen“)","status":"entwurf","scenario":"","kurz":"Testbar wird die Behauptung, wenn du fragst, wie sich die Wirkung der „Information“ von der Wirkung des Glaubens daran trennen lässt. Ihre Existenz widerlegen zu wollen, liegt näher, läuft aber im Kreis und liefert keinen Test.","prueffrage":"Könnte irgendeine Beobachtung den Homöopathen davon überzeugen, dass es die „geistartige Information“ nicht gibt?","rueckmeldung":[{"option":0,"text":"Eine unbelegte Behauptung lädt dazu ein, sie direkt zu widerlegen. Das Nichtvorhandensein einer „Information“ lässt sich aber kaum beweisen, und ein Gespräch, das nur Gewinner und Verlierer kennt, läuft im Kreis."},{"option":2,"text":"Dass „Geist“ in der Physik nicht als Größe vorkommt, ist ein berechtigter Hinweis. Wer daraufhin aussteigt, bietet aber keinen Test an und lässt offen, wie sich die behauptete Wirkung überprüfen ließe. Das Gespräch endet, ohne dass etwas geklärt ist."},{"option":3,"text":"Dass die „Information“ schwer zu fassen ist, legt nahe, sie sei gar nicht prüfbar. Doch „grundsätzlich nicht prüfbar“ wäre selbst unbelegt: Ob die Wirkung über die eines Scheinmedikaments hinausgeht, zeigt erst ein Test, keine Vorannahme."}],"familie":"widerlegung-benennen","fertigkeit":"F1"},{"id":"qx-c1-028","clusterId":"C","werkstueckRef":"C.2.1","stufe":4,"question":"Ein Anbieter verspricht Heilung durch „digital übertragene Schwingungsinformationen“, ganz ohne Wirkstoff. Mit welchem Einwand kannst du diese Behauptung am besten prüfen?","options":["Information lässt sich nur dann beurteilen, wenn man zuvor die genaue Funktionsweise des Geräts kennt.","Der Körper reagiert auf viele Reize unbewusst, daher lässt sich eine solche Wirkung nicht von vornherein ausschließen.","Information braucht einen physikalischen Träger, und ohne Teilchen der Substanz im Wasser gibt es nichts, was wirken könnte.","Digitale Übertragung ist verlustfrei, deshalb müsste die Wirkung der Substanz vollständig im Wasser ankommen."],"correctIndex":2,"explanation":"Information braucht einen physikalischen Träger. Eine Behauptung, die Wirkung ohne jeden Wirkstoff verspricht, muss deshalb erklären können, was genau übertragen wird und woran es im Wasser steckt. Ohne Moleküle der Substanz im Wasser gibt es keinen Träger, der etwas übertragen könnte. Dazu kommt: Materie ist nicht unendlich teilbar. Jenseits von etwa C12 ist statistisch kein einziges Molekül der Ausgangssubstanz mehr in der Lösung, und dann bleibt nichts übrig, was wirken könnte. Wer „Information“ ohne Träger behauptet, verschiebt die Frage nur, statt sie zu beantworten. Die anderen Einwände weichen aus: Dass man die Funktionsweise nicht kennt, sagt nichts darüber, ob ein Träger vorhanden ist. Dass der Körper auf Reize reagiert, erklärt nicht, warum die Substanz selbst wirken soll. Und Verlustfreiheit digitaler Kopien gilt für Daten auf Datenträgern, nicht für eine Wirkung im Wasser.","coreRule":"⚡ Ohne Träger keine Information, ohne Teilchen keine Wirkung.","beleg":"Werkstück C.2.1 (Anwendung & Relevanz, „Bei anderen ‚Informationsmedizin‘-Systemen“; Red Flags)","status":"entwurf","scenario":"In der Werbung heißt es: „Unser Gerät überträgt die Heilinformation der Substanz digital auf Ihr Trinkwasser. Es ist kein Wirkstoff nötig, die Information genügt.“","kurz":"Information braucht einen physikalischen Träger. Wer Wirkung ganz ohne Wirkstoff verspricht, muss zeigen, was im Wasser überhaupt steckt. Ohne Teilchen der Substanz bleibt nichts, was wirken könnte; „Information“ verschiebt die Frage nur.","prueffrage":"Würde sich am Wasser etwas ändern, wenn das Gerät statt der Heilinformation eine leere Datei überträgt, und wie ließe sich das prüfen?","rueckmeldung":[{"option":0,"text":"Wer die Funktionsweise nicht kennt, kann Einzelheiten tatsächlich nicht widerlegen. Prüfen lässt sich die Behauptung trotzdem: Wirkung ohne Wirkstoff verlangt einen Träger im Wasser, und der fehlt unabhängig von der Technik."},{"option":1,"text":"Dass der Körper unbewusst auf Reize reagiert, stimmt. Es beantwortet aber nicht, warum die Substanz selbst wirken soll, und prüft die Behauptung nicht. Die Frage nach einem Träger im Wasser bleibt offen."},{"option":3,"text":"Digitale Kopien sind bei Daten auf Datenträgern verlustfrei. Über eine Wirkung im Wasser sagt das nichts, und es setzt schon voraus, dass die Wirkung als übertragbare Information vorliegt; genau das ist die unbelegte Behauptung."}],"familie":"verduennung-nachrechnen","fertigkeit":"F4"},{"id":"qx-c1-029","clusterId":"C","werkstueckRef":"C.2.2","stufe":1,"question":"Was ist an der Aussage der Mitbewohnerin fehlerhaft, und was ist chemisch tatsächlich passiert?","scenario":"Jemand toastet eine Scheibe Brot zu lange. Sie wird schwarz und knusprig, es steigt Rauch auf, und die verkohlte Scheibe wiegt deutlich weniger als vorher. Eine Mitbewohnerin meint: „Beim Verbrennen wird Materie zerstört, sonst müsste die Scheibe ja gleich viel wiegen.“","options":["Die Hitze hat die Bindungen im Brot nicht verändert, es hat sich nur verfärbt, weshalb nichts Neues entstanden ist und der Gewichtsverlust auf Austrocknung beruht.","Die Kohlenstoffatome des Brots haben sich unter der Hitze in Sauerstoffatome verwandelt, die als Gas entwichen sind, und das erklärt den Gewichtsverlust.","Ein Teil der Brotmaterie wurde bei der Hitze in Energie umgewandelt und ist dadurch aus der Welt verschwunden, und das erklärt den Gewichtsverlust.","Die Bindungen im Brot sind aufgebrochen und dieselben Atome haben sich neu angeordnet, zum Teil zu Kruste, zum Teil zu Gasen wie CO₂ und Wasserdampf, die entwichen sind."],"correctIndex":3,"explanation":"Die Mitbewohnerin schließt vom Gewichtsverlust auf zerstörte Materie. Dieser Schluss trägt nicht: Die Scheibe wiegt weniger, weil Wasserdampf, Kohlendioxid und andere Gase im Rauch entweichen. Die Hitze bricht die Bindungen der Kohlenhydrat-Moleküle auf, und die Atome ordnen sich neu an: Ein Großteil des Kohlenstoffs bleibt als schwarze Kruste zurück, Wasserstoff, Sauerstoff und ein Teil des Kohlenstoffs entweichen als Gase; Sauerstoff steckt dafür schon reichlich in den Kohlenhydraten, ein Teil kann auch aus der Luft kommen. Bei einer chemischen Reaktion gehen keine Atome verloren und es kommen keine hinzu, nur ihre Anordnung ändert sich; Elemente wandeln sich erst bei Kernreaktionen um. Mit „nur verfärbt“ lässt sich die neue Kruste mit ihren neuen Eigenschaften nicht erklären.","coreRule":"⚡ Chemie ordnet Atome neu an: Atome entstehen nicht und verschwinden nicht. Fehlt Masse, sucht man die unsichtbaren Produkte, statt Zerstörung anzunehmen.","beleg":"Werkstück C.2.2 (Das verbrannte Brot; Kernidee; Kontext & Tiefe, „Materie bleibt erhalten“)","status":"entwurf","kurz":"Die Scheibe wiegt weniger, weil Gase wie CO₂ und Wasserdampf entweichen. Die Atome sind alle noch da, nur anders angeordnet. Wer vom Gewichtsverlust auf zerstörte Materie schließt, übersieht, was durch die Luft abzieht.","prueffrage":"Was geschieht mit allem, was beim Toasten als Rauch oder Dampf aufsteigt, und wo würdest du es mitwiegen?","rueckmeldung":[{"option":0,"text":"Ein Teil des Gewichtsverlusts ist tatsächlich Wasser, das verdampft. Aber die schwarze, knusprige Kruste und der Rauch zeigen, dass neue Stoffe entstanden sind. Mit bloßer Verfärbung lässt sich das nicht erklären."},{"option":1,"text":"Dass Gas entweicht und die Scheibe dadurch leichter wird, stimmt. Atome verwandeln sich bei Hitze aber nicht in andere Elemente: Der Kohlenstoff bleibt Kohlenstoff, ob in der schwarzen Kruste oder im entweichenden CO₂."},{"option":2,"text":"Masse und Energie hängen physikalisch zusammen, deshalb liegt der Gedanke nahe. Bei einer chemischen Reaktion wie dem Toasten geht aber kein Atom verloren; die Hitze liefert nur Energie, und die fehlende Masse steckt in den entwichenen Gasen."}],"familie":"bilanz-pruefen","fertigkeit":"F1"},{"id":"qx-c1-030","clusterId":"C","werkstueckRef":"C.2.2","stufe":2,"question":"Welche Schlussfolgerung ist die sparsamste?","options":["Die Atome sind in beiden Stoffen unterschiedlich angeordnet; diese Anordnung bestimmt die Eigenschaften, ein Widerspruch entsteht nicht.","Die Atome sind in beiden Stoffen gleich angeordnet; also muss einer der beiden Stoffe in Wahrheit eine andere Zusammensetzung haben.","Die Atome sind in beiden Stoffen gleich angeordnet; die Eigenschaften hängen allein von der Menge der Atome ab, Diamant ist hart, weil er mehr Atome enthält.","Die Atome sind in beiden Stoffen gleich angeordnet; der Unterschied lässt sich nicht erklären, im Diamanten wirkt eine besondere Eigenschaft, die sich chemisch nicht fassen lässt."],"correctIndex":0,"explanation":"Der scheinbare Widerspruch entsteht nur durch die versteckte Annahme, dass dieselben Atome immer dieselben Eigenschaften ergeben müssten. Doch Graphit und Diamant bestehen beide aus reinem Kohlenstoff, und weil die Atome unterschiedlich angeordnet sind, ist das eine ein weiches Schmiermittel und das andere eines der härtesten bekannten Materialien. Die Erklärung kommt ohne zusätzliche Annahmen aus. Die anderen Wege behaupten entweder eine andere Zusammensetzung ohne Beleg, verwechseln Anordnung mit Menge oder setzen eine unerklärbare Sonderkraft an, wo eine einfache Erklärung vorliegt.","coreRule":"⚡ Nicht nur woraus ein Stoff besteht, sondern wie die Atome angeordnet sind, entscheidet über seine Eigenschaften.","beleg":"Werkstück C.2.2 (Kontext & Tiefe, „Struktur bestimmt Funktion“)","status":"entwurf","scenario":"Eine Chemikerin sagt: „Graphit und Diamant bestehen beide aus reinem Kohlenstoff. Trotzdem ist der eine ein weiches Schmiermittel, der andere eines der härtesten bekannten Materialien.“ Ein Zuhörer meint, das sei ein Widerspruch.","kurz":"Der Widerspruch besteht nur, wenn dieselben Atome immer dieselben Eigenschaften ergeben müssten. Das tun sie nicht: Die Anordnung der Kohlenstoffatome unterscheidet sich, und das erklärt alles ohne zusätzliche Annahmen.","prueffrage":"Was ist über beide Stoffe gesichert, und wie viel muss man darüber hinaus annehmen, um ihren Unterschied zu erklären?","rueckmeldung":[{"option":1,"text":"Eine andere Zusammensetzung wäre ein bequemer Ausweg. Beide Stoffe bestehen aber aus reinem Kohlenstoff, für eine Abweichung gibt es keinen Beleg, und gleich angeordnet sind die Atome auch nicht."},{"option":2,"text":"Bei manchen Eigenschaften spielt die Menge eine Rolle, bei der Härte nicht: Ein kleiner Diamant ist so hart wie ein großer. Entscheidend ist die Anordnung der Atome, und die ist hier verschieden."},{"option":3,"text":"Der Unterschied wirkt so groß, dass eine geheimnisvolle Besonderheit des Diamanten plausibel erscheint. Die Atome sind aber gar nicht gleich angeordnet, und ihre verschiedene Anordnung erklärt den Unterschied, ohne etwas Unfassbares anzunehmen."}],"familie":"natuerlich-kein-guetesiegel","fertigkeit":"F2"},{"id":"qx-c1-031","clusterId":"C","werkstueckRef":"C.2.2","stufe":3,"question":"Welchen Denkfehler macht diese Person?","options":["Die Person vergleicht Herkunft statt Struktur: Glutamat kommt als Aminosäure in Tomaten und Parmesan natürlich vor, und identische Moleküle reagieren im Körper gleich.","Die Person vergleicht Mengen statt Stoffe: Tomaten und Parmesan enthalten zwar Glutamat, aber so wenig, dass der Körper es nie als Glutamat verarbeitet.","Die Person vergleicht Verarbeitungsgrade statt Stoffe: Glutamat aus dem Labor hat eine andere räumliche Struktur als Glutamat aus Lebensmitteln und wirkt deshalb anders.","Die Person vergleicht Geschmäcker statt Stoffe: Der Umami-Geschmack von Tomaten und Parmesan stammt von anderen Molekülen als der von MSG."],"correctIndex":0,"explanation":"„Natürlich“ und „synthetisch“ beschreiben die Herkunft eines Stoffes, nicht das Molekül selbst. Glutamat ist eine Aminosäure, die in reifen Tomaten und in Parmesan reichlich frei vorkommt und dort für den Umami-Geschmack sorgt. MSG ist das Natriumsalz der Glutaminsäure: Gelöst in Wasser oder Speichel liegt dasselbe Glutamat vor wie in der Tomate, dazu Natrium wie aus Kochsalz. Für die Wirkung im Körper zählt die Struktur, nicht die Herkunft, ähnlich wie bei Vitamin C aus der Orange und aus dem Labor. Wer das eine meidet und das andere genießt, urteilt nach dem Etikett statt nach dem Stoff.","coreRule":"⚡ „Natürlich“ oder „synthetisch“ sagt nichts über das Molekül – seine Struktur zählt.","beleg":"Werkstück C.2.2 (Werkbank-Frage; Anwendung & Relevanz, „Natürlich vs. Chemisch/Synthetisch“)","status":"entwurf","scenario":"Jemand sagt: „Ich vermeide Mononatriumglutamat (MSG) in meinem Essen, weil es unnatürlich und schädlich ist. Dafür esse ich gern Tomaten und Parmesan, denn die sind natürlich und gesund.“","quote":"","quoteLabel":"","kurz":"Entscheidend ist das Molekül, nicht seine Herkunft: Das Glutamat in Tomate und Parmesan ist dasselbe wie das in MSG und wirkt im Körper gleich. Wer nur nach Herkunft „natürlich“ oder „unnatürlich“ urteilt, folgt dem Etikett statt dem Stoff.","prueffrage":"Was steckt in einer reifen Tomate oder im Parmesan chemisch alles drin, und worauf geht ihr herzhafter Geschmack zurück?","rueckmeldung":[{"option":1,"text":"Mengen spielen bei Stoffen oft eine Rolle, hier aber nicht: Tomaten und Parmesan enthalten viel Glutamat, und der Körper verarbeitet es genauso wie das aus MSG, ohne nach der Quelle zu fragen."},{"option":2,"text":"Dass es auf die Struktur ankommt, stimmt. Nur ist sie hier identisch: Glutamat aus dem Labor und aus Lebensmitteln ist dasselbe Molekül, ein Unterschied in der räumlichen Struktur besteht nicht."},{"option":3,"text":"Der Umami-Geschmack geht in Tomaten und Parmesan gerade auf Glutamat zurück, also auf dasselbe Molekül wie in MSG. Der Geschmack liefert deshalb keinen Unterschied zwischen den Stoffen."}],"familie":"natuerlich-kein-guetesiegel","fertigkeit":"F2"},{"id":"qx-c1-032","clusterId":"C","werkstueckRef":"C.2.2","stufe":4,"question":"Ein Anbieter behauptet, nicht näher benannte „Toxine“ lagerten sich im Körper ab, sein Präparat „ziehe sie heraus“. Welche Gegenfrage prüft diese Behauptung am besten?","options":["Welche Stoffe genau gemeint sind und welche chemische Reaktion im Körper ablaufen soll, denn jede Wirkbehauptung braucht beides.","Ob das Präparat natürlichen Ursprungs ist, denn natürliche Stoffe reagieren im Körper anders als im Labor hergestellte.","Wie viel Energie das Präparat enthält, denn nur Energie kann die Stoffe aus dem Körper austreiben.","Ob Kunden von einer Besserung berichten, denn Erfahrungsberichte gelten als sicherer Beleg für die Wirkung des Präparats."],"correctIndex":0,"explanation":"Eine Wirkbehauptung ist erst prüfbar, wenn sie benennt, welche Stoffe beteiligt sind und welche Reaktion abläuft. „Toxine“ oder „Schlacken“ ohne Stoffbenennung lassen sich weder nachweisen noch widerlegen und sind ein Warnsignal. Der Körper wandelt außerdem selbst unzählige potenziell schädliche Stoffe um: Die Leber macht sie wasserlöslich, damit sie ausgeschieden werden können. Die Herkunft („natürlich“) sagt nichts über die Reaktion, denn ein Molekül mit gleicher Struktur reagiert gleich, egal woher es stammt. Und Zufriedenheitsberichte benennen weder Stoffe noch Reaktion und beantworten deshalb nicht die Frage nach dem Wirkmechanismus.","coreRule":"⚡ Frag nach den „Lego-Steinen“: Welche Stoffe, welche Reaktion?","beleg":"Werkstück C.2.2 (Aktivierungs-Frage; Anwendung & Relevanz, „Gegen die ‚Detox‘-Mythen“; Red Flags)","status":"entwurf","kurz":"Eine Wirkbehauptung lässt sich erst prüfen, wenn sie benennt, welche Stoffe beteiligt sind und welche Reaktion ablaufen soll. „Toxine“ ohne Namen kann man weder nachweisen noch widerlegen. Gerade das macht die Behauptung verdächtig.","prueffrage":"Lässt sich die Behauptung so, wie sie dasteht, überhaupt nachmessen, und woran würdest du das festmachen?","rueckmeldung":[{"option":1,"text":"Die Herkunft eines Stoffes sagt nichts darüber, wie er im Körper reagiert: Ein Molekül mit gleicher Struktur verhält sich gleich, egal woher es stammt. Außerdem bleibt offen, welche Stoffe gemeint sind und was passieren soll."},{"option":2,"text":"Der Energiegehalt hat mit dem Entfernen von Stoffen aus dem Körper nichts zu tun, und Energie allein treibt nichts heraus. Die Frage klärt weder, welche Stoffe gemeint sind, noch, welche Reaktion ablaufen soll."},{"option":3,"text":"Berichte über eine Besserung wirken überzeugend, weil sie konkret erlebt sind. Eine Besserung kann aber auch von Erwartung oder vom natürlichen Verlauf kommen, und die Berichte nennen weder Stoffe noch Reaktion."}],"familie":"mechanismus-verlangen","fertigkeit":"F1"},{"id":"qx-c1-033","clusterId":"C","werkstueckRef":"C.2.3","stufe":1,"question":"Ein Start-up wirbt für einen „Generator der Zukunft“: Er soll dauerhaft Strom liefern, ohne dass Brennstoff, Sonnenlicht oder Wind nötig sind, und dabei angeblich zu 100 % effizient arbeiten, also ohne jede Abwärme. Welche Einschätzung ist physikalisch korrekt?","options":["Das Versprechen „Strom ohne Energiequelle“ widerspricht der Energieerhaltung, und das Versprechen „keine Abwärme“ widerspricht dem Zweiten Hauptsatz, nach dem jede Umwandlung nutzbare Energie in Abwärme verliert.","Beide Versprechen widersprechen allein der Energieerhaltung, denn weil Energie nie verloren geht, ist auch ein Verlust durch Abwärme von vornherein ausgeschlossen.","Das Versprechen „Strom ohne Energiequelle“ widerspricht dem Zweiten Hauptsatz, das Versprechen „keine Abwärme“ widerspricht der Energieerhaltung, denn Abwärme entsteht, wenn Energie neu erzeugt wird.","Beide Versprechen widersprechen weder der Energieerhaltung noch dem Zweiten Hauptsatz, denn ein sehr gut gebauter Generator kann die Reibung so weit senken, dass wirklich kein Verlust mehr auftritt."],"correctIndex":0,"explanation":"Die beiden Versprechen sind zwei verschiedene Verstöße, wie bei einer Bank, die Geld aus dem Nichts auszahlt und jede Transaktion ohne Gebühren abwickelt. Strom ohne jede Energiequelle wäre Energie aus dem Nichts, und Energie kann weder erzeugt noch vernichtet werden (Erster Hauptsatz). Eine völlig verlustfreie Umwandlung gibt es ebenfalls nicht: Bei jedem realen Vorgang wird ein Teil der nutzbaren Energie zu Abwärme, die sich nicht vollständig zurück in Arbeit verwandeln lässt, die Entropie steigt (Zweiter Hauptsatz). Beide Aussagen sind nötig, denn die Energieerhaltung allein erklärt noch nicht, warum immer ein Teil als Abwärme „verloren“ geht. Ein seriöser Prüfschritt fragt deshalb: Woher kommt die Energie, und wohin geht die Abwärme?","coreRule":"⚡ Energie aus dem Nichts verbietet der Erste, verlustfreie Umwandlung der Zweite Hauptsatz.","beleg":"Werkstück C.2.3 (Die unmögliche Bank; Kontext & Tiefe)","status":"entwurf","scenario":"","kurz":"Strom ohne Quelle wäre Energie aus dem Nichts, das verbietet die Energieerhaltung. Verlustfreie Umwandlung scheitert an etwas anderem: Dass Energie erhalten bleibt, heißt nicht, dass sie nutzbar bleibt, denn bei jedem realen Vorgang wird ein Teil zu Abwärme (Zweiter Hauptsatz).","prueffrage":"Woher stammt in dieser Werbung die Energie, die als Strom herauskommt, und wo bliebe die Wärme, die jede Maschine abgibt?","rueckmeldung":[{"option":1,"text":"Dass Energie nie verloren geht, stimmt, und das widerlegt das erste Versprechen. Abwärme schließt es aber nicht aus: Sie ist erhaltene Energie, nur nicht mehr vollständig nutzbar. Warum immer ein Teil so endet, erklärt der Zweite Hauptsatz."},{"option":2,"text":"Hier sind die beiden Gesetze vertauscht: Energie aus dem Nichts verletzt die Energieerhaltung. Abwärme entsteht nicht aus neu erzeugter Energie, sondern aus vorhandener, die in eine kaum nutzbare Form übergeht; das beschreibt der Zweite Hauptsatz."},{"option":3,"text":"Bessere Bauweise senkt Reibungsverluste, das stimmt. Doch Reibung ist nur ein Verlustweg, ganz ohne Abwärme läuft kein realer Vorgang ab. Und gegen Strom ohne Quelle hilft keine Konstruktion, denn Energie lässt sich nicht erzeugen."}],"familie":"bilanz-pruefen","fertigkeit":"F1"},{"id":"qx-c1-034","clusterId":"C","werkstueckRef":"C.2.3","stufe":2,"question":"Eine Freundin sagt: „Wenn ich in meinem Kamin Holz verbrenne, erzeuge ich Wärme – das ist doch Energie, die aus dem Nichts entsteht.“ Welche Antwort trifft den Denkfehler am besten?","options":["Die Wärme entsteht tatsächlich neu, denn bei jeder Verbrennung wird mehr Energie frei, als vorher im Holz steckte.","Die Energie war schon im Holz gespeichert, denn der Baum hat per Photosynthese Sonnenlicht in chemische Energie umgewandelt.","Die Wärme stammt aus der Raumluft, denn die Luft kühlt beim Verbrennen ab und gibt ihre Energie an das Feuer weiter.","Die Wärme stammt aus der Erde, denn der Baum hat im Boden Erdwärme gespeichert, die beim Verbrennen wieder frei wird."],"correctIndex":1,"explanation":"Energie kann weder erzeugt noch vernichtet werden, sie wird nur umgewandelt. Auch das Feuer erschafft nichts neu, sondern setzt chemische Energie frei, die im Holz gespeichert war; die Pflanze hat sie per Photosynthese aus Sonnenlicht gewonnen. Mehr Energie, als vorher im Holz steckte, kann deshalb beim Verbrennen nicht frei werden. Die Raumluft scheidet als Quelle aus, denn sie müsste sich dabei abkühlen, tatsächlich wird der Raum aber wärmer; und Erdwärme erklärt den Energiegehalt von Holz nicht, weil Bäume vor allem aus Sonnenlicht, Luft und Wasser wachsen. Die Behauptung „Energie aus dem Nichts“ scheitert an der Frage, woher die Energie vorher kam.","coreRule":"⚡ Energie entsteht nie neu – frage immer: Woher kam sie vorher?","beleg":"Werkstück C.2.3 (Schmiede-Übung „Der persönliche Energie-Audit“; Kontext & Tiefe: Erster Hauptsatz)","status":"entwurf","scenario":"","kurz":"Das Feuer erschafft keine Energie, es setzt chemische Energie frei, die im Holz gespeichert war; die Pflanze hat sie per Photosynthese aus Sonnenlicht gewonnen. „Aus dem Nichts“ hält der Frage nach der Herkunft nicht stand.","prueffrage":"Was war mit dieser Energie, bevor das Holz im Kamin lag, und wo steckte sie dann?","rueckmeldung":[{"option":0,"text":"Beim Verbrennen wird tatsächlich Wärme frei, doch dabei entsteht keine Energie neu: Es kann nie mehr frei werden, als vorher im Holz gespeichert war. Wer „mehr als vorher“ annimmt, wiederholt nur die Behauptung der Freundin."},{"option":2,"text":"Die Frage nach der Energiequelle ist richtig gestellt, aber diese Quelle passt nicht zur Beobachtung. Würde die Raumluft ihre Energie ans Feuer abgeben, würde der Raum kälter. Er wird aber spürbar wärmer."},{"option":3,"text":"Hier wird sinnvoll nach einer gespeicherten Quelle gesucht, nur erklärt die genannte nicht die Energie im Holz. Ein Baum wächst vor allem aus Sonnenlicht, Luft und Wasser, nicht aus Wärme aus dem Boden."}],"familie":"bilanz-pruefen","fertigkeit":"F1"},{"id":"qx-c1-035","clusterId":"C","werkstueckRef":"C.2.3","stufe":3,"question":"Welche der folgenden Aussagen sollte dich am ehesten misstrauisch machen, weil hier ein Energie-Begriff als physikalische Tatsache verkauft wird und Menschen dadurch zu einer Entscheidung gedrängt werden?","options":["„Mein Gerät liefert dauerhaft mehr Strom, als es verbraucht, aus ‚Raumenergie‘ – investier jetzt in deine Unabhängigkeit.“","„Nach dem Urlaub bin ich voller positiver Energie, habe richtig Lust auf neue Projekte und freue mich darauf, mich zu verabreden.“","„Meine Kollegin hat eine Energie, die den ganzen Raum mitreißt, sobald sie ein Meeting beginnt, und bringt jede Diskussion in Gang.“","„In dieser Gruppe fühle ich mich energiegeladen; die Stimmung trägt uns auch dann, wenn die Arbeit sehr anstrengend ist.“"],"correctIndex":0,"explanation":"Drei der Aussagen benutzen „Energie“ als Bild für Stimmung, Lust oder Ausstrahlung. Niemand will daraus eine messbare physikalische Größe ableiten, und niemand muss dafür Geld oder Gesundheit riskieren. Anders die Aussage mit dem Gerät: Sie behauptet einen physikalischen Vorgang (mehr Strom heraus als hinein) und knüpft daran eine Geldforderung. Nach dem Ersten Hauptsatz kann Energie weder erzeugt noch vernichtet werden. Ein Gerät, das mehr abgibt, als es aufnimmt, wäre eine „Bank“, die Geld aus dem Nichts druckt. Der Zweite Hauptsatz kommt noch hinzu: Kein realer Vorgang läuft ohne Verlust ab, ein Teil der nutzbaren Energie wird immer zu Abwärme. Wer für eine solche Maschine Geld verlangt, verkauft eine Metapher oder ein Wort als Physik. Das Wort „Raumenergie“ ohne Maßeinheit und ohne benannte Quelle ist zusätzlich ein Warnsignal. Prüffrage: Woher kommt die Energie, in welcher Form fließt sie, und wohin geht die Abwärme?","coreRule":"⚡ Eine Metapher ist harmlos. Gefährlich wird sie, wenn jemand sie als Physik verkauft und daran eine Forderung knüpft.","beleg":"Werkstück C.2.3 (Der Kipppunkt; Red Flags)","status":"entwurf","kurz":"Wer ein Gerät verkauft, das mehr Strom liefern soll, als es verbraucht, behauptet einen physikalischen Vorgang und verlangt dafür Geld. Energie entsteht aber nicht aus dem Nichts. Wo „Energie“ nur ein Bild für Stimmung oder Ausstrahlung ist, wird nichts Messbares behauptet.","prueffrage":"Was müsste man messen, um jede dieser Aussagen zu überprüfen, und wer hätte einen Schaden, wenn sie falsch wäre?","rueckmeldung":[{"option":1,"text":"Hier steht „Energie“ für Lust und gute Stimmung nach dem Urlaub, also für ein Gefühl. Niemand soll daraus eine messbare Größe ableiten, und es wird auch nichts verkauft oder gefordert."},{"option":2,"text":"Eine Ausstrahlung, die andere mitreißt, kann beeindruckend wirken und überzeugend klingen. „Energie“ ist hier aber ein Bild für Wirkung auf andere, es wird kein physikalischer Vorgang behauptet und niemand zu etwas gedrängt."},{"option":3,"text":"Dass eine Gruppenstimmung durch anstrengende Arbeit tragen kann, ist gut vorstellbar. Mit „fühle ich mich energiegeladen“ beschreibt die Person ein Empfinden und stellt keine Tatsache über Physik auf."}],"familie":"begriff-messbar-machen","fertigkeit":"F1"},{"id":"qx-c1-036","clusterId":"C","werkstueckRef":"C.2.3","stufe":4,"question":"Ein Freund schwärmt von einer „Kristall-Klangschale“, die Wasser „energetisiere“ und ihm heilende Eigenschaften verleihe. Welche Reaktion bringt ihn am ehesten dazu, die Behauptung selbst zu prüfen, ohne dass das Gespräch zum Streit wird?","options":["Du fragst nach, welche Energieform gemeint ist und woher sie kommt.","Du erklärst ihm die Gesetze der Thermodynamik und stellst klar, dass die Schale nicht funktionieren kann.","Du sagst, „energetisiertes“ Wasser lasse sich nicht beweisen oder widerlegen, und wechselst das Thema.","Du behauptest, jeder Klang erzeuge nur Wärme, und eine Schale könne Wasser deshalb nicht verändern."],"correctIndex":0,"explanation":"Wer eine Wirkung behauptet, behauptet damit einen Energiefluss: Etwas Messbares muss von der Schale auf das Wasser übergehen. Offene, neugierige Fragen wie: Welche Energieform meinst du genau, Wärme oder Schall? Woher kommt mehr Energie, als ich beim Anschlagen hineingesteckt habe? lassen den Freund die Lücke in dieser Energie-Buchhaltung selbst bemerken. Eine Belehrung oder ein Verbot (es könne gar nicht funktionieren) lädt dagegen zur Verteidigung ein. Eine Behauptung ohne Energiebilanz unkommentiert stehen zu lassen, regt nicht zum Prüfen an. Und die Aussage, jeder Klang erzeuge nur Wärme und könne Wasser deshalb nicht verändern, ist überzogen und unbelegt: Sinnvoll ist stattdessen, die behauptete Energieform konkret zu benennen und ihre Messbarkeit zu klären.","coreRule":"⚡ Frag nach der Energie-Buchhaltung: Woher kommt die Energie, in welcher Form wird sie übertragen, wohin geht der Verlust? Der andere findet die Lücke am besten selbst.","beleg":"Werkstück C.2.3 (Werkbank-Frage; Aktivierungs-Frage)","status":"entwurf","scenario":"Du sitzt mit einem Freund beim Kaffee. Er erzählt begeistert, seine Klangschale „energetisiere“ Wasser. Er hat die Schale gekauft und will dich überzeugen.","kurz":"Wer fragt, welche Energieform gemeint ist und woher sie kommt, lässt den Freund die Lücke in seiner Behauptung selbst bemerken. Eine Belehrung oder ein Verbot („kann nicht funktionieren“) lädt dagegen zur Verteidigung ein.","prueffrage":"Was hat dein Freund in die Schale investiert, und wie dürfte er reagieren, wenn ihm jemand sagt, sie könne gar nicht wirken?","rueckmeldung":[{"option":1,"text":"Eine Energiebilanz ist das richtige Kriterium, um die Behauptung zu prüfen. Als Vortrag mit dem fertigen Urteil „kann nicht funktionieren“ lädt dieses Wissen den Freund aber zur Verteidigung ein, statt ihn selbst nachdenken zu lassen."},{"option":2,"text":"Ein Themenwechsel vermeidet zwar den Streit, aber auch das Prüfen. Die Behauptung ist durchaus prüfbar, sobald die behauptete Energieform benannt ist; unkommentiert stehen gelassen, regt sie niemanden zum Nachdenken an."},{"option":3,"text":"Skepsis ist berechtigt, und beim Anschlagen entsteht auch etwas Wärme. „Jeder Klang erzeugt nur Wärme“ ist aber überzogen und unbelegt; eine solche Gegenbehauptung lässt sich so leicht zurückweisen wie die Behauptung des Freundes."}],"familie":"bilanz-pruefen","fertigkeit":"F1"},{"id":"qx-c1-037","clusterId":"C","werkstueckRef":"C.3.1","stufe":1,"question":"Eine Mitschülerin behauptet: „Für den Bau eines Proteins muss die gesamte DNA aus dem Zellkern heraus zu den Ribosomen, denn dort steht ja die Bauanleitung.“ Welche Erwiderung passt am besten zum Weg vom Gen zum Protein?","options":["Falsch: Die DNA bleibt als Blaupause im Zellkern, nur der benötigte Gen-Abschnitt wird als RNA-Arbeitskopie abgeschrieben und zu den Ribosomen gebracht, wo daraus das Protein entsteht.","Falsch: Die DNA bleibt im Zellkern und wird dort in Aminosäuren übersetzt, die danach als fertige Kette zu den Ribosomen wandern und sich dort zum Protein falten.","Richtig: Die gesamte DNA wird als Kopie zu den Ribosomen geschickt, wo daraus in einem einzigen Schritt alle Proteine der Zelle entstehen.","Richtig: Die Ribosomen lesen zuerst die fertigen Aminosäuren ab, aus denen im Zellkern anschließend die passende RNA und zuletzt die DNA des Gens entsteht."],"correctIndex":0,"explanation":"Die DNA ist der robuste Informationsspeicher im Zellkern und dient als Master-Blaupause. Für ein bestimmtes Protein wird nur der passende Gen-Abschnitt in eine mobile Arbeitskopie (RNA) umgeschrieben; das nennt man Transkription. Diese Kopie verlässt den Zellkern, wird an den Ribosomen gelesen und in eine Kette von Aminosäuren übersetzt, die sich zum funktionierenden Protein faltet (Translation). Die Übersetzung in Aminosäuren findet also nicht im Zellkern statt, sondern an den Ribosomen. Der Ablauf ist eindeutig: Die DNA bleibt im Zellkern, nur eine RNA-Kopie des Gens verlässt ihn. Der Weg führt vom Gen über die RNA zur Aminosäurekette; die DNA entsteht nicht erst am Ende aus fertigen Aminosäuren. Die Behauptung der Mitschülerin verwechselt außerdem Gen und gesamtes Erbgut: Ein Gen ist nur ein Abschnitt der DNA mit der Anleitung für ein bestimmtes Protein oder eine funktionale RNA-Einheit.","coreRule":"⚡ DNA ist die Blaupause, RNA die Arbeitskopie, das Protein das fertige Bauteil: Die Information fließt vom Gen über die RNA zum Protein, nie wird dafür das Original verschickt.","beleg":"Werkstück C.3.1 (Kontext & Tiefe, „Vom Gen zum Protein“; Kernidee)","status":"entwurf","scenario":"Im Biologiekurs geht es darum, wie eine Zelle ein Protein herstellt. Du sollst eine Behauptung prüfen.","quote":"","quoteLabel":"","kurz":"Die DNA bleibt als Blaupause im Zellkern; nur der Abschnitt des benötigten Gens wird als RNA-Kopie abgeschrieben und zu den Ribosomen gebracht. Die Behauptung verwechselt ein einzelnes Gen mit dem gesamten Erbgut.","prueffrage":"Braucht die Zelle für ein einzelnes Protein wirklich die Anleitung für alle anderen Proteine mit?","rueckmeldung":[{"option":1,"text":"Dass die DNA im Zellkern bleibt, stimmt. Aminosäuren entstehen dort aber nicht aus ihr: Das Übersetzen in eine Aminosäurekette geschieht erst an den Ribosomen, und zwar anhand der RNA-Kopie."},{"option":2,"text":"Hier steckt derselbe Gedanke wie in der Behauptung: das ganze Erbgut als Vorlage. Kopiert wird aber nur der Abschnitt, den die Zelle gerade braucht, und jedes Protein hat seine eigene Anleitung statt eines einzigen Rundumschritts."},{"option":3,"text":"Das wäre der Weg rückwärts. Die Information fließt vom Gen über die RNA zur Aminosäurekette; die Ribosomen lesen die RNA, und die DNA entsteht nicht am Ende aus fertigen Aminosäuren."}],"familie":"mechanismus-verlangen","fertigkeit":"F1"},{"id":"qx-c1-038","clusterId":"C","werkstueckRef":"C.3.1","stufe":2,"question":"Im Netz kursiert: „Der Mensch hat 50 % seiner DNA mit der Banane gemeinsam.“ Ein Kommentar darunter lautet: „Das passt doch, denn bei Menschen und Schimpansen ist es ja auch nur etwa die Hälfte.“ Welche Antwort prüft beides sauber?","options":["Die Zahl ist ein Mythos: Viele Gene haben ein Gegenstück in der Banane, weil alles Leben gemeinsame Vorfahren hat. Die Sequenzen stimmen aber nicht zur Hälfte überein, und beim Schimpansen liegt die Übereinstimmung bei rund 99 %.","Die Zahl stimmt: Die DNA aller Lebewesen besteht aus denselben vier Basen, deshalb deckt sie sich bei Mensch und Banane zur Hälfte, und beim Schimpansen ist es ähnlich viel.","Die Zahl stimmt für einzelne Gene: Selbst bei Menschen und Schimpansen liegt die Übereinstimmung der Erbgut-Sequenzen nur bei etwa 50 %, bei der Banane also entsprechend ähnlich.","Die Zahl ist ein Mythos: Pflanzen und Tiere besitzen kein gemeinsames Erbgut und sind nicht verwandt, deshalb hat jedes Lebewesen einen eigenen Code, und beim Schimpansen gilt das ebenso."],"correctIndex":0,"explanation":"Die „50 % Banane“ vermischen zwei verschiedene Dinge: Dass viele unserer Gene ein Gegenstück in der Banane haben, ist plausibel, weil alles Leben gemeinsame Vorfahren hat. Daraus folgt aber nicht, dass die DNA-Sequenz zur Hälfte übereinstimmt. Wo sich das Erbgut von Mensch und Schimpanse vergleichen lässt, stimmt es zu rund 99 % überein (Chimpanzee Sequencing and Analysis Consortium 2005, Nature 437): etwa 1,2 % Unterschied bei einzelnen Basen, einige Prozent, wenn Einfügungen und Verluste mitzählen. Wer die Banane mit „50 %“ vergleicht und den Schimpansen mit „nur etwa der Hälfte“ gleichsetzt, wirft Genverwandtschaft und Sequenzübereinstimmung durcheinander. Die Kommentar-Aussage zum Schimpansen ist zudem leicht überprüfbar falsch.","coreRule":"⚡ Gemeinsame Gene heißen nicht gleiche Sequenzen: Verwandtschaft ist etwas anderes als Prozentzahlen aus dem Netz. Prüfe, was genau verglichen wurde, bevor du eine Zahl glaubst.","beleg":"Werkstück C.3.1 (Schmiede-Übung „Der Code-Vergleich“); Fn. gl-c-schimpanse (Chimpanzee Sequencing and Analysis Consortium 2005, Nature 437, S. 69–87)","status":"entwurf","kurz":"Viele Gene haben ein Gegenstück in der Banane, weil alles Leben gemeinsame Vorfahren hat. Daraus folgt nicht, dass die Sequenzen zur Hälfte übereinstimmen; beim Schimpansen sind es sogar rund 99 %. Verwandte Gene und gleiche Sequenz sind zweierlei.","prueffrage":"Was genau wird bei der Zahl „50 %“ verglichen, und welcher Wert ist für Mensch und Schimpanse tatsächlich gemessen worden?","rueckmeldung":[{"option":1,"text":"Dass alle Lebewesen dieselben vier Basen nutzen, stimmt, sagt aber nichts über die Reihenfolge der Basen. Genau auf die Reihenfolge kommt es an, und bei Mensch und Schimpanse stimmt sie zu rund 99 % überein, nicht nur zur Hälfte."},{"option":2,"text":"Dass viele Gene in der Banane ein Gegenstück haben, trifft zu, aber das ist keine 50-%-Übereinstimmung der Sequenzen. Beim Schimpansen ist der Wert mit rund 99 % auch deutlich höher, als hier behauptet wird."},{"option":3,"text":"Dass die 50 % nicht stimmen, ist richtig, die Begründung aber nicht. Pflanzen und Tiere haben gemeinsame Vorfahren und teilen viele Gene, und gerade deshalb lässt sich ihr Erbgut überhaupt vergleichen."}],"familie":"zahl-zur-quelle","fertigkeit":"F1"},{"id":"qx-c1-039","clusterId":"C","werkstueckRef":"C.3.1","stufe":3,"question":"Ein Coach verspricht: „Mit positiven Gedanken reprogrammierst du deine DNA – das beweist die Epigenetik.“ Welche Einordnung hält der Prüfung stand?","options":["Gedanken können einzelne Basen der DNA austauschen, wenn man sie regelmäßig und mit Überzeugung übt; die Epigenetik zeigt das.","Die DNA reagiert schon auf Stimmungen, weil sie ein empfindliches Molekül ist; die Epigenetik belegt damit die Wirkung des Geistes auf die Gene.","Die Aktivität von Genen lässt sich überhaupt nicht beeinflussen; daher ist die Epigenetik Unsinn und gehört in dieselbe Kategorie wie die Aussage des Coachs.","Die Aktivität von Genen lässt sich beeinflussen, die Buchstabenfolge der DNA aber nicht durch bloße Absicht; die Epigenetik wird hier als „Beweis“ missbraucht."],"correctIndex":3,"explanation":"Der Satz des Coachs vermischt zwei verschiedene Dinge. Die Aktivität von Genen kann beeinflusst werden, das ist das Feld der Epigenetik. Die DNA dagegen ist ein bemerkenswert stabiles Molekül, und ihre Buchstabenfolge lässt sich nicht durch bloße Absicht verändern. Wer „DNA umprogrammieren“ verspricht, muss einen konkreten, experimentell belegten Mechanismus nennen, der die Sequenz verändert; ein Wort wie „Epigenetik“ ersetzt diesen Beleg nicht. Auch die Gegenposition ist ein Fehler: Aus dem Missbrauch eines Begriffs folgt nicht, dass das dahinterstehende Phänomen nicht existiert.","coreRule":"⚡ Gene lassen sich steuern, die Buchstabenfolge nicht – wer „DNA umschreiben“ verspricht, braucht einen Mechanismus.","beleg":"Werkstück C.3.1 (Anwendung & Relevanz, „In der Pseudomedizin“; Verbindungen; Aktivierungs-Frage)","status":"entwurf","scenario":"","kurz":"Genaktivität lässt sich beeinflussen, die Buchstabenfolge der DNA aber nicht durch bloße Absicht. Wer das Fachwort „Epigenetik“ schon für einen Beweis hält, übersieht, dass ein belegter Mechanismus fehlt, der die Sequenz verändert.","prueffrage":"Welcher konkrete, experimentell belegte Vorgang soll hier laut Coach etwas Bestimmtes in der Zelle verändern?","rueckmeldung":[{"option":0,"text":"Regelmäßiges Üben mit Überzeugung ist noch kein Mechanismus. Die Buchstabenfolge der DNA ist sehr stabil und ändert sich nicht durch bloße Absicht; die Epigenetik betrifft die Aktivität von Genen, nicht die Basenfolge."},{"option":1,"text":"Dass Psyche und Körper zusammenhängen, macht diese Deutung plausibel. DNA ist aber kein empfindliches, stimmungsabhängiges Molekül, sondern bemerkenswert stabil. Die Epigenetik belegt keine Umprogrammierung der DNA durch Gedanken."},{"option":2,"text":"Dass der Coach den Begriff missbraucht, stimmt. Daraus folgt aber nicht, dass das Phänomen dahinter nicht existiert: Die Aktivität von Genen lässt sich beeinflussen, und genau das untersucht die Epigenetik."}],"familie":"mechanismus-verlangen","fertigkeit":"F1"},{"id":"qx-c1-040","clusterId":"C","werkstueckRef":"C.3.1","stufe":4,"question":"Jemand sagt: „Gentechnisch veränderter Mais ist pures Gift, weil er ‚unnatürliche Gene‘ enthält.“ Welche Antwort widerlegt das Argument am besten?","options":["Gentechnik verändert nur einzelne Gene und kann deshalb keine unerwarteten Wirkungen haben, also ist sie immer sicherer als Züchtung.","Natürlich entstandene Gene sind per se unbedenklich, künstlich eingefügte dagegen grundsätzlich riskanter, die Aussage stimmt also teilweise.","Auch Züchtung verändert seit Jahrtausenden das Erbgut, nur zufällig und unpräzise; ob eine Pflanze sicher ist, zeigt ihr Ergebnis, nicht die Herkunft der Veränderung.","Das Argument trifft nur zu, wenn „unnatürlich“ mit „chemisch“ gleichgesetzt wird, und Gene sind ohnehin Chemikalien, also ist die Aussage widerlegt."],"correctIndex":2,"explanation":"Das Argument setzt „unnatürlich“ mit „giftig“ gleich, doch Herkunft oder Methode allein sagen nichts über Giftigkeit. Auch klassische Züchtung verändert seit etwa 10.000 Jahren das Erbgut, nur langsamer, zufälliger und unpräziser; Gentechnik wie CRISPR kann dagegen gezielt einzelne Gene verändern. Entscheidend für die Sicherheit ist das neue Merkmal der Pflanze, etwa ob sie ein Gift oder Allergen bildet, und genau das lässt sich prüfen. Die Antwort „Gentechnik ist immer sicherer“ macht denselben Fehler mit umgekehrtem Vorzeichen, die Antwort „natürlich ist unbedenklich, künstlich riskanter“ wiederholt das Etikett des Arguments nur abgeschwächt; beide urteilen nach der Methode statt nach dem Ergebnis. Der Hinweis, Gene seien Chemikalien, stimmt zwar, trifft aber nicht den Kern: Ob die Pflanze schadet, zeigt erst die Prüfung des Ergebnisses.","coreRule":"⚡ Bewerte das Ergebnis, nicht die Methode: „Natürlich“ ist kein Sicherheitsurteil.","beleg":"Werkstück C.3.1 (Anwendung & Relevanz, „Bei genetisch veränderten Organismen“; Werkbank-Frage; Red Flags)","status":"entwurf","kurz":"Giftig ist ein Merkmal des Ergebnisses, nicht seiner Herkunft: Auch Züchtung verändert seit Jahrtausenden das Erbgut, nur zufälliger. Der Fehler ist, „unnatürlich“ mit „giftig“ gleichzusetzen, statt das neue Merkmal der Pflanze zu prüfen.","prueffrage":"Wie sah die Wildpflanze aus, von der unser heutiger Mais abstammt, und wie wurde daraus die Pflanze auf dem Feld?","rueckmeldung":[{"option":0,"text":"Gentechnik kann einzelne Gene tatsächlich gezielter verändern als Züchtung. „Keine unerwarteten Wirkungen“ und „immer sicherer“ gehen aber zu weit: Auch hier entscheidet das fertige Merkmal, nicht die Methode."},{"option":1,"text":"Dass Natürliches harmlos sei, wirkt einleuchtend, trifft aber nicht zu: Auch natürlich entstandene Stoffe können giftig sein. So wird das Argument nicht widerlegt, sondern mit demselben Etikett in abgeschwächter Form wiederholt."},{"option":3,"text":"Gene sind tatsächlich chemische Stoffe, das stimmt. Doch daraus folgt nicht, dass die Aussage widerlegt ist: Offen bleibt, ob das Merkmal der Pflanze schadet, und das zeigt allein die Prüfung des Ergebnisses."}],"familie":"natuerlich-kein-guetesiegel","fertigkeit":"F2"},{"id":"qx-c1-041","clusterId":"C","werkstueckRef":"C.3.3","stufe":1,"question":"In einer Diskussion sagt jemand: „Wenn der Mensch vom Affen abstammt, warum gibt es dann noch Affen? Also kann die Abstammung nicht stimmen.“ Was ist an diesem Schluss fehlerhaft?","options":["Er setzt voraus, dass eine Art nach der Entstehung einer neuen Art verschwinden muss; zwei Linien können aber aus einem gemeinsamen Vorfahren hervorgehen und nebeneinander weiterbestehen.","Er setzt voraus, dass heutige Affen unsere direkten Vorfahren sind; diese Affen haben sich aber nicht weiterentwickelt, weil sie dazu keinen Anlass hatten.","Er setzt voraus, dass sich einzelne Affen für den Weg zum Menschen entschieden haben; die übrigen Affen sind dagegen bewusst auf ihrer Stufe geblieben.","Er setzt voraus, dass Evolution stets nur eine Art auf einmal verändert; sie ersetzt aber jedes Mal die gesamte Vorgängerart durch eine neue."],"correctIndex":0,"explanation":"Der Schluss setzt stillschweigend voraus, dass eine Stammart verschwinden muss, sobald sich aus ihr eine andere Art entwickelt hat. Das ist nicht der Fall: Zwei Linien können sich von einem gemeinsamen Vorfahren aus getrennt weiterentwickeln, so wie du und dein Cousin einen gemeinsamen Großvater habt. Dass dein Cousin noch lebt, widerlegt die Verwandtschaft nicht, und dass es heute noch Affen gibt, widerlegt die gemeinsame Abstammung ebenso wenig. Die Gegenaussagen haben jeweils einen eigenen Denkfehler: Wer heutige Affen für unsere direkten Vorfahren hält, verwechselt Vorfahren mit entfernten Verwandten, die den Vorfahren mit uns teilen. Wer sich einzelne Affen für den Weg zum Menschen entscheiden lässt, unterstellt Absicht, doch Evolution ist ziellos und hat keinen Plan. Und wer annimmt, dass jede neue Art ihre gesamte Vorgängerart ersetzt, übersieht, dass sich Linien nebeneinander entwickeln können, ohne dass die eine die andere verdrängen muss.","coreRule":"⚡ Wir stammen nicht von heutigen Affen ab, sondern teilen mit ihnen gemeinsame Vorfahren.","beleg":"Werkstück C.3.3 (Red Flags)","status":"entwurf","scenario":"","kurz":"Aus der Abstammung folgt nicht, dass die Stammart verschwindet: Zwei Linien können sich aus einem gemeinsamen Vorfahren getrennt weiterentwickeln und nebeneinander bestehen, so wie du und dein Cousin von einem Großvater abstammt.","prueffrage":"Leben heute verwandte Affenarten wie Schimpanse und Bonobo nebeneinander, und musste dafür eine die andere ablösen?","rueckmeldung":[{"option":1,"text":"Dass heutige Affen unsere direkten Vorfahren seien, ist ein verbreitetes Missverständnis. Falsch ist aber auch der Rest: Heutige Affen haben sich ebenso lange weiterentwickelt wie wir, und Evolution braucht keinen „Anlass“."},{"option":2,"text":"Das Bild von Affen, die weitergehen, und anderen, die zurückbleiben, ist anschaulich, setzt aber Absicht voraus. Evolution ist ziellos und hat keinen Plan, niemand entscheidet sich für einen Weg oder bleibt bewusst auf einer Stufe stehen."},{"option":3,"text":"Hier steckt gerade der Denkfehler des Schlusses als Tatsachenbehauptung: Neue Arten müssen die Vorgängerart nicht ersetzen. Linien können sich nebeneinander weiterentwickeln, ohne dass die eine die andere verdrängt."}],"familie":"auslese-statt-plan","fertigkeit":"F1"},{"id":"qx-c1-042","clusterId":"C","werkstueckRef":"C.3.3","stufe":2,"question":"Welche Erklärung trägt die Beobachtung am besten, dass nach massenhaftem Antibiotika-Einsatz fast nur noch resistente Keime übrig sind?","options":["Das Mittel tötet die empfindlichen Bakterien, die wenigen zufällig resistenten überleben und vermehren sich: Der Einsatz wirkt wie ein Filter.","Die Bakterien reagieren auf die Behandlung, indem sie gezielt Resistenz entwickeln und ihr Erbgut an das Medikament anpassen: Der Einsatz wirkt wie ein Lehrer.","Das Mittel verändert die Bakterien-DNA gezielt so, dass die Erreger widerstandsfähiger werden und das weitergeben: Der Einsatz wirkt wie eine Mutation.","Resistente Bakterien gab es nie, sie entstehen erst durch die Menge des eingesetzten Mittels, die Dosis löst die Resistenz aus: Der Einsatz wirkt wie ein Auslöser."],"correctIndex":0,"explanation":"Die Beobachtung lässt sich ohne Absicht und ohne „Lernen“ der Bakterien erklären: Zufällige Veränderungen im Erbgut entstehen ungerichtet, etwa durch Kopierfehler. Wo viel Antibiotikum eingesetzt wird, sterben die empfindlichen Keime, die wenigen zufällig resistenten überleben und vermehren sich, bis sie die Mehrheit stellen. Der Einsatz erzeugt also einen hohen Selektionsdruck, er verändert die Bakterien nicht gezielt. Die Variation ist zufällig, die Auswahl ist es nicht. Dieselbe Logik erklärt, warum schnell evolvierende Grippeviren jedes Jahr einen neuen Impfstoff nötig machen. Eine Erklärung, die den Bakterien Absicht oder Anpassungswillen zuschreibt, verwechselt das Ergebnis eines Filters mit einer Leistung der Gefilterten.","coreRule":"⚡ Resistenz wird nicht „gelernt“, sondern ausgelesen: Das Mittel selektiert, was zufällig schon resistent war.","beleg":"Werkstück C.3.3 (Anwendung & Relevanz, „Gegen Missverständnisse in der Medizin“; Kipppunkt)","status":"entwurf","scenario":"In einer Klinik wird beobachtet: Nach Jahren intensiven Antibiotika-Einsatzes sind die meisten Keime auf der Station gegen das Mittel resistent. Ein Kollege sagt: „Die Bakterien haben sich eben an das Medikament gewöhnt und angepasst.“ Du sollst beurteilen, welche Erklärung die Beobachtung am besten trägt.","kernregel":"⚡ Resistenz wird nicht „gelernt“, sondern ausgelesen: Das Mittel selektiert die zufällig resistenten Bakterien.","kurz":"Das Mittel tötet die empfindlichen Keime, die wenigen zufällig resistenten überleben und vermehren sich. Der Denkfehler ist, dem Ergebnis dieser Auslese eine Leistung der Bakterien zuzuschreiben, als hätten sie sich gezielt angepasst.","prueffrage":"Gab es in der Bakterienmenge schon vor der Behandlung Unterschiede, und wie ließe sich das nachprüfen?","rueckmeldung":[{"option":1,"text":"„Angepasst“ klingt nach einer Reaktion der Bakterien, und im Ergebnis stimmt es sogar. Die Erbgutveränderungen entstehen aber ungerichtet; die Mehrheit ist resistent, weil die empfindlichen Keime aussortiert wurden."},{"option":2,"text":"Manche Stoffe können Erbgut tatsächlich verändern, aber nicht gezielt zum Vorteil der Bakterien. Resistente Varianten entstehen zufällig, etwa durch Kopierfehler; das Antibiotikum sortiert nur aus und erzeugt so Selektionsdruck."},{"option":3,"text":"Ein Mittel, das Resistenz erst auslöst, würde ihre Häufigkeit erklären. Resistente Varianten entstehen aber zufällig und sind oft schon vorher da, wenn auch selten; das Mittel macht sie zur Mehrheit, indem es die empfindlichen Keime beseitigt."}],"familie":"auslese-statt-plan","fertigkeit":"F1"},{"id":"qx-c1-043","clusterId":"C","werkstueckRef":"C.3.3","stufe":3,"question":"Ein Ernährungs-Influencer sagt: „Wir sind biologisch an die Steinzeit angepasst – iss deshalb wie unsere Vorfahren.“ Welcher Einwand trifft die Behauptung am besten?","options":["Die Behauptung stimmt: Zehntausend Jahre sind biologisch so kurz, dass sich beim Menschen seitdem nichts Wesentliches verändert haben kann.","Die Behauptung stimmt, nur die Milchverdauung ist eine Ausnahme: Sie geht auf eine einzelne Mutation zurück und breitete sich rein zufällig aus.","Die Behauptung ist falsch, weil wir heute perfekt angepasst sind: Evolution arbeitet immer auf den bestmöglichen Zustand hin.","Die Behauptung ist falsch, weil Evolution weiterging: Wo Menschen Milch nutzten, breitete sich die Milchzuckerverdauung im Erwachsenenalter aus."],"correctIndex":3,"explanation":"Die Behauptung unterstellt, die Anpassung sei vor langer Zeit abgeschlossen worden und es gebe einen „natürlichen“ Idealzustand. Das ist doppelt falsch. Erstens hat die Evolution nicht aufgehört: In Populationen, deren Vorfahren Milch nutzten, hat sich die Fähigkeit ausgebreitet, auch als Erwachsene Milchzucker zu verdauen. Das ist eines der am stärksten selektierten Merkmale der letzten 10.000 Jahre. Die Selektion hängt mit dem Milchkonsum zusammen, dessen Stärke allein erklärt die Ausbreitung aber nicht; als zusätzliche Treiber werden Hungersnöte und Krankheiten vermutet. Zweitens ist Evolution nicht auf Perfektion ausgelegt, sondern auf „gut genug“ in der jeweiligen Umgebung. Es gibt deshalb nicht „den einen“ Zustand, an den wir perfekt angepasst sind, weder den steinzeitlichen noch den heutigen. Und die Selektion wirkt nicht zufällig: Die Variation ist zufällig, die Auswahl durch die Umwelt ist es nicht.","coreRule":"⚡ Evolution ist nie fertig, und einen „natürlichen“ Idealzustand, an den wir perfekt angepasst wären, gibt es nicht.","beleg":"Werkstück C.3.3 (Anwendung & Relevanz, „Gegen den Appell an die Natur in seiner ‚Paläo‘-Form“); Fn. gl-c-laktase (Evershed u. a. 2022, Nature 608, S. 336–345)","status":"entwurf","kurz":"Die menschliche Evolution endete nicht in der Steinzeit: Wo Menschen Milch nutzten, breitete sich die Milchzuckerverdauung im Erwachsenenalter aus. Der Denkfehler ist die Annahme, die Anpassung sei längst abgeschlossen und es gebe einen „natürlichen“ Idealzustand.","prueffrage":"Gibt es Merkmale, die sich bei Menschen erst in den letzten Jahrtausenden verbreitet haben, und woran würdest du das erkennen?","rueckmeldung":[{"option":0,"text":"Zehntausend Jahre wirken im Vergleich zur Erdgeschichte winzig. Doch starke Selektion kann schon in wenigen hundert Generationen etwas verändern, wie die Ausbreitung der Milchzuckerverdauung bei Erwachsenen zeigt."},{"option":1,"text":"Die Ausbreitung der Milchverdauung war kein Zufall: Mehrere Erbgutvarianten entstanden unabhängig und zufällig, durchgesetzt haben sie sich, wo Menschen Milch nutzten. Sie ist keine Ausnahme, sondern ein Beleg, dass Evolution weiterging."},{"option":2,"text":"Dass die Behauptung falsch ist, stimmt, doch diese Begründung verlegt ihren Fehler nur in die Gegenwart: Evolution steuert keinen bestmöglichen Zustand an, die Auslese begünstigt, was in der jeweiligen Umgebung gut genug ist."}],"familie":"auslese-statt-plan","fertigkeit":"F1"},{"id":"qx-c1-044","clusterId":"C","werkstueckRef":"C.3.3","stufe":4,"question":"Wie ist dieses Argument zu bewerten?","options":["Es ist stichhaltig: Bei so hoher Komplexität können Mutation und Selektion grundsätzlich nichts mehr erklären.","Es schließt von „ich kann mir keinen schrittweisen Weg vorstellen“ auf „es gab keinen“; komplexe Strukturen können schrittweise entstanden sein.","Es ist erst widerlegt, wenn jeder einzelne Zwischenschritt des Organs im Fossilbericht lückenlos belegt ist.","Es zeigt zu Recht, dass Zufall allein so etwas nicht hervorbringt; deshalb braucht es einen Plan."],"correctIndex":1,"explanation":"Das Argument schließt von der eigenen Ratlosigkeit auf die Wirklichkeit: Weil sich der Redner keinen schrittweisen Weg vorstellen kann, soll es keinen gegeben haben. Das ist ein Fehlschluss aus persönlichem Unglauben. Dass ein Organ heute ohne ein Teil nicht mehr funktioniert, sagt nichts über seine Entstehung: Komplexe Strukturen konnten schrittweise entstehen. Proto-Flügel dienten etwa vielleicht erst der Isolierung oder Balz, bevor sie beim Gleiten nützlich wurden. Außerdem ist Evolution kein reiner Zufallsprozess, sondern die nicht-zufällige Auswahl zufälliger Variationen. Auch muss nicht jeder Zwischenschritt lückenlos fossil belegt sein: Der Fossilienbestand ist naturgemäß lückenhaft.","coreRule":"⚡ „Das kann ich mir nicht vorstellen“ ist kein Argument gegen eine Erklärung, sondern eine Aussage über die eigene Vorstellungskraft.","beleg":"Werkstück C.3.3 (Anwendung & Relevanz, „Gegen Kreationismus & ‚Intelligent Design‘“; Red Flags)","status":"entwurf","scenario":"Ein Redner behauptet: „Dieses Organ ist ‚irreduzibel komplex‘: Nimmt man ein einziges Teil weg, funktioniert es nicht mehr. Also muss ein Designer es geschaffen haben.“","kurz":"Aus „ich kann mir keinen schrittweisen Weg vorstellen“ folgt nicht, dass es keinen gab. Dass heute kein Teil fehlen darf, sagt nichts über die Entstehung: Teile konnten früher andere Aufgaben erfüllen.","prueffrage":"Was wurde an dem Organ tatsächlich beobachtet, und was davon sagt etwas über seine Entstehung?","rueckmeldung":[{"option":0,"text":"Hohe Komplexität wirkt, als überfordere sie jeden schrittweisen Prozess. Doch Selektion wählt nicht-zufällig aus, und Teile können früher anderen Zwecken gedient haben. Aus fehlender Vorstellung folgt kein „grundsätzlich unmöglich“."},{"option":2,"text":"Lückenlose Belege wären schön, sind aber keine Bedingung: Der Fossilienbestand ist naturgemäß lückenhaft. Entscheidend ist, dass das Argument selbst nicht trägt, weil es aus Unvorstellbarkeit auf Unmöglichkeit schließt."},{"option":3,"text":"Reiner Zufall würde komplexe Strukturen tatsächlich nicht hervorbringen. Evolution ist aber kein reiner Zufallsprozess, sondern die nicht-zufällige Auswahl zufälliger Variationen. Daraus, dass „Zufall allein“ nicht reicht, folgt daher noch kein Plan."}],"familie":"vorstellung-ist-kein-massstab","fertigkeit":"F2"},{"id":"qx-c1-045","clusterId":"C","werkstueckRef":"C.3.4","stufe":1,"question":"Eine Bekannte erzählt begeistert: „Im Wald hinter dem Dorf lebt ein einzelnes, riesiges Tier, das noch nie jemand eingefangen hat. Es ist vermutlich schon seit Jahrhunderten dort.“ Welcher Einwand trifft den Kern des Problems am besten?","options":["Über Jahrhunderte hält sich in der Regel nur eine Population, kein Einzeltier, und kleine Gruppen sterben durch Inzucht, Krankheiten oder eine Katastrophe leicht aus.","Ein so großes Tier müsste längst gesehen worden sein, denn Wälder sind dicht besiedelt und gut erforscht, und es würde schnell auffallen.","Ein einzelnes Tier verbraucht zu viel Nahrung, denn der Wald würde es nicht dauerhaft versorgen und es wäre längst abgewandert.","Ein einzelnes Tier hat nicht genug Erbgut, denn seine Eigenschaften könnten sich nicht weiterentwickeln und es bliebe unverändert."],"correctIndex":0,"explanation":"Die Behauptung verwechselt ein einzelnes Tier mit einer Art. Damit etwas über Jahrhunderte besteht, braucht es eine Population, die sich fortpflanzt. Sehr kleine Gruppen sind stark gefährdet: Inzucht und Gendefekte schwächen den Nachwuchs, Krankheiten und zufällige Ereignisse wie ein Waldbrand können alle auf einmal treffen. Für große Säugetiere schätzen Wissenschaftler die minimal überlebensfähige Population auf mehrere hundert bis einige tausend Individuen, die miteinander in Kontakt stehen (Frankham, Bradshaw und Brook 2014; Jamieson und Allendorf 2012). Die genauen Zahlen schwanken je nach Studie, die Größenordnung bleibt aber gleich: weit mehr als ein Pärchen. Wer von „einem Tier“ spricht, muss also die ganze Population mitdenken, samt Nahrungsbedarf, Spuren und Kadavern.","coreRule":"⚡ Wer von „einem Monster“ spricht, muss von einer ganzen Population sprechen.","beleg":"Werkstück C.3.4 (Kontext & Tiefe, „Die minimal überlebensfähige Population“); Fn. gl-c-mvp (Frankham/Bradshaw/Brook 2014, S. 61; Jamieson/Allendorf 2012, S. 582 f.)","status":"entwurf","scenario":"","kurz":"Über Jahrhunderte besteht nur eine fortpflanzungsfähige Population, kein einzelnes Tier. Kleine Gruppen sind durch Inzucht, Krankheiten und Zufallsereignisse stark gefährdet; die Behauptung verwechselt Einzeltier und Art.","prueffrage":"Wie alt werden große Waldtiere wie Bären oder Elche höchstens, und wie oft passt das in einige Jahrhunderte?","rueckmeldung":[{"option":1,"text":"Ein großes Tier hinterlässt tatsächlich Spuren, doch längst nicht jeder Wald ist dicht besiedelt und gut erforscht. Vor allem greift das Argument die Sichtung an, nicht den Gedanken, ein Einzeltier könne Jahrhunderte überdauern."},{"option":2,"text":"Der Nahrungsbedarf spielt eine Rolle, spricht aber eher für als gegen ein einzelnes Tier: Eines braucht weniger als eine ganze Gruppe. Den Kern trifft das nicht, denn es fehlt der Gedanke an Fortpflanzung und Population."},{"option":3,"text":"Geringe genetische Vielfalt ist bei kleinen Gruppen tatsächlich ein Problem. Um zu bestehen, muss sich ein Tier aber nicht weiterentwickeln: Über Jahrhunderte hält sich nur eine Population, die sich fortpflanzt, und kleine Gruppen sterben leicht aus."}],"familie":"population-und-spuren","fertigkeit":"F1"},{"id":"qx-c1-046","clusterId":"C","werkstueckRef":"C.3.4","stufe":2,"question":"Ein Bigfoot-Anhänger sagt: „Die Tiere sind eben scheu und hinterlassen keine Spuren.“ Welche Überlegung stellt diesen Einwand am stärksten infrage?","options":["Eine Population von einigen Tausend großen Primaten bräuchte täglich Tonnen Nahrung und ließe Tausende Spuren, Kothaufen, Nester und im Lauf der Zeit auch Kadaver zurück.","Scheue Tiere dieser Größe brauchen so wenig Nahrung, dass Vegetation und Beutetiere keine messbaren Veränderungen zeigen würden.","Fehlende Belege beweisen nichts, solange niemand bewiesen hat, dass es die Tiere nicht gibt, denn Abwesenheit von Belegen ist kein Gegenbeleg.","Spuren und Kothaufen sind schwer zu finden, deshalb wäre es unfair, von scheuen Tieren überhaupt physische Belege zu erwarten."],"correctIndex":0,"explanation":"Scheu mag erklären, warum man ein einzelnes Tier selten sieht, aber nicht, warum eine ganze Population keine Spuren hinterlässt. Damit sich eine große Tierart über Generationen hält, braucht sie meist mehrere hundert bis einige tausend Tiere; die bräuchten täglich Tonnen an Nahrung und hinterließen Fußspuren, Kothaufen mit DNA, Schlafnester und irgendwann Knochen und Kadaver. Bestätigt wurde bis heute weder ein Körper noch ein Knochen eines solchen Wesens, und genetisch untersuchte Haarproben stammten von bekannten Tieren wie Bären, Pferden oder Menschen. Wer annimmt, scheue Tiere bräuchten kaum Nahrung, übersieht den Bedarf großer Tiere, und wer sagt, Spuren seien schwer zu finden, erklärt nicht, warum Tausende davon nie bestätigt wurden. Der Hinweis, fehlende Belege bewiesen nichts, verlagert die Beweislast: Wo eine Population zwangsläufig Spuren hinterlassen müsste, spricht deren Fehlen durchaus gegen sie.","coreRule":"⚡ Scheu erklärt, warum Einzeltiere selten auffallen, nicht das Fehlen von Kot, Spuren und Knochen einer ganzen Population.","beleg":"Werkstück C.3.4 (Kontext & Tiefe, „Der ökologische Fußabdruck“); Fn. gl-c-sykes (Sykes u. a. 2014, Proc. R. Soc. B 281, 20140161; Lan u. a. 2017)","status":"entwurf","scenario":"","kurz":"Scheu erklärt allenfalls, warum man ein einzelnes Tier selten sieht. Eine Population, die über Generationen besteht, bräuchte aber täglich Tonnen Nahrung und hinterließe zwangsläufig Spuren, Kot und Kadaver, die man bisher nie bestätigt hat.","prueffrage":"Was hinterlassen scheue Waldtiere wie Bären oder Luchse, obwohl man sie selbst kaum zu Gesicht bekommt?","rueckmeldung":[{"option":1,"text":"Scheu klingt nach Vorsicht, aber sie senkt den Energiebedarf nicht: Große Tiere brauchen viel Nahrung, bei einer ganzen Population wären es täglich Tonnen. Das würde Pflanzen und Beutetiere sichtbar verändern."},{"option":2,"text":"Fehlende Belege allein beweisen nicht, dass es etwas nicht gibt. Müsste eine Population aber zwangsläufig Nahrungsspuren, Kot und Kadaver hinterlassen, dann spricht das Fehlen genau dieser Spuren sehr wohl gegen sie."},{"option":3,"text":"Einzelne Spuren sind schwer zu finden, das trifft zu. Erklären muss die Scheu aber, warum von einer ganzen Population Tausende Spuren und Kothaufen mit DNA sowie Kadaver nie bestätigt wurden, und das gelingt ihr nicht."}],"familie":"population-und-spuren","fertigkeit":"F1"},{"id":"qx-c1-047","clusterId":"C","werkstueckRef":"C.3.4","stufe":3,"question":"Jemand zeigt dir ein unscharfes Foto eines angeblichen Riesenprimaten in einem nordamerikanischen Wald und sagt: „Das ist der eindeutige Beweis, dass es diese Tiere gibt!“ Du willst das Foto nicht als Fälschung abtun. Wie antwortest du am überzeugendsten?","options":["Ein scharfes, echtes Foto würde die Existenz der Art belegen, denn nur an der Unschärfe dieses Bildes scheitert die Überzeugungskraft.","Auch ein echtes Foto reicht nicht aus, denn es zeigt höchstens ein Einzeltier, während eine Art eine Population braucht, die Kadaver, Knochen und DNA hinterlässt.","Das Foto genügt, wenn mehrere Zeugen es unabhängig bestätigen, denn dann spricht die Übereinstimmung für eine ganze Population.","Der Fotobeweis muss zuerst als Fälschung entlarvt werden, denn solange das nicht gelingt, bleibt die Existenz der Art bewiesen."],"correctIndex":1,"explanation":"Ein einzelnes Foto, selbst ein echtes, belegt höchstens ein Einzeltier. Eine Art kann aber nicht von einem Einzeltier oder einem Pärchen leben: Bei großen Säugetieren braucht es nach Schätzungen mehrere hundert bis einige tausend Individuen, die in Kontakt stehen, damit Inzucht, Gendefekte und Zufallskatastrophen die Gruppe nicht auslöschen. Eine so große Population hinterlässt jeden Tag messbare Spuren: Fußabdrücke, Kot (eine Fundgrube für DNA-Analysen), Schlafnester und Spuren in der Vegetation. Sie würde außerdem sterben und Kadaver, Knochen oder Fossilien hinterlassen. Bis heute wurde jedoch kein einziger Körper und kein junges Fossil eines solchen Wesens wissenschaftlich bestätigt, und keine der genetisch untersuchten Haarproben ließ sich einer unbekannten Primatenart zuordnen. Die Frage lautet also nicht „Ist auf dem Foto etwas Echtes zu sehen?“, sondern „Wo sind die Belege für eine ganze Population?“. Auch der Weg, erst die Fälschung entlarven zu wollen, führt nicht weiter: Die Logik der Populationsbiologie setzt nicht beim Foto an, sondern bei den Belegen, die eine ganze Population hinterlassen müsste. Mehr Zeugen für dasselbe Einzelbild ersetzen weder Kadaver noch DNA.","coreRule":"⚡ Ein Foto belegt höchstens ein Tier, eine Art braucht eine Population – mit Kadavern, Knochen und DNA.","beleg":"Werkstück C.3.4 (Werkbank-Frage; Red Flags; MVP-Abschnitt; Fußnote gl-c-mvp)","status":"entwurf","scenario":"Das Bild zeigt eine verschwommene, aufrecht gehende Gestalt am Waldrand. Der Fotograf behauptet, es handle sich um ein Mitglied einer bisher unentdeckten Tierart.","kurz":"Selbst ein echtes Foto zeigt höchstens ein Einzeltier, aber eine Art braucht eine Population von vielen Tieren. Die würde Kot, Kadaver, Knochen und DNA hinterlassen. Der Fehler wäre, beim Foto statt bei diesen Spuren anzusetzen.","prueffrage":"Welche Belege außer Fotos gibt es für Bären oder Elche in Nordamerika, und gibt es Vergleichbares für den Riesenprimaten?","rueckmeldung":[{"option":0,"text":"Ein schärferes Bild ließe sich besser beurteilen, deshalb wirkt die Unschärfe wie das eigentliche Problem. Aber auch ein makelloses, echtes Foto zeigt nur ein einzelnes Tier und belegt keine Art, die als ganze Population bestehen müsste."},{"option":2,"text":"Übereinstimmende Zeugen sprechen dafür, dass wirklich etwas gesehen wurde. Sie bleiben aber bei Einzelbeobachtungen und ersetzen weder Kadaver noch Knochen noch DNA, die eine ganze Population hinterlassen müsste."},{"option":3,"text":"Das Foto wirkt wie ein Beweis, dem erst jemand das Gegenteil nachweisen muss. Doch die Beweislast liegt bei der Behauptung: Dass sich keine Fälschung nachweisen lässt, belegt weder das Tier noch eine ganze Population."}],"familie":"population-und-spuren","fertigkeit":"F1"},{"id":"qx-c1-048","clusterId":"C","werkstueckRef":"C.3.4","stufe":4,"question":"Ein Reiseführer am Loch Ness behauptet, in dem See lebe seit der Dinosaurier-Zeit eine Population von Plesiosauriern. Welche Fragen prüfen diese Behauptung am besten?","options":["Wie viele Tiere es für das Überleben der Art bräuchten, wovon sie sich im See ernähren würden und wo die Kadaver blieben.","Wie alt die älteste Sichtung ist, ob mehrere Zeugen sie unabhängig bestätigt haben und ob sie auch nachts gelang.","Wie schnell ein Plesiosaurier schwimmen kann, ob Sonar-Echos Bewegung zeigen und wie groß die Objekte sind.","Ob sich Tiere im Tiefwasser verstecken können, ob man Einzelgänger von Paaren trennen kann und wie sie tauchen."],"correctIndex":0,"explanation":"Eine Art überlebt nicht als Einzeltier, sondern nur als Population, die groß genug für einen gesunden Genpool ist; bei großen Wirbeltieren schätzt man dafür meist mehrere hundert bis einige tausend Individuen. Eine solche Population bräuchte täglich viel Nahrung, würde den Fischbestand spürbar verändern und hinterließe Kadaver und Knochen, und ein begrenzter, gut erforschter See könnte sie kaum ernähren. Eine gezielte Umwelt-DNA-Suche in Loch Ness fand denn auch keine Reptilien-DNA. Dazu kommt: Das Tal war in der letzten Eiszeit von Gletschern bedeckt, den See gibt es erst seit rund 10.000 Jahren, also nicht seit der Zeit der Dinosaurier. Sichtungen oder ein Sonar-Echo würden dagegen nicht klären, ob eine überlebensfähige Population überhaupt existieren kann.","coreRule":"⚡ Prüfe die Herde, nicht das einzelne Wesen: Populationsgröße, Nahrung, Kadaver.","beleg":"Werkstück C.3.4 (Anwendung & Relevanz, „Bei Mythen über ‚überlebende Dinosaurier‘“; Aktivierungs-Frage; Red Flags)","status":"entwurf","scenario":"","kurz":"Eine Art besteht nur als Population, und die bräuchte täglich viel Nahrung und hinterließe Kadaver. Ein einzelnes Tier oder eine Sichtung klärt das nicht; die Frage nach der überlebensfähigen Population wird dabei leicht übersehen.","prueffrage":"Ließe sich die Behauptung auch prüfen, ohne dass je jemand eines der Tiere sieht oder ortet?","rueckmeldung":[{"option":1,"text":"Alter und Übereinstimmung von Zeugenberichten wirken wie solide Prüfung, und unabhängige Bestätigung ist ein Indiz. Selbst viele Sichtungen sagen aber nichts darüber, ob eine überlebensfähige Population überhaupt möglich ist."},{"option":2,"text":"Messdaten zu Tempo, Echo und Größe klingen nach harter Prüfung. Ein Sonar-Echo zeigt aber höchstens, dass sich dort etwas Bewegtes befindet, nicht, dass es ein Plesiosaurier ist oder wie viele es gäbe."},{"option":3,"text":"Fragen nach Verstecken und Tauchen betreffen das einzelne Tier und setzen schon voraus, dass es solche Tiere gibt. Ob ein begrenzter, gut erforschter See eine ganze Population tragen könnte, bleibt dabei ungeprüft."}],"familie":"population-und-spuren","fertigkeit":"F1"},{"id":"qx-c1-049","clusterId":"C","werkstueckRef":"C.3.6","stufe":1,"question":"Wie ist die Behauptung zu beurteilen, ein Werkzeug sei „nur menschengemacht“, wenn man seine Herkunft prüft?","options":["Die Behauptung hält nicht stand: Das Schneidesystem gibt es in der Natur als Abwehr von Bakterien gegen Viren, Forscher haben es nur umprogrammiert.","Die Behauptung hält stand: Weil Forscher das System so umprogrammiert haben, dass es jede DNA-Stelle schneidet, ist es in dieser Form ein reines Laborprodukt.","Die Behauptung hält nicht stand: Das System stammt aus menschlichen Abwehrzellen, die damit Krebszellen erkennen und deren DNA zerschneiden.","Die Behauptung hält nicht stand: Das System stammt aus Viren, die damit die DNA ihrer Wirtszellen zerschneiden, um sich darin einzubauen."],"correctIndex":0,"explanation":"Die Behauptung verwechselt die Umprogrammierung eines Werkzeugs mit seiner Entstehung. Bakterien speichern Bruchstücke der DNA früherer Angreifer als eine Art Fahndungsfoto-Archiv und zerschneiden bei erneutem Angriff mithilfe dieses Archivs und der Cas-Proteine die virale DNA, bei manchen Bakterien mit Cas9. Das System ist also ein uraltes natürliches Abwehrsystem. 2012 zeigten Doudna und Charpentier, dass man ihm eine beliebige „Adresse“ mitgeben kann, sodass es jede gewünschte Sequenz schneidet; dafür erhielten sie 2020 den Nobelpreis für Chemie. Dass die Herkunft natürlich ist, sagt allerdings noch nichts darüber, ob eine Anwendung sicher oder ethisch vertretbar ist. „Natürlich“ ist kein Gütesiegel und „künstlich“ kein Makel, geprüft werden muss die konkrete Anwendung.","coreRule":"⚡ Prüfe die Herkunft einer Sache, bevor du sie als „völlig neu“ oder „unnatürlich“ bewertest. Und bewerte die Anwendung nach Nutzen und Risiko, nicht nach dem Etikett „natürlich“ oder „künstlich“.","beleg":"Werkstück C.3.6 (Kontext & Tiefe, „Woher das Werkzeug kommt“); Fn. gl-c-crispr-immun (Doudna/Sternberg 2017); Fn. gl-c-crispr-nobel (Jinek u. a. 2012, Science 337, S. 816–821)","status":"entwurf","scenario":"In einer Diskussion über Gentechnik sagt jemand: „CRISPR ist ein rein künstliches Laborprodukt. Die Natur hat damit nichts zu tun, deshalb ist es ein unkontrollierbarer Eingriff in etwas, das es vorher nie gab.“ Du willst die Behauptung prüfen, bevor du sie bewertest.","kurz":"Wer ein umprogrammiertes Werkzeug für rein künstlich hält, verwechselt Umbau mit Ursprung: CRISPR/Cas ist ein altes bakterielles Abwehrsystem gegen Viren, das Forscher nur auf neue Zielstellen eingestellt haben.","prueffrage":"Woher stammen die Bausteine, die in diesem Verfahren eingesetzt werden, und was haben die Forscher daran verändert?","rueckmeldung":[{"option":1,"text":"Dass Forscher dem System beliebige Zielstellen mitgeben können, stimmt und war eine echte Leistung. Das ändert aber nichts an seinem Ursprung: Umprogrammiert wurde ein vorhandenes bakterielles Abwehrsystem, erfunden wurde es nicht."},{"option":2,"text":"Eine Abwehrfunktion gegen Eindringlinge gibt es hier tatsächlich, nur an anderer Stelle: Das System stammt aus Bakterien, nicht aus menschlichen Zellen. Menschliche Abwehrzellen erkennen zwar Krebszellen, tun das aber nicht mit diesem Schneidesystem."},{"option":3,"text":"Viren sind im Spiel, aber in der umgekehrten Rolle: Bakterien nutzen das System, um sich gegen Viren zu wehren. Es stammt aus der Abwehr der Bakterien und dient nicht den Viren zum Einbau in fremde DNA."}],"familie":"natuerlich-kein-guetesiegel","fertigkeit":"F2"},{"id":"qx-c1-050","clusterId":"C","werkstueckRef":"C.3.6","stufe":2,"question":"Welche Antwort begründet am besten, warum der erste Fall unstrittig als medizinischer Fortschritt gilt, der zweite aber nicht?","options":["Bei Meldung 1 ist die Veränderung auf den behandelten Menschen beschränkt, er kann zustimmen, und die Anwendung ist geprüft und zugelassen; bei Meldung 2 trifft all das nicht zu.","Bei Meldung 1 wird ein anderes Werkzeug verwendet als bei Meldung 2, und nur das Werkzeug der ersten Meldung gilt als sicher und ethisch unbedenklich.","Bei Meldung 1 wird ein Embryo behandelt, bei Meldung 2 ein Erwachsener, und Eingriffe an Embryonen gelten bei gleichem Werkzeug als besonders unbedenklich.","Bei Meldung 1 ist die Therapie umstritten, weil sie vererbbar ist, bei Meldung 2 gilt sie als unstrittig, weil das Ziel eines Infektionsschutzes erreicht wird."],"correctIndex":0,"explanation":"Beide Meldungen nutzen dasselbe Werkzeug, der Unterschied liegt woanders. Bei der zugelassenen Therapie wird nur der behandelte Mensch verändert (somatisch, nicht vererbbar), er ist einwilligungsfähig, die Krankheit ist schwer und gut verstanden, und Behörden haben die Anwendung nach klinischer Prüfung zugelassen (Großbritannien im November 2023, USA im Dezember 2023). Beim Embryo-Eingriff wird dagegen das Erbgut aller künftigen Generationen verändert, ohne dass diese je zustimmen konnten. Die Folgen lassen sich nicht zurücknehmen, und der Eingriff erfolgte an gesunden Embryonen zur Vorbeugung statt zur Heilung. Wer beides unter „Gentechnik“ in einen Topf wirft, übersieht genau die Fragen, auf die es ankommt: Welche Zellen sind betroffen, wer stimmt zu, wird geheilt oder „verbessert“, ist die Anwendung geprüft?","coreRule":"⚡ Bei Gentechnik zählt nicht das Werkzeug, sondern: Welche Zellen werden verändert, wer stimmt zu, wird geheilt oder verbessert, und ist die Anwendung geprüft?","beleg":"Werkstück C.3.6 (Kontext & Tiefe, „Wo CRISPR heute bereits legal Leben rettet“; Kipppunkt); Fn. gl-c-casgevy (MHRA 16.11.2023; FDA 8.12.2023)","status":"entwurf","scenario":"Zwei Meldungen zur Genschere CRISPR:\\n\\nMeldung 1: Eine Therapie gegen die Sichelzellkrankheit wurde von mehreren Zulassungsbehörden genehmigt. Dabei werden einem jugendlichen oder erwachsenen Patienten Blutstammzellen entnommen, außerhalb des Körpers gezielt editiert und zurückgegeben.\\n\\nMeldung 2: Ein Forscher verkündet, er habe Embryonen gesunder Eltern editiert, um die Kinder gegen eine Infektion zu schützen. Die Veränderung wird an alle späteren Nachkommen weitergegeben.","kurz":"Beide Fälle nutzen dasselbe Werkzeug; entscheidend ist, wen die Veränderung trifft. Die zugelassene, geprüfte Therapie verändert nur den Menschen, der zugestimmt hat, der Embryo-Eingriff dagegen das Erbgut aller Nachkommen, die nie zustimmen konnten.","prueffrage":"Welche Angaben machen die beiden Meldungen zu Werkzeug, behandelter Person und Weitergabe der Veränderung, und wo unterscheiden sie sich?","rueckmeldung":[{"option":1,"text":"Ein anderes Werkzeug als Erklärung liegt nahe, wenn ein Fall gelobt und der andere kritisiert wird. Beide Meldungen handeln aber von CRISPR; der Unterschied liegt darin, welche Zellen verändert werden und wer zustimmen kann."},{"option":2,"text":"Hier sind die Fälle vertauscht: In Meldung 1 werden Blutstammzellen eines Jugendlichen oder Erwachsenen editiert, in Meldung 2 Embryonen. Besonders unbedenklich sind Eingriffe am Embryo auch nicht, denn sie wirken auf alle Nachkommen."},{"option":3,"text":"Vererbbarkeit ist tatsächlich ein zentraler Streitpunkt, sie betrifft aber nur den Embryo-Eingriff. Die zugelassene Therapie ist nicht vererbbar, und ein erreichtes Schutzziel macht eine unumkehrbare Veränderung des Erbguts nicht unstrittig."}],"familie":"nutzen-und-risiko-abwaegen","fertigkeit":"F4"},{"id":"qx-c1-051","clusterId":"C","werkstueckRef":"C.3.6","stufe":3,"question":"Eine Kommentatorin schreibt zu einem Gentechnik-Skandal: „Das Problem war das Werkzeug. Wer CRISPR benutzt, spielt mit dem Feuer – wer es einsetzt, hat die Grenze schon überschritten.“ Tatsächlich wird CRISPR in Laboren weltweit routinemäßig genutzt, und eine CRISPR-basierte Therapie ist bei Sichelzellkrankheit zugelassen. Welche Frage trennt den Skandalfall am besten von dieser legalen Anwendung?","options":["Welche Zellen wurden verändert, wer konnte zustimmen und wurde eine bestehende Krankheit behandelt oder ein gesunder Mensch verändert?","Wie neu und aufwendig ist das eingesetzte Werkzeug im Vergleich zu älteren Verfahren der Gentechnik?","Wie viele Länder haben das Verfahren in ihren Laboren bereits eingesetzt und wie lange nutzen sie es schon?","Wie bekannt ist der Forscher in der Öffentlichkeit und wie professionell wirkt sein Auftreten in den Medien?"],"correctIndex":0,"explanation":"Wenn dasselbe Werkzeug in einem Fall verurteilt und im anderen zugelassen wird, kann das Werkzeug den Unterschied nicht erklären. Er muss in den Umständen der Anwendung liegen. Hier gab es zwei Grenzüberschreitungen zugleich: Gesunden Embryonen wurde ein Gen ausgeschaltet, um sie später vor einer HIV-Infektion zu schützen – eine Vorbeugung, keine Heilung einer bestehenden Krankheit. Und die Veränderung betrifft die Keimbahn und wird an alle Nachkommen weitergegeben, die nie zustimmen konnten. Bei der zugelassenen Sichelzell-Therapie werden dagegen Blutstammzellen eines einwilligungsfähigen Patienten außerhalb des Körpers editiert. Das betrifft nur diese Person, und die Krankheit besteht bereits. Die Frage nach Zellart, Zustimmung und Behandlungsziel trennt beide Fälle sauber. Neuheit, Verbreitung oder Medienwirkung sagen dagegen nichts darüber, ob ein Eingriff vertretbar ist.","coreRule":"⚡ Wenn dasselbe Werkzeug mal verurteilt, mal zugelassen wird, liegt der Unterschied in der Anwendung: Welche Zellen, wer stimmt zu, Heilung oder Verbesserung?","beleg":"Werkstück C.3.6 (Der Tag, an dem die Grenze verschwand; Kipppunkt; Wo CRISPR heute bereits legal Leben rettet); Fn. gl-c-hejiankui (Verurteilung in Shenzhen, Dezember 2019); Fn. gl-c-casgevy (Zulassung MHRA/FDA 2023)","status":"entwurf","scenario":"Ein Forscher hat 2018 mit CRISPR ein Gen im Erbgut von Embryonen ausgeschaltet, um die später geborenen Kinder gegen eine Virusinfektion zu schützen. Die Kinder waren gesund. Fachwelt und Behörden verurteilten das Experiment, der Forscher wurde 2019 zu drei Jahren Haft verurteilt. Dieselbe Technik wird in anderen Fällen als zugelassene Therapie eingesetzt.","kurz":"Wenn dasselbe Werkzeug einmal verurteilt und einmal zugelassen wird, liegt der Unterschied in den Umständen der Anwendung: Zellart, Einwilligung und Behandlungsziel. Wer das Werkzeug verantwortlich macht, übersieht genau das.","prueffrage":"Was haben der verurteilte Versuch und die zugelassene Therapie gemeinsam, und worin unterscheiden sie sich?","rueckmeldung":[{"option":1,"text":"Dass CRISPR ein junges Verfahren ist, klingt nach einem Grund für Vorsicht. In beiden Fällen kam aber dasselbe Werkzeug zum Einsatz, also kann es nicht erklären, warum ein Fall verurteilt und der andere zugelassen wurde."},{"option":2,"text":"Wie weit und wie lange ein Verfahren genutzt wird, zeigt, wie etabliert es ist. Ob ein bestimmter Eingriff am Menschen vertretbar ist, sagt es nicht, denn auch ein verbreitetes Werkzeug kann in einem Fall unzulässig angewandt werden."},{"option":3,"text":"Bekanntheit und Medienauftritt prägen, wie der Fall wahrgenommen wird. Über den Eingriff selbst sagen sie nichts: weder welche Zellen verändert wurden noch wer zustimmen konnte oder ob eine Krankheit behandelt wurde."}],"familie":"nutzen-und-risiko-abwaegen","fertigkeit":"F4"},{"id":"qx-c1-052","clusterId":"C","werkstueckRef":"C.3.6","stufe":4,"question":"Welche Einordnung des Angebots ist am besten begründet?","options":["Das Angebot ist seriös, weil die Methode mit dem Nobelpreis ausgezeichnet wurde und damit als ausreichend geprüft gilt.","Das Angebot ist unbedenklich, weil bei Erwachsenen keine Keimbahn betroffen ist und damit kein Risiko besteht.","Das Angebot ist unseriös, weil jede Gentechnik am Menschen grundsätzlich gefährlich ist, auch als zugelassene Therapie.","Das Angebot ist ein Warnsignal, weil Hoffnung verkauft wird, bevor Wirksamkeit und Sicherheit belegt sind."],"correctIndex":3,"explanation":"Ein Nobelpreis würdigt die Entdeckung einer Methode, nicht die Wirksamkeit oder Sicherheit einer einzelnen Anwendung. Ob eine Behandlung hilft, zeigen nur kontrollierte Studien und eine behördliche Zulassung. Die Klinik bietet außerhalb davon eine Behandlung gegen ein derart breites Ziel wie „Alterung“ an, zeigt keine Belege und verlangt hohe Preise: Hier wird Hoffnung zu Geld gemacht, bevor die Wissenschaft nachgezogen hat. Dass keine Keimbahn betroffen ist, macht den Eingriff nicht automatisch sicher; auch Eingriffe an Körperzellen können schaden und müssen ihren Nutzen belegen. Umgekehrt ist die pauschale Ablehnung jeder Gentechnik ebenfalls ein Fehlschluss, denn zugelassene, geprüfte Therapien wie die gegen die Sichelzellkrankheit zeigen, dass dieselbe Methode in geprüfter Form Leben retten kann. Seriös wäre ein Angebot erst als zugelassenes Medikament oder im Rahmen einer regulären klinischen Studie. Entscheidend ist also nicht die Technik, sondern der Prüfstatus der konkreten Anwendung.","coreRule":"⚡ Prüfe bei „CRISPR-Angeboten“ zuerst: Gibt es ein zugelassenes Medikament oder eine reguläre Studie? Wenn nicht, ist Vorsicht geboten. Ein Preis für die Methode ist kein Beleg für die Anwendung.","beleg":"Werkstück C.3.6 (Anwendung & Relevanz, „Gegen unregulierte ‚Gentherapie‘-Kliniken“; Red Flags)","status":"entwurf","scenario":"Eine Klinik wirbt außerhalb von Studien mit „CRISPR-Behandlungen gegen Alterung“. Die Behandlung kostet mehrere zehntausend Euro. Belastbare Wirksamkeitsnachweise zeigt die Klinik nicht, nennt aber stolz, dass die Entwickler der Methode den Nobelpreis erhalten haben.","kurz":"Entscheidend ist der Prüfstatus der konkreten Anwendung: Ein Nobelpreis würdigt die Entdeckung der Methode, nicht ihre Wirksamkeit gegen „Alterung“. Ohne kontrollierte Studien und Zulassung wird hier Hoffnung verkauft, bevor Nutzen und Sicherheit belegt sind.","prueffrage":"Was führt die Klinik zu ihren Gunsten an, und bezieht sich das auf die Methode allgemein oder auf genau diese Behandlung?","rueckmeldung":[{"option":0,"text":"Der Nobelpreis ist echt und würdigt eine bedeutende Entdeckung. Er sagt aber nichts darüber, ob diese eine Behandlung wirkt oder sicher ist: Das Ansehen der Methode wird hier auf ein ungeprüftes Angebot übertragen."},{"option":1,"text":"Dass keine Keimbahn betroffen ist, heißt nur, dass nichts vererbt wird. Auch Eingriffe an Körperzellen können schaden und müssen ihren Nutzen erst belegen, ein fehlendes Risiko folgt daraus nicht."},{"option":2,"text":"Das Urteil „unseriös“ trifft zu, die Begründung aber nicht: Die zugelassene Therapie gegen die Sichelzellkrankheit zeigt, dass dieselbe Methode in geprüfter Form Leben retten kann. Es kommt auf den Prüfstatus der Anwendung an, nicht auf die Technik."}],"familie":"nutzen-und-risiko-abwaegen","fertigkeit":"F4"},{"id":"qx-c1-053","clusterId":"C","werkstueckRef":"C.4.1","stufe":1,"question":"Welche Schlussfolgerung stützen die Daten am besten?","options":["Die Erkrankung wird durch winzige, unsichtbare Krankheitserreger verursacht, die an den Händen vom Seziersaal zu den Müttern gelangen.","Die Erkrankung wird durch schlechte Dünste im Kreißsaal verursacht, die das Gleichgewicht der Körpersäfte der Mütter stören.","Die Erkrankung hat keine äußere Ursache: Die Mütter der ersten Abteilung waren schon zuvor geschwächt und die Waschung hat zufällig zeitgleich gewirkt.","Die Erkrankung ist eine Folge des ungesunden Milieus im Körper der Mütter, die Chlorlösung hat dieses Milieu auf den Händen verbessert."],"correctIndex":0,"explanation":"Der Unterschied zwischen den Abteilungen fällt mit einem Faktor zusammen: Wer aus dem Seziersaal kommt, trägt etwas auf den Händen zu den Müttern. Dass die Sterblichkeit nach dem Desinfizieren der Hände sofort und deutlich fällt, stützt diese Ursache: Wird die vermutete Ursache entfernt, verschwindet der Effekt. Das passt zu der Erklärung, dass viele Krankheiten durch unsichtbare Mikroorganismen verursacht werden, die in den Körper gelangen und sich dort vermehren (Keimtheorie). Die Erklärung mit schlechten Dünsten sagt nichts darüber, warum die Hebammen-Abteilung im selben Haus verschont bleibt und warum Händewaschen helfen sollte. Die Annahme eines Zufalls oder eines „ungesunden Milieus“ erklärt weder den Unterschied zwischen den Abteilungen noch den Abfall auf einen Schlag nach der Maßnahme.","coreRule":"⚡ Wenn das Entfernen einer vermuteten Ursache die Wirkung beseitigt und ein Unterschied zwischen Gruppen genau mit dieser Ursache zusammenfällt, ist die Ursachen-Erklärung gestützt – bei Krankheiten oft: ein spezifischer Erreger statt diffuser „Dünste“ oder „Milieus“.","beleg":"Werkstück C.4.1 (Kernidee; Kontext & Tiefe)","status":"entwurf","scenario":"In einer Geburtsklinik gibt es zwei Abteilungen. In der ersten, betreut von Ärzten und Medizinstudenten, sterben bis zu 18 % der Mütter an Kindbettfieber. In der zweiten, betreut ausschließlich von Hebammen, sind es etwa 2 %. Die Ärzte und Studenten kommen vor ihrer Arbeit direkt aus dem Seziersaal, die Hebammen nicht. Nachdem sich alle Ärzte vor jeder Untersuchung die Hände in einer Chlorlösung desinfizieren müssen, fällt die Sterblichkeit in der ersten Abteilung auf unter 2 %.","kurz":"Der Unterschied fällt mit dem Weg vom Seziersaal zu den Müttern zusammen, und nach dem Desinfizieren der Hände sinkt die Sterblichkeit auf unter 2 %. Wird die vermutete Ursache entfernt und verschwindet der Effekt, stützt das die Annahme unsichtbarer Erreger an den Händen.","prueffrage":"Worin unterscheiden sich die beiden Abteilungen außer der Sterblichkeit noch, und was änderte sich genau vor dem Rückgang?","rueckmeldung":[{"option":1,"text":"Schlechte Luft war lange eine gängige Erklärung für solche Krankheiten und klingt vertraut. Dünste erklären aber nicht, warum die Hebammen-Abteilung im selben Haus verschont bleibt und warum Händewaschen helfen sollte."},{"option":2,"text":"Zufall ist bei schwankenden Zahlen immer möglich. Hier unterscheiden sich die Abteilungen aber deutlich, und der Abfall folgt auf die Maßnahme; das wäre ein sehr unwahrscheinliches Zusammentreffen, zumal von vorgeschwächten Müttern keine Rede ist."},{"option":3,"text":"Ein „ungesundes Milieu“ klingt nach einer Erklärung, lässt sich aber kaum prüfen. Es sagt nicht, warum die Mütter der Hebammen-Abteilung verschont bleiben. Die Chlorlösung wirkt zudem auf den Händen der Ärzte, nicht im Körper der Mütter."}],"familie":"korrelation-und-ursache","fertigkeit":"F2"},{"id":"qx-c1-054","clusterId":"C","werkstueckRef":"C.4.1","stufe":2,"question":"Welche Schlussfolgerung passt am besten zu dem Muster in den Beobachtungen, und welcher nächste Schritt prüft sie?","options":["Etwas von den Leichen gelangt über die Hände der Ärzte zu den Müttern; die Ärzte sollten sich vor jeder Untersuchung die Hände desinfizieren und die Sterblichkeit weiter beobachten.","Die Hebammen haben mehr Erfahrung bei Geburten als die Ärzte; die Ärzte sollten von ihnen geschult werden und die Sterblichkeit weiter beobachten.","Schlechte Luft aus dem Seziersaal verteilt sich im ganzen Haus; die erste Abteilung sollte stärker belüftet werden und die Sterblichkeit weiter beobachtet werden.","Der Tod des Arztes ist ein trauriger Einzelfall ohne Aussagekraft; die Ärzte sollten die bisherigen Versuche mit anderen Geburtspositionen fortsetzen und die Sterblichkeit weiter beobachten."],"correctIndex":0,"explanation":"Die Ausgangslage legt einen gemeinsamen Faktor nahe: Genau die Gruppe mit der hohen Sterblichkeit kommt vom Sezieren, die andere nicht. Dass der Arzt nach einer Verletzung bei der Leichenöffnung an denselben Symptomen stirbt, stützt die Annahme, dass etwas von den Leichen die Krankheit auslöst. Der Weg über die Hände erklärt, warum die Abteilung mit den Ärzten betroffen ist und die andere nicht. Diese Erklärung lässt sich gezielt prüfen: Wenn sich die Ärzte die Hände desinfizieren und die Sterblichkeit sinkt, spricht das für sie. Genau das geschah historisch bei Semmelweis in Wien, wo die Rate nach Chlorwaschungen auf unter zwei Prozent fiel, zeitweise unter eins. Das Lüften erklärt nicht, warum nur die Abteilung der Ärzte betroffen ist, und hatte bereits nichts gebracht. Mehr Erfahrung der Hebammen erklärt nicht die Symptome des gestorbenen Arztes. Den Todesfall als Zufall abzutun wirft den stärksten Hinweis weg. Eine Beobachtung kann den Anfang liefern, belastbar wird die Erklärung erst durch Prüfung und Wiederholung.","coreRule":"⚡ Such den Faktor, in dem sich die Gruppen unterscheiden, formuliere daraus eine Erklärung und prüfe sie mit einer gezielten Maßnahme.","beleg":"Werkstück C.4.1 (Der Arzt, der sich die Hände wusch; Verbindungen); Fn. gl-c-semmelweis (Semmelweis 1861; Best/Neuhauser 2004)","status":"entwurf","scenario":"Eine Klinik hat zwei Geburtsabteilungen. In der ersten, betreut von Ärzten und Medizinstudenten, sterben bis zu 18 % der Mütter an Kindbettfieber, in der zweiten, betreut von Hebammen, nur etwa 2 %. Geburtsposition und Belüftung wurden schon verändert, ohne dass sich etwas bessert. Dann stirbt ein Arzt der Klinik an einer Schnittwunde, die er sich bei einer Leichenöffnung zugezogen hat, mit denselben Symptomen wie die erkrankten Mütter. Die Ärzte und Studenten der ersten Abteilung kommen direkt aus dem Seziersaal, die Hebammen nicht.","kurz":"Die erste Abteilung ist genau die, deren Personal vom Sezieren kommt, und ein Arzt stirbt nach einer Leichenverletzung an denselben Symptomen. Das spricht dafür, dass etwas von den Leichen über die Hände zu den Müttern gelangt; prüfen lässt sich das mit Händedesinfektion.","prueffrage":"Was haben die Personen der Abteilung mit hoher Sterblichkeit gemeinsam, das bei der anderen Abteilung fehlt?","rueckmeldung":[{"option":1,"text":"Dass Hebammen viel Erfahrung mit Geburten haben, ist gut vorstellbar und könnte einen Unterschied erklären. Es erklärt aber nicht, warum ein Arzt nach einer Verletzung bei einer Leichenöffnung an denselben Symptomen stirbt wie die Mütter."},{"option":2,"text":"Schlechte Luft scheint ein Haus als Ganzes zu betreffen, doch gerade das passt nicht: Nur die erste Abteilung ist stark betroffen. Außerdem hatte eine veränderte Belüftung schon nichts gebracht."},{"option":3,"text":"Weitere Geburtspositionen auszuprobieren wirkt gründlich, hat aber schon keine Besserung gebracht. Und der Tod des Arztes ist kein beliebiger Einzelfall: Er folgt auf eine Leichenverletzung und zeigt dieselben Symptome, ist also der stärkste Hinweis."}],"familie":"korrelation-und-ursache","fertigkeit":"F2"},{"id":"qx-c1-055","clusterId":"C","werkstueckRef":"C.4.1","stufe":3,"question":"Welche Bewertung ist an diesem Gespräch am stichhaltigsten?","options":["Ein gesunder Lebensstil ist sinnvoll, ersetzt aber nicht den gezielten Schutz gegen einen bestimmten Erreger. Bei Wundstarrkrampf reicht allgemeine Abwehrstärke nicht aus.","Ein gesunder Lebensstil ist sinnlos, weil Infektionen allein von Keimen abhängen. Wer sich gesund ernährt, verschwendet seine Mühe.","Ein gut trainierter Körper ist ausreichend geschützt, solange man sich gesund fühlt. Er wehrt jeden Erreger ab, bevor ein Schaden entsteht.","Ein Mangel an Schlaf und Bewegung ist das eigentliche Problem, weil eine dauerhaft geschwächte Abwehr die Ursache jeder Infektion ist."],"correctIndex":0,"explanation":"Ein gesunder Lebensstil und ein gut funktionierendes Immunsystem helfen dabei, Krankheiten abzuwehren. Der Fehler liegt woanders: Die Bekannte setzt diese allgemeinen Maßnahmen an die Stelle von spezifischen Schutzmaßnahmen. Tetanus wird durch einen bestimmten Erreger verursacht. Dagegen schützt die Impfung gezielt, und bei einer bakteriellen Wundinfektion wirken Antibiotika gezielt gegen den Erreger. Allgemeine Abwehrstärke kann das nicht ersetzen. Wer die Rolle des Lebensstils bestreitet, übertreibt in die Gegenrichtung. Wer aus dem Wohlbefinden auf Unverwundbarkeit schließt, verwechselt ein Gefühl mit einem Beleg. Wer jede Infektion auf eine geschwächte Abwehr zurückführt, übersieht, dass selbst ein starkes Immunsystem bei Tetanus oder schwerer bakterieller Sepsis Impfung oder Antibiotika nicht ersetzt.","coreRule":"⚡ Lebensstil stärkt, ersetzt aber weder Impfung noch Antibiotika bei Infektionen mit spezifischen Erregern.","beleg":"Werkstück C.4.1 (Der Kipppunkt; Red Flags)","status":"entwurf","scenario":"Eine Bekannte erzählt: „Ich ernähre mich sehr bewusst, schlafe gut und treibe viel Sport. Mein Immunsystem ist bestens, deshalb brauche ich keine Tetanus-Impfung. Und wenn ich mir mal an rostigem Metall die Hand aufreiße und die Wunde sich entzündet, kommt kein Antibiotikum infrage, ich vertraue auf meine Abwehrkräfte.“","kurz":"Allgemeine Abwehrkraft schützt nicht gezielt vor einem bestimmten Erreger wie dem Tetanus-Bakterium. Der Denkfehler: Ein guter Lebensstil wird an die Stelle von Impfung und Antibiotikum gesetzt, obwohl er sie nicht ersetzen kann.","prueffrage":"Erkranken auch sportliche, gut ernährte Menschen ohne Impfung an Wundstarrkrampf, und wie ließe sich das nachprüfen?","rueckmeldung":[{"option":1,"text":"Dass Keime Infektionen auslösen, stimmt. Daraus folgt aber nicht, dass Ernährung, Schlaf und Bewegung nutzlos wären: Sie unterstützen die Abwehr, ersetzen nur keinen gezielten Schutz."},{"option":2,"text":"Wer sich fit fühlt, schließt leicht auf zuverlässigen Schutz. Wohlbefinden sagt aber nichts darüber, ob der Körper einen bestimmten Erreger beherrscht, und bei Tetanus oder schwerer Sepsis reicht auch ein starkes Immunsystem nicht aus."},{"option":3,"text":"Schlaf und Bewegung stützen die Abwehr, und eine geschwächte Abwehr begünstigt manche Infektionen. Ursache jeder Infektion ist sie aber nicht: Auch Gesunde stecken sich an, und bei Wundstarrkrampf ersetzt selbst eine starke Abwehr die Impfung nicht."}],"familie":"ergaenzen-oder-ersetzen","fertigkeit":"F4"},{"id":"qx-c1-056","clusterId":"C","werkstueckRef":"C.4.1","stufe":4,"question":"Ein Therapeut behauptet: „Keime sind nicht die Ursache von Infektionen, sondern nur ein Symptom des ‚ungesunden Milieus‘. Mit einer Entsäuerungskur heilst du die Krankheit.“ Welche Rückfrage prüft diese Behauptung am besten?","options":["Wer hat die Milieu-Idee entwickelt, denn so alte Theorien aus dem 19. Jahrhundert sind allein wegen ihres Alters überholt?","Wie erklärt diese Sicht, dass sich dieselbe Krankheit bei jeder Ansteckung mit demselben Erreger zeigt, denn eine Behauptung muss zu den Befunden passen?","Wie viele zufriedene Kunden hat die Kur, denn spürbare Besserung nach der Anwendung beweist, dass die Therapie wirkt?","Sind Keime nur unter dem Mikroskop sichtbar, denn nur mit bloßem Auge Sichtbares kann als Krankheitsursache gelten?"],"correctIndex":1,"explanation":"Eine Behauptung wird nicht dadurch stark, dass sie plausibel klingt, sondern dadurch, dass sie die vorhandenen Befunde erklären kann. Hier lautet der Befund: Bestimmte Mikroben lösen bestimmte Krankheiten mit bestimmten Symptomen aus, und wo man die Übertragung der Erreger gezielt unterbindet (Hygiene, Impfung, Antibiotika), sinkt die Erkrankungsrate. Das Beispiel Semmelweis zeigt, wie stark so ein Eingriff wirkt: Nach der Einführung der Chlorwaschungen fiel die Sterblichkeit durch Kindbettfieber in seiner Abteilung von bis zu 18 Prozent auf unter zwei Prozent. Erst die Arbeit von Pasteur und Koch bestätigte später die Keimtheorie dahinter. Wer behauptet, Keime seien nur ein Symptom, muss erklären, warum diese Muster so zuverlässig auftreten. Das Alter einer Idee sagt nichts darüber, ob sie zu den Befunden passt. Auch die Zufriedenheit einzelner Kunden beantwortet diese Frage nicht, denn sie zeigt nicht, ob die Kur der Grund für die Besserung war. Dass Keime mit bloßem Auge unsichtbar sind, spricht nicht gegen ihre Wirkung, denn die Wirkung zeigt sich in den Folgen, nicht in der Sichtbarkeit.","coreRule":"⚡ Verlange Erklärung für die Belege: Wer eine etablierte Ursache bestreitet, muss erklären, warum spezifische Mikroben, spezifische Krankheiten und Heilung durch Beseitigung der Mikroben so zuverlässig zusammenfallen.","beleg":"Werkstück C.4.1 (Anwendung & Relevanz, „Bei der Leugnung der Keimtheorie“; Aktivierungs-Frage)","status":"entwurf","kurz":"Eine Behauptung überzeugt nicht durch Plausibilität, sondern dadurch, dass sie die Befunde erklärt. Wer Keime zum bloßen Symptom erklärt, muss erklären, warum bestimmte Erreger zuverlässig bestimmte Krankheiten auslösen und warum weniger Übertragung weniger Erkrankungen bringt.","prueffrage":"Was geschieht mit der Zahl bestimmter Erkrankungen, wenn Hygiene oder Impfung die Übertragung ihrer Erreger unterbindet?","rueckmeldung":[{"option":0,"text":"Wer eine Behauptung auf ihren Ursprung zurückverfolgt, wirkt gründlich. Das Alter einer Idee entscheidet aber nicht über ihre Geltung: Ob sie trägt, zeigt sich daran, ob sie zu den vorhandenen Befunden passt."},{"option":2,"text":"Zufriedene Kunden wirken wie ein Beleg aus der Praxis. Sie zeigen aber nur, dass es nach der Kur vielen besser ging, nicht, dass die Kur der Grund war. Die Besserung kann auch ohne sie eingetreten sein."},{"option":3,"text":"Dass Keime nur unter dem Mikroskop sichtbar sind, stimmt, und das Unsichtbare kann Misstrauen wecken. Ob etwas Ursache sein kann, hängt aber nicht von seiner Sichtbarkeit ab, sondern davon, ob sich seine Wirkung in den Folgen zeigt."}],"familie":"beweislast-klaeren","fertigkeit":"F1"},{"id":"qx-c1-057","clusterId":"C","werkstueckRef":"C.4.2","stufe":1,"question":"Eine Freundin hat eine fiebrige Erkältung und will sich beim Arzt „etwas Starkes“ verschreiben lassen: „Das ist eine Infektion, also muss ein Antibiotikum her.“ Wie beurteilst du ihre Schlussfolgerung?","options":["Sie ist berechtigt, denn bei jeder Infektion vermehrt sich ein Erreger im Körper, und Antibiotika bremsen jede Vermehrung von Erregern.","Sie ist unvollständig, denn entscheidend ist der Erreger: Antibiotika wirken nur gegen Bakterien, nicht gegen Viren.","Sie ist nur bei mildem Verlauf falsch, denn bei hohem Fieber erreichen Antibiotika im Körper auch Viren in den Zellen.","Sie ist nur dann berechtigt, wenn der Erreger kleiner als ein Bakterium ist, denn Viren sind besonders kleine Einzeller."],"correctIndex":1,"explanation":"„Infektion“ sagt nur, dass ein Erreger im Körper ist, nicht welcher. Bakterien sind einzellige Lebewesen mit eigenem Stoffwechsel; Antibiotika greifen Strukturen an, die menschlichen Zellen fehlen oder sich von ihnen unterscheiden, etwa die bakterielle Zellwand. Viren gelten meist nicht als Lebewesen: Sie bestehen aus Erbgut in einer Proteinhülle, haben weder Zellwand noch eigenen Stoffwechsel und vermehren sich nur, indem sie eine Wirtszelle umprogrammieren, deshalb wirken Antibiotika gegen sie nicht, auch bei starken Symptomen. Unnötiger Einsatz begünstigt zudem resistente Bakterien. Die klärende Frage lautet also nicht „Infektion ja oder nein?“, sondern „Welcher Erreger?“.","coreRule":"⚡ Erst fragen, welcher Erreger: Bakterium (eigenständiger Zwerg) oder Virus (Gen-Pirat, der eine Zelle kapern muss). Davon hängt die Behandlung ab.","beleg":"Werkstück C.4.2 (Kernidee; Kontext & Tiefe, „Bakterien“ und „Viren“; Anwendung & Relevanz, Antibiotika-Krise)","status":"entwurf","scenario":"","kurz":"„Infektion“ sagt nur, dass ein Erreger im Körper ist, nicht welcher, und Antibiotika wirken nur gegen Bakterien, nicht gegen Viren. Wer aus „Infektion“ direkt auf „Antibiotikum“ schließt, überspringt die Frage nach dem Erreger.","prueffrage":"Wie verlaufen fiebrige Erkältungen gewöhnlich, und in welchen Fällen verschreiben Ärzte dabei überhaupt ein Antibiotikum?","rueckmeldung":[{"option":0,"text":"Dass sich bei einer Infektion ein Erreger vermehrt, stimmt; Antibiotika bremsen aber nicht jede Vermehrung, sondern greifen bakterielle Strukturen wie die Zellwand an. Viren vermehren sich in Wirtszellen und werden davon nicht getroffen."},{"option":2,"text":"Hohes Fieber wirkt wie ein Grund für stärkere Mittel. Der Schweregrad verrät aber nicht sicher, welcher Erreger dahintersteckt, und Viren bieten Antibiotika keinen Angriffspunkt, gleich ob die Symptome leicht oder stark sind."},{"option":3,"text":"Viren sind zwar kleiner als Bakterien, aber keine Einzeller, und meist zählt man sie nicht einmal zu den Lebewesen. Auf die Größe kommt es zudem nicht an: Antibiotika setzen an bakteriellen Strukturen an, die Viren fehlen."}],"familie":"genau-unterscheiden","fertigkeit":"F1"},{"id":"qx-c1-058","clusterId":"C","werkstueckRef":"C.4.2","stufe":2,"question":"Eine Bekannte lehnt eine Impfung ab: „Da spritzen die mir ja die Krankheit direkt in den Körper.“ Welche Erwiderung trifft den Kern?","options":["Impfstoffe enthalten stets den vollständigen, voll aktiven Erreger, der eine leichte Erkrankung auslöst. Genau das erzeugt den Schutz.","Impfstoffe enthalten oft nur ungefährliche Bestandteile oder abgeschwächte bzw. abgetötete Erreger. Das Immunsystem lernt daran, den Erreger zu erkennen.","Impfstoffe wirken wie Antibiotika und töten den Erreger im Körper ab. Das Immunsystem muss dann gar nicht eingreifen.","Impfstoffe zerstören die Proteinhülle des Virus im Körper. Danach ist der Erreger harmlos und die Abwehr nicht mehr nötig."],"correctIndex":1,"explanation":"Die Sorge verwechselt den vollständigen, aktiven Erreger mit dem, was tatsächlich gespritzt wird. Impfstoffe enthalten oft nur harmlose Bestandteile des Erregers, etwa ein Oberflächenprotein oder ein unschädlich gemachtes Bakteriengift, oder abgeschwächte bzw. abgetötete Erreger, die in aller Regel keine Krankheit auslösen. Daran lernt das Immunsystem den Eindringling kennen wie an einem „Fahndungsfoto“ und bildet Antikörper und Gedächtniszellen, sodass es den echten Erreger später rasch erkennt und bekämpft. Antibiotika scheiden als Erklärung aus: Eine Impfung tötet keinen Erreger ab, und gegen Viren wirken Antibiotika ohnehin nicht. Auch zerstört der Impfstoff keine Virushülle im Körper; die Abwehr bleibt nötig, sie wird nur vorbereitet.","coreRule":"⚡ Wer eine Aussage über Impfstoffe prüft, fragt zuerst: Was wird tatsächlich gespritzt, der ganze aktive Erreger oder nur ein „Fahndungsfoto“?","beleg":"Werkstück C.4.2 (Kontext & Tiefe, „Impfungen“; Anwendung & Relevanz, „In der Impfdebatte“; Red Flags)","status":"entwurf","scenario":"","quote":"","quoteLabel":"","kurz":"Gespritzt wird in aller Regel nicht der voll aktive Erreger, sondern etwa harmlose Bestandteile oder abgeschwächte bzw. abgetötete Erreger, an denen das Immunsystem den Eindringling kennenlernt. Der Fehler liegt darin, „Impfstoff“ mit „voll aktivem Erreger“ gleichzusetzen.","prueffrage":"Erkranken Geimpfte nach der Spritze an der Krankheit, gegen die sie geimpft wurden, und wie oft kommt das vor?","rueckmeldung":[{"option":0,"text":"Dass eine Impfung eine Immunreaktion auslöst, stimmt. Gespritzt wird aber nicht der voll aktive Erreger, sondern etwa harmlose Bestandteile oder abgeschwächte bzw. abgetötete Erreger, die in aller Regel keine Krankheit auslösen."},{"option":2,"text":"Den Erreger gleich abzutöten, wirkt beruhigend. Eine Impfung tötet aber keinen Erreger ab, sondern bereitet das Immunsystem auf ihn vor, und gegen Viren wirken Antibiotika ohnehin nicht."},{"option":3,"text":"Die Vorstellung, die Impfung mache den Erreger direkt harmlos, wirkt einleuchtend. Zerstört wird aber keine Virushülle im Körper; der Impfstoff liefert dem Immunsystem ein Erkennungsmerkmal zum Lernen, die Abwehr bleibt nötig."}],"familie":"genau-unterscheiden","fertigkeit":"F1"},{"id":"qx-c1-059","clusterId":"C","werkstueckRef":"C.4.2","stufe":3,"question":"Welcher Einwand trifft den Kern, warum diese Werbung unglaubwürdig ist?","options":["Viren vermehren sich in lebenden Körperzellen und haben keine eigene Zellwand und keinen eigenen Stoffwechsel; ein Mittel muss daher in die befallene Zelle hineinwirken, ohne diese Zelle zu schädigen, was Nebenwirkungen schwer vermeidbar macht.","Viren sind deutlich größer als Bakterien und lassen sich deshalb mit kleinen Wirkstoffmolekülen schlechter erreichen und zerstören, was jede gezielte Wirkung unwahrscheinlich macht.","Viren besitzen eine besonders feste Zellwand, die kein Wirkstoff durchdringt, während die Wände von Bakterien leicht zu zerstören sind, weshalb gezielte Mittel gegen Viren nicht möglich sind.","Viren werden vom Immunsystem nicht als Eindringlinge erkannt, sodass ein Mittel die Abwehr komplett ersetzen müsste, und das ist technisch kaum machbar, weshalb gezielte Mittel gegen Viren unmöglich sind."],"correctIndex":0,"explanation":"Antibiotika sind deshalb so gezielt, weil Bakterien Strukturen haben, die menschliche Zellen nicht besitzen, etwa die Zellwand. Dort kann ein Wirkstoff ansetzen, ohne Körperzellen zu treffen. Viren haben weder Zellwand noch eigenen Stoffwechsel. Sie vermehren sich, indem sie eine lebende Wirtszelle umprogrammieren. Ein antivirales Mittel muss deshalb in die bereits infizierte Zelle gelangen und dort die Vermehrung des Virus stören, ohne die Wirtszelle zu sehr zu schädigen. Solche Mittel sind viel schwieriger zu entwickeln als Antibiotika, deshalb ist das Versprechen „genauso gezielt, ganz ohne Nebenwirkungen“ nicht plausibel. Die anderen Einwände stützen sich auf Behauptungen, die nicht stimmen: Viren sind viel kleiner als Bakterien, sie haben keine Zellwand, und für das Immunsystem sind auch Viren Eindringlinge, deren Erkennung Impfungen trainieren.","coreRule":"⚡ Gegen Bakterien gibt es Angriffsflächen von außen, gegen Viren muss man in die gekaperte Zelle hinein. Bei Heilversprechen prüfst du deshalb zuerst, ob ein plausibler Mechanismus erklärt wird.","beleg":"Werkstück C.4.2 (Kontext & Tiefe, „Antivirale Medikamente“; „Wie man sie bekämpft“)","status":"entwurf","scenario":"Ein Pharmakonzern wirbt für ein neues Mittel: „Wirkt gegen Viren genauso gezielt wie gängige Antibiotika gegen Bakterien, und das ganz ohne Nebenwirkungen.“","kurz":"Antibiotika treffen Strukturen, die Körperzellen nicht haben; Viren dagegen vermehren sich in der Körperzelle selbst, ein Mittel muss also dort wirken, ohne sie zu schädigen. Deshalb ist „genauso gezielt, ganz ohne Nebenwirkungen“ nicht plausibel.","prueffrage":"Haben gängige Antibiotika selbst Nebenwirkungen, und gibt es bereits zugelassene Mittel gegen Viren?","rueckmeldung":[{"option":1,"text":"Dass Mittel gegen Viren schwerer zu entwickeln sind, stimmt, doch an der Größe liegt das nicht: Viren sind viel kleiner als Bakterien. Entscheidend ist, dass sie sich in lebenden Körperzellen vermehren."},{"option":2,"text":"Die Zellwand ist bei Bakterien tatsächlich ein wichtiger Angriffspunkt. Viren haben aber gar keine Zellwand, auch keine feste, und unmöglich sind Mittel gegen sie nicht, nur deutlich schwieriger zu entwickeln."},{"option":3,"text":"Hier steckt eine falsche Voraussetzung: Auch Viren gelten dem Immunsystem als Eindringlinge, und Impfungen trainieren genau diese Erkennung. Ein Mittel müsste die Abwehr also nicht ersetzen, und „unmöglich“ ist zu absolut."}],"familie":"genau-unterscheiden","fertigkeit":"F1"},{"id":"qx-c1-060","clusterId":"C","werkstueckRef":"C.4.2","stufe":4,"question":"Ein Bekannter sagt: „Ich lasse mich nicht mit mRNA impfen. Die verändert doch mein Erbgut.“ Welche Rückfrage prüft diese Befürchtung am besten?","options":["Was genau bringt der Impfstoff in die Körperzellen: den Bauplan für ein Virusprotein, das die Zellen vorübergehend selbst herstellen, oder etwas, das ins Erbgut eingebaut wird?","Wie viele Menschen im Umfeld des Bekannten hatten nach der Impfung Beschwerden und stehen dem Impfstoff deshalb skeptisch gegenüber?","Wie lange sind mRNA-Impfstoffe schon auf dem Markt, und wie viele Hersteller bieten solche Präparate inzwischen weltweit an?","Was berichten Menschen im Internet über ihre persönlichen Erfahrungen mit der Impfung, die sie für eine Veränderung ihres Erbguts halten?"],"correctIndex":0,"explanation":"Die Sorge hängt an einer Sachfrage: Was bringt der Impfstoff in die Zelle, und was geschieht damit? mRNA ist eine Arbeitsanweisung für die Herstellung eines Proteins. Die Körperzellen bauen daraufhin ein Oberflächenprotein des Virus, das dem Immunsystem als „Fahndungsfoto“ dient. Das vorübergehende Ablesen eines Bauplans ist etwas ganz anderes als ein Eingriff ins Erbgut, und Fachleute sehen übereinstimmend keine Gefahr für das menschliche Erbgut. Wer so nachfragt, prüft die Behauptung an ihrem Mechanismus. Die anderen Rückfragen drehen sich um Beschwerden einzelner Personen, Marktdaten oder Meinungen im Netz. Sie sagen nichts darüber, ob der behauptete Mechanismus überhaupt existiert.","coreRule":"⚡ Prüfe eine Befürchtung zuerst am behaupteten Mechanismus: Was passiert in der Zelle tatsächlich? mRNA liefert den Bauplan für ein Protein, nicht für Veränderungen am Erbgut.","beleg":"Werkstück C.4.2 (Anwendung & Relevanz, „In der Impfdebatte“); Fn. gl-c-mrna (Kuhrt/Oude-Aost/Betsch 2021, Fakten-Check Impfen; Verweis auf Band II, Sektion II.3.2)","status":"entwurf","scenario":"Im Gespräch über die Corona-Impfung äußert ein Bekannter seine Sorge, ein mRNA-Impfstoff greife ins Erbgut ein.","kurz":"Die Sorge lässt sich nur an der Sache prüfen: Was gelangt in die Zelle, und was passiert damit? mRNA ist ein Bauplan, der vorübergehend abgelesen wird, kein Eingriff ins Erbgut. Beschwerden, Marktdaten und Netzmeinungen sagen darüber nichts.","prueffrage":"Welche Untersuchungen gibt es dazu, ob Geimpfte ein verändertes Erbgut haben, und was zeigen sie?","rueckmeldung":[{"option":1,"text":"Beschwerden im Umfeld können Skepsis erklären, und Nebenwirkungen sind ein ernstes Thema für sich. Ob der Impfstoff ins Erbgut eingreift, klären sie aber nicht: Einzelne Beschwerden sagen nichts über den behaupteten Mechanismus."},{"option":2,"text":"Wie lange es mRNA-Impfstoffe gibt und wie viele Firmen sie herstellen, ist eine Frage des Marktes. Ob ein Eingriff ins Erbgut stattfindet, entscheidet sich aber nicht an Zeitraum oder Herstellerzahl, sondern daran, was in der Zelle geschieht."},{"option":3,"text":"Erfahrungsberichte im Netz zeigen, was Menschen erleben und glauben, aber nicht, was in ihren Zellen tatsächlich passiert. Wer gezielt jene fragt, die schon an eine Erbgutveränderung glauben, hört zudem vor allem Bestätigung."}],"familie":"mechanismus-verlangen","fertigkeit":"F1"}]`);export{t as n,n as t};